insert into public.lessons (level, seq, theme, content, status, model) values
  ('A1', 1, 'Bonjour ! Se présenter', '{"level":"A1","seq":1,"theme":"Bonjour ! Se présenter","vocabulary":[{"fr":"bonjour","en":"hello / good morning","example":"Bonjour, je m''appelle Léa."},{"fr":"au revoir","en":"goodbye","example":"Au revoir et à demain !"},{"fr":"s''appeler","en":"to be called","example":"Comment tu t''appelles ?"},{"fr":"habiter","en":"to live","example":"J''habite à Lagos."},{"fr":"le pays","en":"the country","example":"Quel est ton pays ?"},{"fr":"la ville","en":"the town / city","example":"Paris est une grande ville."},{"fr":"étudiant / étudiante","en":"student","example":"Je suis étudiante."},{"fr":"enchanté(e)","en":"nice to meet you","example":"Enchanté, Marc !"}],"grammar":{"topic":"Le verbe être et les pronoms sujets","explanation":"Subject pronouns: je (I), tu (you, informal), il / elle / on (he / she / one), nous (we), vous (you, formal or plural), ils / elles (they).\nThe verb être (to be) is irregular: je suis, tu es, il/elle est, nous sommes, vous êtes, ils/elles sont.\nUse it for nationality, profession and description. No article before a profession: « Je suis médecin. »","examples":["Je suis nigérian.","Tu es étudiante ?","Nous sommes à Paris.","Ils sont professeurs."]},"text":{"title":"Au cours de français","body":"Bonjour ! Je m''appelle Amara. Je suis nigériane et j''habite à Abuja. Je suis étudiante en informatique. Dans mon cours de français, il y a Paul. Il est canadien. Il habite à Montréal, mais il est à Abuja pour le travail. Nous sommes amis.","questions":[{"id":"tq1","question":"Où habite Amara ?","options":["à Montréal","à Abuja","à Paris","à Lagos"],"answer":"à Abuja","explanation":"« J''habite à Abuja. »"},{"id":"tq2","question":"Quelle est la nationalité de Paul ?","options":["nigériane","française","belge","canadienne"],"answer":"canadienne","explanation":"« Il est canadien. »"}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"Nous ___ étudiants.","options":["sommes","sont","est","êtes"],"answer":"sommes","accepted":[],"explanation":"Être with nous: nous sommes.","tag":"etre","id":"ex1"},{"type":"fill_blank","skill":"grammar","prompt":"Vous ___ professeur ?","options":[],"answer":"êtes","accepted":["etes"],"explanation":"Être with vous: vous êtes.","tag":"etre","id":"ex2"},{"type":"mcq","skill":"vocabulary","prompt":"« Comment tu t''appelles ? » — « ___ Marc. »","options":["Tu t''appelles","Il s''appelle","Je m''appelle","Je suis appelle"],"answer":"Je m''appelle","accepted":[],"explanation":"Answer with je m''appelle + name.","tag":"s-appeler","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["Je","étudiant","Lyon","à","suis"],"answer":"Je suis étudiant à Lyon","accepted":[],"explanation":"Subject + verb + complement.","tag":"word-order","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"She is Nigerian and she lives in Lagos.\"","options":[],"answer":"Elle est nigériane et elle habite à Lagos.","accepted":["Elle est nigériane et habite à Lagos."],"explanation":"Nationality adjectives agree: nigérian → nigériane. Use à before a city.","tag":"etre","id":"ex5"}],"writing_prompt":"Présentez-vous en 3 ou 4 phrases : votre nom, votre nationalité, votre ville et votre profession.","writing_model":"Bonjour ! Je m''appelle Benjamin. Je suis nigérian et j''habite à Lagos. Je suis ingénieur. J''apprends le français.","writing_checklist":["Je m''appelle + prénom","Je suis + nationalité (accord masculin/féminin)","J''habite à + ville","Je suis + profession (sans article)"],"email_snippet":{"word_of_day":{"fr":"bonjour","en":"hello / good morning","example":"Bonjour, je m''appelle Léa."},"mini_question":{"prompt":"Nous ___ étudiants.","options":["sommes","sont","est","êtes"],"answer":"sommes"}}}'::jsonb, 'approved', 'curriculum'),
  ('A1', 2, 'Ma famille', '{"level":"A1","seq":2,"theme":"Ma famille","vocabulary":[{"fr":"la mère","en":"the mother","example":"Ma mère est infirmière."},{"fr":"le père","en":"the father","example":"Mon père travaille à Kano."},{"fr":"le frère","en":"the brother","example":"J''ai un frère."},{"fr":"la sœur","en":"the sister","example":"Ma sœur a dix ans."},{"fr":"les parents","en":"the parents","example":"Mes parents habitent à Ibadan."},{"fr":"le fils / la fille","en":"the son / the daughter","example":"Leur fille s''appelle Aïcha."},{"fr":"le mari / la femme","en":"the husband / the wife","example":"Sa femme est française."},{"fr":"les grands-parents","en":"the grandparents","example":"Mes grands-parents sont gentils."}],"grammar":{"topic":"Le verbe avoir et les adjectifs possessifs","explanation":"Avoir (to have): j''ai, tu as, il/elle a, nous avons, vous avez, ils/elles ont.\nPossessive adjectives agree with the thing owned, not the owner:\n• my: mon (m.), ma (f.), mes (pl.)\n• your: ton, ta, tes\n• his/her: son, sa, ses\nBefore a feminine noun starting with a vowel, use mon/ton/son: mon amie.","examples":["J''ai deux sœurs.","Ma mère et mon père sont à Lagos.","Tu as tes clés ?","Son amie est sympa."]},"text":{"title":"La famille de Chidi","body":"Je m''appelle Chidi. J''ai une grande famille. Mon père s''appelle Emeka et ma mère s''appelle Ngozi. J''ai deux frères et une sœur. Ma sœur a douze ans. Mes grands-parents habitent avec nous. Le dimanche, nous mangeons ensemble.","questions":[{"id":"tq1","question":"Combien de frères a Chidi ?","options":["un","zéro","trois","deux"],"answer":"deux","explanation":"« J''ai deux frères et une sœur. »"},{"id":"tq2","question":"Qui habite avec la famille ?","options":["la tante","le cousin","les grands-parents","un ami"],"answer":"les grands-parents","explanation":"« Mes grands-parents habitent avec nous. »"}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"Ils ___ trois enfants.","options":["sont","a","ont","avez"],"answer":"ont","accepted":[],"explanation":"Avoir with ils: ils ont.","tag":"avoir","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"C''est ___ sœur.","options":["le","mon","ma","mes"],"answer":"ma","accepted":[],"explanation":"Sœur is feminine singular → ma.","tag":"possessive-adjectives","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"J''adore ___ amie Fatou. (my)","options":[],"answer":"mon","accepted":[],"explanation":"Feminine noun starting with a vowel → mon.","tag":"possessive-adjectives","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["avons","deux","enfants","Nous"],"answer":"Nous avons deux enfants","accepted":[],"explanation":"Subject + avoir + number + noun.","tag":"avoir","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"My parents live in Lagos.\"","options":[],"answer":"Mes parents habitent à Lagos.","accepted":[],"explanation":"Plural noun → mes.","tag":"possessive-adjectives","id":"ex5"}],"writing_prompt":"Décrivez votre famille en 4 phrases.","writing_model":"J''ai une petite famille. Mon père s''appelle David et ma mère s''appelle Grace. J''ai une sœur. Elle a quinze ans.","writing_checklist":["mon / ma / mes selon le nom","avoir pour l''âge : elle a quinze ans","au moins trois membres de la famille"],"email_snippet":{"word_of_day":{"fr":"la mère","en":"the mother","example":"Ma mère est infirmière."},"mini_question":{"prompt":"Ils ___ trois enfants.","options":["sont","a","ont","avez"],"answer":"ont"}}}'::jsonb, 'approved', 'curriculum'),
  ('A1', 3, 'Les nombres et l''âge', '{"level":"A1","seq":3,"theme":"Les nombres et l''âge","vocabulary":[{"fr":"un, deux, trois","en":"one, two, three","example":"J''ai trois chats."},{"fr":"dix","en":"ten","example":"Il est dix heures."},{"fr":"vingt","en":"twenty","example":"J''ai vingt ans."},{"fr":"trente","en":"thirty","example":"Le mois a trente jours."},{"fr":"quarante","en":"forty","example":"Mon père a quarante-cinq ans."},{"fr":"cinquante","en":"fifty","example":"Ça coûte cinquante euros."},{"fr":"l''âge (m.)","en":"age","example":"Quel âge as-tu ?"},{"fr":"le numéro de téléphone","en":"the phone number","example":"Quel est ton numéro de téléphone ?"}],"grammar":{"topic":"Dire son âge avec avoir","explanation":"French uses avoir (not être) for age: « J''ai 25 ans » = I am 25. Always say ans.\nAsk: « Quel âge as-tu ? » / « Quel âge avez-vous ? »\nNumbers 21–69: vingt et un, vingt-deux… trente et un… (et un for 21, 31, 41, 51, 61; hyphens elsewhere).","examples":["J''ai vingt et un ans.","Ma grand-mère a soixante ans.","Quel âge a ton frère ?","Il a trente-quatre ans."]},"text":{"title":"Une fiche d''inscription","body":"Nom : Diallo. Prénom : Moussa. Âge : 34 ans. Nationalité : sénégalaise. Ville : Dakar. Téléphone : 77 45 12 30. Moussa a une femme et deux enfants. Sa fille a huit ans et son fils a cinq ans.","questions":[{"id":"tq1","question":"Quel âge a Moussa ?","options":["24 ans","30 ans","34 ans","43 ans"],"answer":"34 ans","explanation":""},{"id":"tq2","question":"Quel âge a le fils de Moussa ?","options":["cinq ans","deux ans","quatre ans","huit ans"],"answer":"cinq ans","explanation":"« son fils a cinq ans »"}]},"exercises":[{"type":"mcq","skill":"vocabulary","prompt":"Comment dit-on « I am 20 » ?","options":["Je suis vingt.","J''ai vingt ans.","Je suis vingt ans.","J''ai vingt."],"answer":"J''ai vingt ans.","accepted":[],"explanation":"Age uses avoir + ans.","tag":"age","id":"ex1"},{"type":"mcq","skill":"vocabulary","prompt":"31 =","options":["trente et un","trois un","treize","trente-un"],"answer":"trente et un","accepted":[],"explanation":"21, 31, 41, 51, 61 take « et un ».","tag":"numbers","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"Quel âge ___-tu ?","options":[],"answer":"as","accepted":[],"explanation":"Avoir with tu: tu as.","tag":"avoir","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["Ma","ans","a","douze","sœur"],"answer":"Ma sœur a douze ans","accepted":[],"explanation":"Subject + a + number + ans.","tag":"age","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"How old is your brother?\"","options":[],"answer":"Quel âge a ton frère ?","accepted":["Quel âge a votre frère ?","Ton frère a quel âge ?"],"explanation":"Quel âge + avoir + subject.","tag":"age","id":"ex5"}],"writing_prompt":"Écrivez votre âge et l''âge de trois personnes de votre entourage.","writing_model":"J''ai vingt-huit ans. Mon frère a vingt-cinq ans. Ma mère a cinquante-deux ans. Mon ami Tunde a trente ans.","writing_checklist":["avoir + nombre + ans","nombres écrits correctement (traits d''union)","mon / ma selon la personne"],"email_snippet":{"word_of_day":{"fr":"un, deux, trois","en":"one, two, three","example":"J''ai trois chats."},"mini_question":{"prompt":"Comment dit-on « I am 20 » ?","options":["Je suis vingt.","J''ai vingt ans.","Je suis vingt ans.","J''ai vingt."],"answer":"J''ai vingt ans."}}}'::jsonb, 'approved', 'curriculum'),
  ('A1', 4, 'En ville', '{"level":"A1","seq":4,"theme":"En ville","vocabulary":[{"fr":"la banque","en":"the bank","example":"La banque est fermée."},{"fr":"la gare","en":"the train station","example":"La gare est loin."},{"fr":"le marché","en":"the market","example":"Il y a un marché le samedi."},{"fr":"l''hôpital (m.)","en":"the hospital","example":"L''hôpital est en face."},{"fr":"la pharmacie","en":"the pharmacy","example":"Il y a une pharmacie ici ?"},{"fr":"l''école (f.)","en":"the school","example":"L''école est à côté du parc."},{"fr":"le restaurant","en":"the restaurant","example":"C''est un bon restaurant."},{"fr":"la rue","en":"the street","example":"J''habite dans cette rue."}],"grammar":{"topic":"Les articles et « il y a »","explanation":"Indefinite articles (a / some): un (m.), une (f.), des (pl.).\nDefinite articles (the): le (m.), la (f.), l'' (before a vowel), les (pl.).\nUse il y a to say « there is / there are »: « Il y a une banque. » Negative: « Il n''y a pas de banque. » (un/une/des → de after negation).","examples":["Il y a un marché dans mon quartier.","La pharmacie est ouverte.","Il n''y a pas de gare ici.","Les restaurants sont chers."]},"text":{"title":"Mon quartier","body":"J''habite dans un quartier animé. Dans ma rue, il y a une boulangerie, une pharmacie et deux restaurants. L''école est à côté du parc. Il y a un grand marché le samedi. Mais il n''y a pas de gare : pour prendre le train, je vais au centre-ville.","questions":[{"id":"tq1","question":"Combien de restaurants y a-t-il dans la rue ?","options":["un","trois","deux","aucun"],"answer":"deux","explanation":""},{"id":"tq2","question":"Qu''est-ce qu''il n''y a pas dans le quartier ?","options":["une école","un marché","une gare","une pharmacie"],"answer":"une gare","explanation":"« il n''y a pas de gare »"}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"Il y a ___ banque dans la rue.","options":["une","le","un","des"],"answer":"une","accepted":[],"explanation":"Banque is feminine → une.","tag":"articles","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"Il n''y a pas ___ hôpital ici.","options":["un","des","d''","l''"],"answer":"d''","accepted":[],"explanation":"After a negation, un/une/des → de (d'' before a vowel).","tag":"negation-de","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"___ école est à côté du parc. (the)","options":[],"answer":"L''","accepted":["l''"],"explanation":"Le/la → l'' before a vowel.","tag":"articles","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["Il","un","y","a","le","samedi","marché"],"answer":"Il y a un marché le samedi","accepted":[],"explanation":"Il y a + noun + time.","tag":"il-y-a","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"There is a pharmacy in my street.\"","options":[],"answer":"Il y a une pharmacie dans ma rue.","accepted":[],"explanation":"Il y a = there is.","tag":"il-y-a","id":"ex5"}],"writing_prompt":"Décrivez votre quartier : qu''est-ce qu''il y a ? Qu''est-ce qu''il n''y a pas ?","writing_model":"Dans mon quartier, il y a un marché, une école et une église. Il y a aussi deux banques. Il n''y a pas de cinéma.","writing_checklist":["il y a + un / une / des","il n''y a pas de …","au moins quatre lieux"],"email_snippet":{"word_of_day":{"fr":"la banque","en":"the bank","example":"La banque est fermée."},"mini_question":{"prompt":"Il y a ___ banque dans la rue.","options":["une","le","un","des"],"answer":"une"}}}'::jsonb, 'approved', 'curriculum'),
  ('A1', 5, 'La maison', '{"level":"A1","seq":5,"theme":"La maison","vocabulary":[{"fr":"la cuisine","en":"the kitchen","example":"Je mange dans la cuisine."},{"fr":"la chambre","en":"the bedroom","example":"Ma chambre est petite."},{"fr":"la salle de bains","en":"the bathroom","example":"La salle de bains est à droite."},{"fr":"le salon","en":"the living room","example":"Le salon est grand."},{"fr":"la table","en":"the table","example":"Les clés sont sur la table."},{"fr":"le lit","en":"the bed","example":"Le chat dort sur le lit."},{"fr":"la fenêtre","en":"the window","example":"La fenêtre est ouverte."},{"fr":"l''appartement (m.)","en":"the flat / apartment","example":"J''ai un appartement en ville."}],"grammar":{"topic":"Les prépositions de lieu","explanation":"sur (on), sous (under), dans (in), devant (in front of), derrière (behind), entre (between), à côté de (next to), en face de (opposite).\nde + le → du, de + les → des: « à côté du lit », « en face des fenêtres ».","examples":["Le livre est sur la table.","Le chat est sous le lit.","La lampe est à côté du canapé.","La cuisine est en face de la salle de bains."]},"text":{"title":"L''appartement de Sophie","body":"Sophie habite dans un petit appartement. Il y a un salon, une chambre, une cuisine et une salle de bains. Dans le salon, le canapé est devant la fenêtre. La télévision est en face du canapé. Dans la chambre, le lit est entre l''armoire et le bureau.","questions":[{"id":"tq1","question":"Où est le canapé ?","options":["devant la fenêtre","derrière la porte","sous la fenêtre","dans la chambre"],"answer":"devant la fenêtre","explanation":""},{"id":"tq2","question":"Qu''est-ce qu''il y a entre l''armoire et le bureau ?","options":["la télévision","le lit","la table","le canapé"],"answer":"le lit","explanation":""}]},"exercises":[{"type":"mcq","skill":"vocabulary","prompt":"Le chat dort ___ le lit. (under)","options":["devant","sur","dans","sous"],"answer":"sous","accepted":[],"explanation":"sous = under.","tag":"prepositions-place","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"La lampe est à côté ___ canapé.","options":["de le","de la","des","du"],"answer":"du","accepted":[],"explanation":"de + le → du.","tag":"contractions","id":"ex2"},{"type":"fill_blank","skill":"vocabulary","prompt":"Les clés sont ___ la table. (on)","options":[],"answer":"sur","accepted":[],"explanation":"sur = on.","tag":"prepositions-place","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["cuisine","côté","salon","à","du","est","La"],"answer":"La cuisine est à côté du salon","accepted":[],"explanation":"Subject + est + place.","tag":"prepositions-place","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"The book is on the bed.\"","options":[],"answer":"Le livre est sur le lit.","accepted":[],"explanation":"sur = on.","tag":"prepositions-place","id":"ex5"}],"writing_prompt":"Décrivez votre chambre ou votre salon avec au moins quatre prépositions.","writing_model":"Ma chambre est petite. Le lit est à côté de la fenêtre. Il y a une table devant le lit. Mes livres sont sur la table et mes chaussures sont sous le lit.","writing_checklist":["sur / sous / devant / à côté de","du = de + le","il y a pour présenter les objets"],"email_snippet":{"word_of_day":{"fr":"la cuisine","en":"the kitchen","example":"Je mange dans la cuisine."},"mini_question":{"prompt":"Le chat dort ___ le lit. (under)","options":["devant","sur","dans","sous"],"answer":"sous"}}}'::jsonb, 'approved', 'curriculum'),
  ('A1', 6, 'À table !', '{"level":"A1","seq":6,"theme":"À table !","vocabulary":[{"fr":"le pain","en":"bread","example":"Je mange du pain le matin."},{"fr":"le riz","en":"rice","example":"Nous mangeons du riz avec du poulet."},{"fr":"la viande","en":"meat","example":"Il ne mange pas de viande."},{"fr":"le poisson","en":"fish","example":"J''aime le poisson grillé."},{"fr":"les légumes (m.)","en":"vegetables","example":"Les légumes sont bons pour la santé."},{"fr":"le fromage","en":"cheese","example":"Les Français aiment le fromage."},{"fr":"l''eau (f.)","en":"water","example":"Je bois de l''eau."},{"fr":"boire","en":"to drink","example":"Tu bois du café ?"}],"grammar":{"topic":"Les verbes en -er et les articles partitifs","explanation":"Regular -er verbs (manger, aimer, parler): je mange, tu manges, il mange, nous mangeons, vous mangez, ils mangent.\nPartitive articles = « some »: du (m.), de la (f.), de l'' (vowel), des (pl.). « Je mange du pain. »\nAfter aimer / adorer / détester use le, la, les: « J''aime le pain. »\nAfter a negation: pas de: « Je ne mange pas de viande. »","examples":["Je mange du riz.","Elle boit de l''eau.","Nous aimons les légumes.","Il ne boit pas de café."]},"text":{"title":"Les repas de Kofi","body":"Le matin, Kofi mange du pain avec de la confiture et il boit du thé. À midi, il mange du riz, du poisson et des légumes. Il adore le poisson ! Le soir, il mange une soupe. Kofi ne boit pas de soda : il boit de l''eau.","questions":[{"id":"tq1","question":"Que boit Kofi le matin ?","options":["du soda","du thé","du lait","du café"],"answer":"du thé","explanation":""},{"id":"tq2","question":"Qu''est-ce que Kofi ne boit pas ?","options":["de jus","de soda","de thé","d''eau"],"answer":"de soda","explanation":"« Kofi ne boit pas de soda »"}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"Je mange ___ pain.","options":["de la","des","le","du"],"answer":"du","accepted":[],"explanation":"Some bread → du pain (masculine).","tag":"partitive","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"Il ne mange pas ___ viande.","options":["la","du","de","de la"],"answer":"de","accepted":[],"explanation":"After a negation, du / de la / des → de.","tag":"negation-de","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"Nous ___ du riz. (manger)","options":[],"answer":"mangeons","accepted":[],"explanation":"-ger verbs keep e with nous: nous mangeons.","tag":"present-er","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["matin","boit","l''eau","Elle","le","de"],"answer":"Elle boit de l''eau le matin","accepted":[],"explanation":"Subject + verb + partitive + noun + time.","tag":"partitive","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"I like fish but I don''t eat meat.\"","options":[],"answer":"J''aime le poisson mais je ne mange pas de viande.","accepted":["J''aime le poisson, mais je ne mange pas de viande."],"explanation":"aimer + le; negation + de.","tag":"partitive","id":"ex5"}],"writing_prompt":"Qu''est-ce que vous mangez et buvez pendant une journée normale ?","writing_model":"Le matin, je mange du pain et je bois du café. À midi, je mange du riz avec du poulet. Le soir, je mange des légumes. Je ne bois pas d''alcool.","writing_checklist":["du / de la / des pour les quantités","pas de après la négation","verbes en -er bien conjugués"],"email_snippet":{"word_of_day":{"fr":"le pain","en":"bread","example":"Je mange du pain le matin."},"mini_question":{"prompt":"Je mange ___ pain.","options":["de la","des","le","du"],"answer":"du"}}}'::jsonb, 'approved', 'curriculum'),
  ('A1', 7, 'Ma journée', '{"level":"A1","seq":7,"theme":"Ma journée","vocabulary":[{"fr":"se lever","en":"to get up","example":"Je me lève à six heures."},{"fr":"se doucher","en":"to shower","example":"Il se douche le matin."},{"fr":"prendre le petit-déjeuner","en":"to have breakfast","example":"Nous prenons le petit-déjeuner ensemble."},{"fr":"travailler","en":"to work","example":"Elle travaille dans une banque."},{"fr":"rentrer","en":"to go back home","example":"Je rentre à dix-huit heures."},{"fr":"se coucher","en":"to go to bed","example":"Tu te couches tard ?"},{"fr":"le matin / le soir","en":"morning / evening","example":"Le soir, je lis."},{"fr":"Quelle heure est-il ?","en":"What time is it?","example":"Quelle heure est-il ? Il est midi."}],"grammar":{"topic":"L''heure et les verbes pronominaux","explanation":"Time: Il est deux heures. Il est huit heures et demie. Il est midi / minuit. « À sept heures » = at seven.\nReflexive verbs add a pronoun: je me lève, tu te lèves, il/elle se lève, nous nous levons, vous vous levez, ils/elles se lèvent.\nBefore a vowel: me → m'', te → t'', se → s'': « Je m''habille. »","examples":["Je me lève à six heures et demie.","Il est neuf heures.","Nous nous couchons à onze heures.","Elle s''habille vite."]},"text":{"title":"La journée de Fatima","body":"Fatima se lève à six heures. Elle se douche et elle prend le petit-déjeuner à six heures et demie. Elle travaille de huit heures à seize heures dans un hôpital. Elle rentre à dix-sept heures. Le soir, elle prépare le dîner et elle se couche à dix heures.","questions":[{"id":"tq1","question":"À quelle heure Fatima se lève-t-elle ?","options":["à six heures et demie","à six heures","à huit heures","à sept heures"],"answer":"à six heures","explanation":""},{"id":"tq2","question":"Où travaille Fatima ?","options":["dans une banque","à la maison","dans une école","dans un hôpital"],"answer":"dans un hôpital","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"Nous ___ levons à sept heures.","options":["nous","me","vous","se"],"answer":"nous","accepted":[],"explanation":"Nous + nous levons.","tag":"reflexive-verbs","id":"ex1"},{"type":"mcq","skill":"vocabulary","prompt":"Comment dit-on « It''s half past eight » ?","options":["Il est huit heures moins demie.","Il est huit et demi heures.","Il est huit heures et demie.","C''est demi huit."],"answer":"Il est huit heures et demie.","accepted":[],"explanation":"« et demie » after heures.","tag":"time","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"Elle ___ couche à dix heures.","options":[],"answer":"se","accepted":[],"explanation":"Il / elle → se.","tag":"reflexive-verbs","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["à","me","lève","Je","six","heures"],"answer":"Je me lève à six heures","accepted":[],"explanation":"Subject + reflexive pronoun + verb.","tag":"reflexive-verbs","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"I go to bed at eleven o''clock.\"","options":[],"answer":"Je me couche à onze heures.","accepted":["Je me couche à 23 heures."],"explanation":"se coucher = to go to bed.","tag":"reflexive-verbs","id":"ex5"}],"writing_prompt":"Racontez votre journée typique avec les heures.","writing_model":"Je me lève à six heures. Je me douche et je prends le petit-déjeuner. Je travaille de huit heures à dix-sept heures. Je rentre à dix-huit heures et je me couche à onze heures.","writing_checklist":["verbes pronominaux : je me lève, je me couche","à + heure","au moins cinq actions dans l''ordre"],"email_snippet":{"word_of_day":{"fr":"se lever","en":"to get up","example":"Je me lève à six heures."},"mini_question":{"prompt":"Nous ___ levons à sept heures.","options":["nous","me","vous","se"],"answer":"nous"}}}'::jsonb, 'approved', 'curriculum'),
  ('A1', 8, 'Les vêtements et les couleurs', '{"level":"A1","seq":8,"theme":"Les vêtements et les couleurs","vocabulary":[{"fr":"la chemise","en":"the shirt","example":"Il porte une chemise blanche."},{"fr":"le pantalon","en":"the trousers","example":"J''achète un pantalon noir."},{"fr":"la robe","en":"the dress","example":"Elle a une belle robe rouge."},{"fr":"les chaussures (f.)","en":"the shoes","example":"Mes chaussures sont neuves."},{"fr":"porter","en":"to wear","example":"Tu portes un chapeau ?"},{"fr":"blanc / blanche","en":"white","example":"Une voiture blanche."},{"fr":"vert / verte","en":"green","example":"Des yeux verts."},{"fr":"cher / chère","en":"expensive","example":"Cette robe est chère."}],"grammar":{"topic":"L''accord des adjectifs","explanation":"Adjectives agree with the noun: add -e for feminine, -s for plural: un pantalon noir, une robe noire, des chaussures noires.\nIf the adjective already ends in -e, no change in the feminine: rouge, jaune.\nIrregular: blanc → blanche, beau → belle, cher → chère.\nMost colours come after the noun: une chemise bleue.","examples":["une jupe verte","des chaussures blanches","un beau manteau","Elle porte une belle robe."]},"text":{"title":"Au magasin","body":"Aujourd''hui, Lucie cherche une tenue pour un mariage. Elle essaie une robe verte, mais elle est trop petite. Ensuite, elle trouve une robe bleue très élégante. Elle achète aussi des chaussures blanches. La robe coûte 60 euros : ce n''est pas trop cher !","questions":[{"id":"tq1","question":"Pourquoi Lucie n''achète-t-elle pas la robe verte ?","options":["Elle est trop chère.","Elle est trop petite.","Elle est trop grande.","Elle n''aime pas le vert."],"answer":"Elle est trop petite.","explanation":""},{"id":"tq2","question":"Qu''est-ce que Lucie achète ?","options":["une robe bleue et des chaussures blanches","des chaussures bleues","une chemise blanche","une robe verte"],"answer":"une robe bleue et des chaussures blanches","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"une chemise ___","options":["blancs","blanches","blanc","blanche"],"answer":"blanche","accepted":[],"explanation":"Feminine singular → blanche.","tag":"adjective-agreement","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"des pantalons ___","options":["noirs","noire","noir","noires"],"answer":"noirs","accepted":[],"explanation":"Masculine plural → noirs.","tag":"adjective-agreement","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"C''est une ___ robe. (beau)","options":[],"answer":"belle","accepted":[],"explanation":"beau → belle in the feminine.","tag":"adjective-agreement","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["une","Il","chemise","bleue","porte"],"answer":"Il porte une chemise bleue","accepted":[],"explanation":"Colour adjectives go after the noun.","tag":"adjective-position","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"She is wearing green shoes.\"","options":[],"answer":"Elle porte des chaussures vertes.","accepted":[],"explanation":"Feminine plural → vertes.","tag":"adjective-agreement","id":"ex5"}],"writing_prompt":"Décrivez ce que vous portez aujourd''hui (vêtements et couleurs).","writing_model":"Aujourd''hui, je porte une chemise bleue, un pantalon noir et des chaussures marron. J''ai aussi une montre grise.","writing_checklist":["accord des couleurs (féminin / pluriel)","adjectif de couleur après le nom","porter conjugué"],"email_snippet":{"word_of_day":{"fr":"la chemise","en":"the shirt","example":"Il porte une chemise blanche."},"mini_question":{"prompt":"une chemise ___","options":["blancs","blanches","blanc","blanche"],"answer":"blanche"}}}'::jsonb, 'approved', 'curriculum'),
  ('A1', 9, 'Les loisirs', '{"level":"A1","seq":9,"theme":"Les loisirs","vocabulary":[{"fr":"faire du sport","en":"to do sport","example":"Je fais du sport le samedi."},{"fr":"jouer au football","en":"to play football","example":"Ils jouent au football au parc."},{"fr":"nager","en":"to swim","example":"Elle nage très bien."},{"fr":"lire","en":"to read","example":"Il aime lire le soir."},{"fr":"écouter de la musique","en":"to listen to music","example":"J''écoute de la musique dans le bus."},{"fr":"regarder un film","en":"to watch a film","example":"Nous regardons un film."},{"fr":"danser","en":"to dance","example":"Tu aimes danser ?"},{"fr":"le week-end","en":"the weekend","example":"Le week-end, je me repose."}],"grammar":{"topic":"Le verbe faire et la négation ne… pas","explanation":"Faire: je fais, tu fais, il fait, nous faisons, vous faites, ils font.\nfaire du / de la / de l'' + activity: faire du vélo, faire de la natation.\njouer au / à la + sport; jouer du / de la + instrument.\nNegation surrounds the verb: ne + verb + pas. ne → n'' before a vowel: « Je n''aime pas le sport. »","examples":["Je fais du vélo le dimanche.","Elle joue de la guitare.","Nous ne regardons pas la télé.","Il n''aime pas danser."]},"text":{"title":"Le week-end de Yao","body":"Le samedi matin, Yao fait du sport : il joue au basket avec ses amis. L''après-midi, il lit ou il écoute de la musique. Le soir, il regarde un film avec sa sœur. Le dimanche, il ne fait pas de sport : il se repose et il joue de la guitare.","questions":[{"id":"tq1","question":"Quel sport fait Yao ?","options":["le football","le tennis","le basket","la natation"],"answer":"le basket","explanation":""},{"id":"tq2","question":"Que fait Yao le dimanche ?","options":["Il nage.","Il travaille.","Il joue au basket.","Il se repose et joue de la guitare."],"answer":"Il se repose et joue de la guitare.","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"Vous ___ du sport ?","options":["fais","font","faisez","faites"],"answer":"faites","accepted":[],"explanation":"Faire with vous: vous faites (irregular).","tag":"faire","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"Il joue ___ piano.","options":["le","de la","au","du"],"answer":"du","accepted":[],"explanation":"Instruments: jouer du / de la.","tag":"jouer-a-de","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"Je ___ aime pas le football.","options":[],"answer":"n''","accepted":["n"],"explanation":"ne → n'' before a vowel.","tag":"negation","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["ne","regardons","télévision","Nous","la","pas"],"answer":"Nous ne regardons pas la télévision","accepted":[],"explanation":"ne + verb + pas.","tag":"negation","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"They play football on Saturdays.\"","options":[],"answer":"Ils jouent au football le samedi.","accepted":["Elles jouent au football le samedi.","Ils jouent au foot le samedi."],"explanation":"jouer au + sport; le samedi = every Saturday.","tag":"jouer-a-de","id":"ex5"}],"writing_prompt":"Qu''est-ce que vous aimez faire le week-end ? Qu''est-ce que vous n''aimez pas faire ?","writing_model":"Le week-end, j''aime faire du vélo et regarder des films. Je joue aussi au football avec mes amis. Je n''aime pas faire le ménage !","writing_checklist":["faire du / de la","jouer au + sport","une phrase négative avec ne… pas"],"email_snippet":{"word_of_day":{"fr":"faire du sport","en":"to do sport","example":"Je fais du sport le samedi."},"mini_question":{"prompt":"Vous ___ du sport ?","options":["fais","font","faisez","faites"],"answer":"faites"}}}'::jsonb, 'approved', 'curriculum'),
  ('A1', 10, 'Le temps et le calendrier', '{"level":"A1","seq":10,"theme":"Le temps et le calendrier","vocabulary":[{"fr":"lundi, mardi, mercredi…","en":"Monday, Tuesday, Wednesday…","example":"Le cours est mardi."},{"fr":"janvier, février…","en":"January, February…","example":"Mon anniversaire est en mars."},{"fr":"la saison","en":"the season","example":"L''été est ma saison préférée."},{"fr":"il fait chaud","en":"it''s hot","example":"En avril, il fait chaud à Lagos."},{"fr":"il fait froid","en":"it''s cold","example":"En hiver, il fait froid à Paris."},{"fr":"il pleut","en":"it''s raining","example":"Il pleut beaucoup en juillet."},{"fr":"le soleil","en":"the sun","example":"Il y a du soleil aujourd''hui."},{"fr":"l''anniversaire (m.)","en":"the birthday","example":"Bon anniversaire !"}],"grammar":{"topic":"La météo et les dates","explanation":"Weather uses il: il fait beau / chaud / froid; il pleut; il neige; il y a du vent / du soleil.\nDates: le + number + month: le 14 juillet (but le premier mai for the 1st).\nMonths and seasons: en janvier, en été, en automne, en hiver — but au printemps.\nDays and months take no capital letter in French.","examples":["Aujourd''hui, il fait beau.","Mon anniversaire, c''est le premier octobre.","Au printemps, il pleut souvent.","En décembre, il fait froid à Montréal."]},"text":{"title":"Deux climats","body":"Awa habite à Dakar. Chez elle, il fait chaud presque toute l''année. De juillet à octobre, il pleut souvent. Son cousin Julien habite à Québec. En hiver, il fait très froid et il neige beaucoup. Julien adore l''été parce qu''il fait beau et il y a du soleil.","questions":[{"id":"tq1","question":"Quand pleut-il souvent à Dakar ?","options":["de juillet à octobre","toute l''année","en hiver","en janvier"],"answer":"de juillet à octobre","explanation":""},{"id":"tq2","question":"Pourquoi Julien adore-t-il l''été ?","options":["Il neige.","Il fait beau et il y a du soleil.","Il fait froid.","Il pleut."],"answer":"Il fait beau et il y a du soleil.","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"___ printemps, les fleurs sont belles.","options":["Le","À la","Au","En"],"answer":"Au","accepted":[],"explanation":"Au printemps; en été / automne / hiver.","tag":"seasons","id":"ex1"},{"type":"mcq","skill":"vocabulary","prompt":"Comment dit-on « It''s cold » ?","options":["Il est froid.","C''est froid temps.","Il fait froid.","Il a froid."],"answer":"Il fait froid.","accepted":[],"explanation":"Weather: il fait + adjective.","tag":"weather","id":"ex2"},{"type":"fill_blank","skill":"vocabulary","prompt":"Aujourd''hui, il ___. (rain)","options":[],"answer":"pleut","accepted":[],"explanation":"pleuvoir → il pleut.","tag":"weather","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["froid","Paris","hiver","En","fait","il","à"],"answer":"En hiver il fait froid à Paris","accepted":[],"explanation":"Season + weather + place.","tag":"weather","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"My birthday is on the first of May.\"","options":[],"answer":"Mon anniversaire est le premier mai.","accepted":["Mon anniversaire, c''est le premier mai.","Mon anniversaire est le 1er mai."],"explanation":"Use premier for the 1st.","tag":"dates","id":"ex5"}],"writing_prompt":"Quel temps fait-il chez vous en ce moment ? Quelle est votre saison préférée et pourquoi ?","writing_model":"Aujourd''hui, il fait chaud et il y a du soleil. Ma saison préférée est la saison des pluies parce qu''il fait moins chaud. Mon anniversaire est le 5 août.","writing_checklist":["il fait + adjectif / il pleut","en / au + saison","une date : le + nombre + mois"],"email_snippet":{"word_of_day":{"fr":"lundi, mardi, mercredi…","en":"Monday, Tuesday, Wednesday…","example":"Le cours est mardi."},"mini_question":{"prompt":"___ printemps, les fleurs sont belles.","options":["Le","À la","Au","En"],"answer":"Au"}}}'::jsonb, 'approved', 'curriculum'),
  ('A1', 11, 'Au café', '{"level":"A1","seq":11,"theme":"Au café","vocabulary":[{"fr":"un café","en":"a coffee","example":"Un café, s''il vous plaît."},{"fr":"un thé","en":"a tea","example":"Je voudrais un thé au citron."},{"fr":"un jus d''orange","en":"an orange juice","example":"Un jus d''orange pour moi."},{"fr":"un croissant","en":"a croissant","example":"Il prend un croissant."},{"fr":"l''addition (f.)","en":"the bill","example":"L''addition, s''il vous plaît !"},{"fr":"s''il vous plaît","en":"please (formal)","example":"Une table pour deux, s''il vous plaît."},{"fr":"combien ?","en":"how much?","example":"C''est combien ?"},{"fr":"le serveur / la serveuse","en":"the waiter / waitress","example":"La serveuse est très gentille."}],"grammar":{"topic":"Poser des questions et « je voudrais »","explanation":"Three ways to ask a yes/no question:\n1. Intonation: Tu veux un café ?\n2. Est-ce que: Est-ce que tu veux un café ?\n3. Inversion (formal): Voulez-vous un café ?\nQuestion words: où (where), quand (when), combien (how much), qu''est-ce que (what), pourquoi (why).\nTo order politely, use je voudrais (I would like).","examples":["Est-ce que vous avez du thé ?","Je voudrais un croissant, s''il vous plaît.","C''est combien ?","Qu''est-ce que tu prends ?"]},"text":{"title":"Une commande","body":"— Bonjour, madame. Qu''est-ce que vous prenez ?\n— Bonjour ! Je voudrais un café et un croissant, s''il vous plaît.\n— Et pour monsieur ?\n— Pour moi, un jus d''orange. Est-ce que vous avez des sandwichs ?\n— Oui, jambon ou fromage.\n— Un sandwich au fromage, alors. C''est combien ?\n— Ça fait douze euros.","questions":[{"id":"tq1","question":"Que prend la femme ?","options":["un thé","un sandwich au jambon","un jus d''orange","un café et un croissant"],"answer":"un café et un croissant","explanation":""},{"id":"tq2","question":"Combien coûte la commande ?","options":["dix euros","douze euros","vingt euros","deux euros"],"answer":"douze euros","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"___ vous avez du thé vert ?","options":["Qu''est-ce que","Est-ce que","Est-ce","Où"],"answer":"Est-ce que","accepted":[],"explanation":"Est-ce que starts a yes/no question.","tag":"questions","id":"ex1"},{"type":"mcq","skill":"vocabulary","prompt":"Polite way to order:","options":["Donne-moi un thé.","Je voudrais un thé.","Un thé je.","Je veux thé."],"answer":"Je voudrais un thé.","accepted":[],"explanation":"je voudrais = I would like.","tag":"politeness","id":"ex2"},{"type":"fill_blank","skill":"vocabulary","prompt":"___ coûte le croissant ? (how much)","options":[],"answer":"Combien","accepted":["combien"],"explanation":"combien = how much.","tag":"questions","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["s''il","un","voudrais","café","Je","vous","plaît"],"answer":"Je voudrais un café s''il vous plaît","accepted":[],"explanation":"Je voudrais + order + s''il vous plaît.","tag":"politeness","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"Where is the waiter?\"","options":[],"answer":"Où est le serveur ?","accepted":[],"explanation":"où = where.","tag":"questions","id":"ex5"}],"writing_prompt":"Écrivez un petit dialogue au café entre vous et le serveur (4 à 6 répliques).","writing_model":"— Bonjour, qu''est-ce que vous prenez ?\n— Bonjour, je voudrais un thé et un croissant, s''il vous plaît.\n— Très bien. Et avec ça ?\n— C''est tout, merci. C''est combien ?\n— Six euros.","writing_checklist":["je voudrais + commande","une question avec est-ce que ou combien","formules de politesse : bonjour, s''il vous plaît, merci"],"email_snippet":{"word_of_day":{"fr":"un café","en":"a coffee","example":"Un café, s''il vous plaît."},"mini_question":{"prompt":"___ vous avez du thé vert ?","options":["Qu''est-ce que","Est-ce que","Est-ce","Où"],"answer":"Est-ce que"}}}'::jsonb, 'approved', 'curriculum'),
  ('A1', 12, 'Où est la gare ?', '{"level":"A1","seq":12,"theme":"Où est la gare ?","vocabulary":[{"fr":"tout droit","en":"straight ahead","example":"Allez tout droit."},{"fr":"à gauche","en":"on the left / turn left","example":"Tournez à gauche."},{"fr":"à droite","en":"on the right / turn right","example":"La poste est à droite."},{"fr":"le carrefour","en":"the crossroads","example":"Au carrefour, tournez à droite."},{"fr":"traverser","en":"to cross","example":"Traversez la place."},{"fr":"loin / près","en":"far / near","example":"C''est près d''ici ?"},{"fr":"le plan","en":"the map (of a town)","example":"Vous avez un plan de la ville ?"},{"fr":"aller","en":"to go","example":"Je vais à la gare."}],"grammar":{"topic":"Le verbe aller, à + article, et l''impératif","explanation":"Aller: je vais, tu vas, il va, nous allons, vous allez, ils vont.\nà + le → au, à + les → aux; à la and à l'' don''t change: je vais au marché, à la gare, à l''hôpital, aux toilettes.\nImperative (instructions): drop the subject. Tournez à gauche ! Allez tout droit ! (vous) / Tourne à gauche ! (tu: -er verbs drop the final s).","examples":["Je vais au cinéma.","Nous allons à la plage.","Allez tout droit, puis tournez à droite.","Traverse la rue !"]},"text":{"title":"Demander son chemin","body":"— Pardon, monsieur. Où est la gare, s''il vous plaît ?\n— Ce n''est pas loin. Allez tout droit jusqu''au carrefour. Là, tournez à gauche. Traversez la place, et la gare est à droite, en face de la banque.\n— C''est à combien de minutes ?\n— À dix minutes à pied.\n— Merci beaucoup !","questions":[{"id":"tq1","question":"Que faut-il faire au carrefour ?","options":["tourner à gauche","traverser la rue","tourner à droite","aller tout droit"],"answer":"tourner à gauche","explanation":""},{"id":"tq2","question":"Où est la gare ?","options":["à côté de la poste","derrière la place","au carrefour","en face de la banque"],"answer":"en face de la banque","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"Je vais ___ marché.","options":["à le","au","à la","aux"],"answer":"au","accepted":[],"explanation":"à + le → au.","tag":"contractions","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"Ils ___ à la plage.","options":["vont","vais","va","allons"],"answer":"vont","accepted":[],"explanation":"Aller with ils: ils vont.","tag":"aller","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"___ à droite au carrefour. (turn, vous)","options":[],"answer":"Tournez","accepted":["tournez"],"explanation":"Imperative with vous: tournez.","tag":"imperative","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["Allez","droit","à","gauche","tout","tournez","puis"],"answer":"Allez tout droit puis tournez à gauche","accepted":[],"explanation":"Imperative instructions.","tag":"imperative","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"Is the hospital far from here?\"","options":[],"answer":"L''hôpital est loin d''ici ?","accepted":["Est-ce que l''hôpital est loin d''ici ?","Est-ce que l''hôpital est loin ?"],"explanation":"loin de = far from.","tag":"directions","id":"ex5"}],"writing_prompt":"Expliquez à un ami comment aller de chez vous au marché ou à l''arrêt de bus le plus proche.","writing_model":"Sors de la maison et tourne à droite. Va tout droit jusqu''au carrefour. Traverse la rue et tourne à gauche. Le marché est à côté de la pharmacie. C''est à cinq minutes à pied.","writing_checklist":["impératif : va, tourne, traverse","à gauche / à droite / tout droit","au / à la / à l''"],"email_snippet":{"word_of_day":{"fr":"tout droit","en":"straight ahead","example":"Allez tout droit."},"mini_question":{"prompt":"Je vais ___ marché.","options":["à le","au","à la","aux"],"answer":"au"}}}'::jsonb, 'approved', 'curriculum'),
  ('A2', 1, 'Le week-end dernier', '{"level":"A2","seq":1,"theme":"Le week-end dernier","vocabulary":[{"fr":"hier","en":"yesterday","example":"Hier, j''ai travaillé."},{"fr":"le week-end dernier","en":"last weekend","example":"Le week-end dernier, j''ai vu un film."},{"fr":"visiter","en":"to visit (a place)","example":"Nous avons visité le musée."},{"fr":"rendre visite à","en":"to visit (a person)","example":"J''ai rendu visite à ma tante."},{"fr":"acheter","en":"to buy","example":"Elle a acheté une robe."},{"fr":"voir","en":"to see","example":"Tu as vu ce film ?"},{"fr":"faire la fête","en":"to party","example":"Ils ont fait la fête samedi."},{"fr":"se reposer","en":"to rest","example":"Dimanche, je me suis reposé."}],"grammar":{"topic":"Le passé composé avec avoir","explanation":"Passé composé = avoir (present) + past participle. It expresses completed actions in the past.\nParticiples: -er → -é (parler → parlé), -ir → -i (finir → fini), many -re → -u (vendre → vendu).\nCommon irregulars: faire → fait, voir → vu, prendre → pris, avoir → eu, être → été, boire → bu, lire → lu.\nNegation surrounds avoir: « Je n''ai pas vu le film. »","examples":["J''ai mangé au restaurant.","Nous avons fini le travail.","Elle a pris le bus.","Ils n''ont pas vu Paul."]},"text":{"title":"Un samedi bien rempli","body":"Samedi dernier, Ibrahim a fait beaucoup de choses. Le matin, il a joué au football avec ses collègues. À midi, il a déjeuné chez sa sœur et il a rendu visite à ses grands-parents. L''après-midi, il a acheté un cadeau pour l''anniversaire de sa femme. Le soir, ils ont vu un film au cinéma. Il n''a pas eu le temps de se reposer !","questions":[{"id":"tq1","question":"Avec qui Ibrahim a-t-il joué au football ?","options":["avec sa femme","avec ses collègues","avec sa sœur","avec ses grands-parents"],"answer":"avec ses collègues","explanation":""},{"id":"tq2","question":"Pourquoi a-t-il acheté un cadeau ?","options":["pour l''anniversaire de sa femme","pour un collègue","pour Noël","pour sa sœur"],"answer":"pour l''anniversaire de sa femme","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"Hier, nous ___ un bon film.","options":["avons vu","avons voir","avons vus","sommes vu"],"answer":"avons vu","accepted":[],"explanation":"voir → vu, with avoir.","tag":"passe-compose","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"Participe passé de « prendre » :","options":["prené","pris","prit","prendu"],"answer":"pris","accepted":[],"explanation":"prendre → pris.","tag":"past-participles","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"Elle a ___ ses devoirs. (finir)","options":[],"answer":"fini","accepted":[],"explanation":"-ir verbs → -i.","tag":"past-participles","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["fait","Je","les","courses","pas","n''ai"],"answer":"Je n''ai pas fait les courses","accepted":[],"explanation":"ne + avoir + pas + participle.","tag":"passe-compose-negation","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"Last weekend, I visited the museum.\"","options":[],"answer":"Le week-end dernier, j''ai visité le musée.","accepted":["Le week-end dernier j''ai visité le musée."],"explanation":"visiter a place; passé composé with avoir.","tag":"passe-compose","id":"ex5"}],"writing_prompt":"Racontez votre week-end dernier en 5 phrases.","writing_model":"Le week-end dernier, j''ai rendu visite à mes parents. Samedi, nous avons mangé ensemble et nous avons regardé un match. Dimanche, j''ai lu un livre et j''ai fait les courses. Je n''ai pas travaillé.","writing_checklist":["avoir + participe passé","participes irréguliers (fait, vu, lu, pris)","une phrase négative : je n''ai pas…","des marqueurs de temps : samedi, dimanche, le soir"],"email_snippet":{"word_of_day":{"fr":"hier","en":"yesterday","example":"Hier, j''ai travaillé."},"mini_question":{"prompt":"Hier, nous ___ un bon film.","options":["avons vu","avons voir","avons vus","sommes vu"],"answer":"avons vu"}}}'::jsonb, 'approved', 'curriculum'),
  ('A2', 2, 'Un voyage', '{"level":"A2","seq":2,"theme":"Un voyage","vocabulary":[{"fr":"partir","en":"to leave","example":"Nous sommes partis à huit heures."},{"fr":"arriver","en":"to arrive","example":"Elle est arrivée à Accra."},{"fr":"l''avion (m.)","en":"the plane","example":"J''ai pris l''avion pour Paris."},{"fr":"le billet","en":"the ticket","example":"J''ai acheté un billet aller-retour."},{"fr":"la valise","en":"the suitcase","example":"Ma valise est lourde."},{"fr":"l''hôtel (m.)","en":"the hotel","example":"Nous sommes restés à l''hôtel."},{"fr":"descendre","en":"to go down / to get off","example":"Il est descendu du train."},{"fr":"les vacances (f. pl.)","en":"the holidays","example":"Les vacances sont finies."}],"grammar":{"topic":"Le passé composé avec être","explanation":"About 15 verbs of movement / change of state take être: aller, venir, arriver, partir, entrer, sortir, monter, descendre, naître, mourir, rester, tomber, retourner, devenir, revenir.\nWith être, the participle agrees with the subject: il est parti, elle est partie, ils sont partis, elles sont parties.\nAll reflexive verbs also take être (lesson 4).","examples":["Je suis allé à Dakar.","Elle est arrivée hier.","Nous sommes restés une semaine.","Mes sœurs sont venues avec moi."]},"text":{"title":"Vacances à Marrakech","body":"En avril, Clara et sa sœur sont allées à Marrakech. Elles sont parties de Lyon en avion et elles sont arrivées le soir. Elles sont restées dix jours dans un petit hôtel. Un jour, elles sont montées dans les montagnes de l''Atlas. Malheureusement, Clara est tombée et elle s''est fait mal au pied. Elles sont rentrées un peu fatiguées mais très contentes.","questions":[{"id":"tq1","question":"Combien de temps sont-elles restées ?","options":["deux jours","dix jours","un mois","une semaine"],"answer":"dix jours","explanation":""},{"id":"tq2","question":"Qu''est-il arrivé à Clara dans les montagnes ?","options":["Elle a perdu sa valise.","Elle s''est perdue.","Elle est restée à l''hôtel.","Elle est tombée."],"answer":"Elle est tombée.","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"Elle ___ à Paris en mai.","options":["est allée","a allé","a allée","est allé"],"answer":"est allée","accepted":[],"explanation":"aller takes être; feminine → allée.","tag":"passe-compose-etre","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"Nous ___ restés à l''hôtel.","options":["avons","sommes","êtes","sont"],"answer":"sommes","accepted":[],"explanation":"rester takes être.","tag":"passe-compose-etre","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"Mes parents sont ___ hier. (arriver)","options":[],"answer":"arrivés","accepted":[],"explanation":"être + agreement: masculine plural → arrivés.","tag":"past-participle-agreement","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["heures","Ils","partis","à","six","sont"],"answer":"Ils sont partis à six heures","accepted":[],"explanation":"Subject + être + participle + time.","tag":"passe-compose-etre","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"She arrived in Abuja on Monday.\"","options":[],"answer":"Elle est arrivée à Abuja lundi.","accepted":["Elle est arrivée lundi à Abuja."],"explanation":"arriver + être; feminine agreement.","tag":"passe-compose-etre","id":"ex5"}],"writing_prompt":"Racontez un voyage que vous avez fait : où, quand, avec qui, et ce qui s''est passé.","writing_model":"L''année dernière, je suis allé à Accra avec mon frère. Nous sommes partis en bus et nous sommes arrivés le soir. Nous sommes restés cinq jours. Nous avons visité la ville et nous avons mangé du poisson. Nous sommes rentrés contents.","writing_checklist":["être avec aller, partir, arriver, rester, rentrer","accord du participe avec être","avoir avec les autres verbes"],"email_snippet":{"word_of_day":{"fr":"partir","en":"to leave","example":"Nous sommes partis à huit heures."},"mini_question":{"prompt":"Elle ___ à Paris en mai.","options":["est allée","a allé","a allée","est allé"],"answer":"est allée"}}}'::jsonb, 'approved', 'curriculum'),
  ('A2', 3, 'Au marché', '{"level":"A2","seq":3,"theme":"Au marché","vocabulary":[{"fr":"un kilo de","en":"a kilo of","example":"Un kilo de tomates, s''il vous plaît."},{"fr":"une bouteille de","en":"a bottle of","example":"Une bouteille d''eau."},{"fr":"un morceau de","en":"a piece of","example":"Un morceau de fromage."},{"fr":"beaucoup de","en":"a lot of","example":"Il y a beaucoup de monde."},{"fr":"un peu de","en":"a little","example":"Un peu de sel."},{"fr":"le vendeur / la vendeuse","en":"the seller","example":"La vendeuse est sympa."},{"fr":"frais / fraîche","en":"fresh","example":"Le poisson est frais ?"},{"fr":"Ça fait combien ?","en":"How much is it (total)?","example":"Ça fait combien, en tout ?"}],"grammar":{"topic":"Les quantités et le pronom en","explanation":"After expressions of quantity, use de (d'') without article: un kilo de riz, beaucoup d''oranges, assez de pain.\nThe pronoun en replaces de + noun (du, de la, des) and goes before the verb: « Tu veux du pain ? — Oui, j''en veux. »\nKeep the number or quantity at the end: « Tu as des enfants ? — J''en ai deux. »","examples":["Je voudrais deux kilos de bananes.","Il y a assez de lait ?","Des tomates ? J''en prends un kilo.","Je n''en veux pas, merci."]},"text":{"title":"Chez le marchand de légumes","body":"— Bonjour ! Vos tomates sont fraîches ?\n— Oui, elles sont arrivées ce matin. Vous en voulez combien ?\n— J''en voudrais deux kilos. Et vous avez des avocats ?\n— Oui, ils sont mûrs. Je vous en mets quatre ?\n— Parfait. Et un peu de persil, s''il vous plaît.\n— Voilà. Ça fait neuf euros cinquante.","questions":[{"id":"tq1","question":"Combien de kilos de tomates le client achète-t-il ?","options":["un","trois","quatre","deux"],"answer":"deux","explanation":""},{"id":"tq2","question":"Combien d''avocats achète-t-il ?","options":["un","deux","neuf","quatre"],"answer":"quatre","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"Je voudrais un kilo ___ oranges.","options":["d''","les","des","de les"],"answer":"d''","accepted":[],"explanation":"After a quantity: de / d'' without article.","tag":"quantities","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"Tu bois du café ? — Oui, j''___ bois tous les jours.","options":["lui","y","en","le"],"answer":"en","accepted":[],"explanation":"en replaces du + noun.","tag":"pronoun-en","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"Il y a beaucoup ___ monde au marché.","options":[],"answer":"de","accepted":[],"explanation":"beaucoup de + noun.","tag":"quantities","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["deux","kilos","voudrais","J''en"],"answer":"J''en voudrais deux kilos","accepted":[],"explanation":"en before the verb; quantity at the end.","tag":"pronoun-en","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"I would like a bottle of water, please.\"","options":[],"answer":"Je voudrais une bouteille d''eau, s''il vous plaît.","accepted":["Je voudrais une bouteille d''eau s''il vous plaît."],"explanation":"une bouteille de → d'' before a vowel.","tag":"quantities","id":"ex5"}],"writing_prompt":"Écrivez votre liste de courses pour la semaine et un petit dialogue avec un vendeur.","writing_model":"Liste : un kilo de riz, six œufs, une bouteille d''huile, un peu de piment.\n— Bonjour, vous avez des œufs ?\n— Oui, vous en voulez combien ?\n— J''en voudrais six, s''il vous plaît.","writing_checklist":["quantité + de (sans article)","le pronom en avec une quantité","politesse : je voudrais, s''il vous plaît"],"email_snippet":{"word_of_day":{"fr":"un kilo de","en":"a kilo of","example":"Un kilo de tomates, s''il vous plaît."},"mini_question":{"prompt":"Je voudrais un kilo ___ oranges.","options":["d''","les","des","de les"],"answer":"d''"}}}'::jsonb, 'approved', 'curriculum'),
  ('A2', 4, 'Ma routine (au passé)', '{"level":"A2","seq":4,"theme":"Ma routine (au passé)","vocabulary":[{"fr":"se réveiller","en":"to wake up","example":"Je me suis réveillé tard."},{"fr":"s''habiller","en":"to get dressed","example":"Elle s''est habillée vite."},{"fr":"se brosser les dents","en":"to brush one''s teeth","example":"Il se brosse les dents."},{"fr":"se dépêcher","en":"to hurry","example":"Dépêche-toi !"},{"fr":"se promener","en":"to go for a walk","example":"Nous nous sommes promenés au parc."},{"fr":"s''amuser","en":"to have fun","example":"Les enfants se sont bien amusés."},{"fr":"d''habitude","en":"usually","example":"D''habitude, je me lève tôt."},{"fr":"ensuite / puis","en":"then / next","example":"Ensuite, je prends le bus."}],"grammar":{"topic":"Les verbes pronominaux au passé composé","explanation":"Reflexive verbs always use être in the passé composé: je me suis levé(e), tu t''es levé(e), il s''est levé, elle s''est levée, nous nous sommes levé(e)s, vous vous êtes levé(e)(s), ils se sont levés, elles se sont levées.\nThe participle usually agrees with the subject.\nNegation: « Je ne me suis pas réveillé. »\nLinkers for a sequence: d''abord, ensuite, puis, après, enfin.","examples":["Ce matin, je me suis réveillée à sept heures.","Ils se sont promenés sur la plage.","Elle ne s''est pas dépêchée.","D''abord je me suis douché, ensuite je me suis habillé."]},"text":{"title":"Un matin difficile","body":"D''habitude, Martin se lève à six heures. Mais hier, il ne s''est pas réveillé : son téléphone n''a pas sonné ! Il s''est levé à huit heures. Il s''est douché en deux minutes, il s''est habillé et il s''est dépêché pour prendre le bus. Il est arrivé au bureau en retard, mais son chef ne s''est pas fâché.","questions":[{"id":"tq1","question":"Pourquoi Martin ne s''est-il pas réveillé ?","options":["Son téléphone n''a pas sonné.","Il n''a pas de réveil.","Il était malade.","Il s''est couché tard."],"answer":"Son téléphone n''a pas sonné.","explanation":""},{"id":"tq2","question":"Comment a réagi son chef ?","options":["Il est parti.","Il a téléphoné.","Il s''est fâché.","Il ne s''est pas fâché."],"answer":"Il ne s''est pas fâché.","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"Elle ___ habillée en noir.","options":["est","s''a","s''est","a"],"answer":"s''est","accepted":[],"explanation":"Reflexive verbs use être: elle s''est habillée.","tag":"reflexive-passe-compose","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"Nous nous sommes ___ au parc.","options":["promenés","promené","promener","promenez"],"answer":"promenés","accepted":[],"explanation":"Agreement with nous (masculine plural).","tag":"past-participle-agreement","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"Je ne me ___ pas réveillé à l''heure.","options":[],"answer":"suis","accepted":[],"explanation":"je me suis…","tag":"reflexive-passe-compose","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["bien","Ils","amusés","hier","se","sont"],"answer":"Ils se sont bien amusés hier","accepted":[],"explanation":"se + être + adverb + participle.","tag":"reflexive-passe-compose","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"This morning, I woke up at six o''clock.\"","options":[],"answer":"Ce matin, je me suis réveillé à six heures.","accepted":["Ce matin, je me suis réveillée à six heures.","Ce matin je me suis réveillé à six heures."],"explanation":"se réveiller + être.","tag":"reflexive-passe-compose","id":"ex5"}],"writing_prompt":"Racontez votre matinée d''hier dans l''ordre (d''abord, ensuite, puis, enfin).","writing_model":"Hier, je me suis réveillé à six heures. D''abord, je me suis douché. Ensuite, je me suis habillé et j''ai pris le petit-déjeuner. Puis je me suis dépêché pour prendre le bus. Enfin, je suis arrivé au travail à huit heures.","writing_checklist":["verbes pronominaux avec être","accord du participe si nécessaire","d''abord, ensuite, puis, enfin"],"email_snippet":{"word_of_day":{"fr":"se réveiller","en":"to wake up","example":"Je me suis réveillé tard."},"mini_question":{"prompt":"Elle ___ habillée en noir.","options":["est","s''a","s''est","a"],"answer":"s''est"}}}'::jsonb, 'approved', 'curriculum'),
  ('A2', 5, 'Mes projets', '{"level":"A2","seq":5,"theme":"Mes projets","vocabulary":[{"fr":"le projet","en":"the plan / project","example":"J''ai un projet pour l''été."},{"fr":"demain","en":"tomorrow","example":"Demain, je vais travailler."},{"fr":"la semaine prochaine","en":"next week","example":"La semaine prochaine, nous allons partir."},{"fr":"l''année prochaine","en":"next year","example":"L''année prochaine, je vais apprendre à conduire."},{"fr":"déménager","en":"to move house","example":"Ils vont déménager à Abuja."},{"fr":"chercher un emploi","en":"to look for a job","example":"Elle va chercher un emploi."},{"fr":"économiser","en":"to save money","example":"Je vais économiser pour un voyage."},{"fr":"bientôt","en":"soon","example":"À bientôt !"}],"grammar":{"topic":"Le futur proche","explanation":"Futur proche = aller (present) + infinitive. It expresses plans and near-future actions: « Je vais partir. »\nNegation surrounds aller: « Je ne vais pas partir. »\nWith reflexive verbs, the pronoun stays before the infinitive: « Je vais me reposer. »","examples":["Ce soir, nous allons regarder un match.","Elle va commencer un nouveau travail.","Ils ne vont pas venir.","Je vais me coucher tôt."]},"text":{"title":"Une nouvelle vie","body":"Kemi va bientôt finir ses études. L''année prochaine, elle va déménager au Canada pour travailler. D''abord, elle va passer un examen de français. Ensuite, elle va chercher un appartement à Montréal. Son frère ne va pas partir avec elle, mais il va lui rendre visite en été.","questions":[{"id":"tq1","question":"Où Kemi va-t-elle déménager ?","options":["en France","au Canada","aux États-Unis","en Belgique"],"answer":"au Canada","explanation":""},{"id":"tq2","question":"Que va faire son frère ?","options":["partir avec elle","lui rendre visite en été","chercher un appartement","passer un examen"],"answer":"lui rendre visite en été","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"Demain, nous ___ visiter le musée.","options":["allons","allez","irons aller","vont"],"answer":"allons","accepted":[],"explanation":"Futur proche: aller + infinitive.","tag":"futur-proche","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"Negative: « Je vais partir. » →","options":["Je vais ne pas partir.","Je ne vais partir pas.","Je pas vais partir.","Je ne vais pas partir."],"answer":"Je ne vais pas partir.","accepted":[],"explanation":"ne… pas around aller.","tag":"futur-proche","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"Ce soir, je vais ___ reposer.","options":[],"answer":"me","accepted":[],"explanation":"Reflexive pronoun before the infinitive.","tag":"futur-proche","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["vont","déménager","prochaine","l''année","Ils"],"answer":"Ils vont déménager l''année prochaine","accepted":[],"explanation":"aller + infinitive + time.","tag":"futur-proche","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"Next week, she is going to look for a job.\"","options":[],"answer":"La semaine prochaine, elle va chercher un emploi.","accepted":["La semaine prochaine, elle va chercher un travail."],"explanation":"aller + infinitive.","tag":"futur-proche","id":"ex5"}],"writing_prompt":"Quels sont vos projets pour les six prochains mois ?","writing_model":"Le mois prochain, je vais commencer un cours de cuisine. En juin, je vais aller à Dakar avec ma famille. Je vais aussi économiser pour acheter une voiture. Je ne vais pas changer de travail.","writing_checklist":["aller + infinitif","marqueurs de futur : demain, le mois prochain","une phrase négative"],"email_snippet":{"word_of_day":{"fr":"le projet","en":"the plan / project","example":"J''ai un projet pour l''été."},"mini_question":{"prompt":"Demain, nous ___ visiter le musée.","options":["allons","allez","irons aller","vont"],"answer":"allons"}}}'::jsonb, 'approved', 'curriculum'),
  ('A2', 6, 'Chez le médecin', '{"level":"A2","seq":6,"theme":"Chez le médecin","vocabulary":[{"fr":"avoir mal à","en":"to have a pain in","example":"J''ai mal à la tête."},{"fr":"la fièvre","en":"fever","example":"Il a de la fièvre."},{"fr":"tousser","en":"to cough","example":"Elle tousse beaucoup."},{"fr":"le médicament","en":"the medicine","example":"Prenez ce médicament trois fois par jour."},{"fr":"l''ordonnance (f.)","en":"the prescription","example":"Le médecin m''a donné une ordonnance."},{"fr":"être enrhumé","en":"to have a cold","example":"Je suis enrhumé."},{"fr":"se reposer","en":"to rest","example":"Il faut vous reposer."},{"fr":"guérir","en":"to get better / to cure","example":"Tu vas vite guérir."}],"grammar":{"topic":"Avoir mal à et « il faut »","explanation":"avoir mal à + body part (with article): j''ai mal à la tête, au dos (à + le), aux dents (à + les), à l''oreille.\nil faut + infinitive = it is necessary to / you must: « Il faut boire de l''eau. »\nNegative: il ne faut pas = you must not.","examples":["J''ai mal au ventre.","Elle a mal aux pieds.","Il faut prendre ce médicament.","Il ne faut pas fumer."]},"text":{"title":"Une consultation","body":"— Bonjour, docteur. Depuis deux jours, j''ai mal à la gorge et je tousse.\n— Vous avez de la fièvre ?\n— Oui, un peu, 38 degrés.\n— Vous avez une angine. Il faut prendre ces médicaments pendant cinq jours. Il faut aussi boire beaucoup d''eau et vous reposer.\n— Je peux aller travailler ?\n— Non, il ne faut pas aller au travail cette semaine.","questions":[{"id":"tq1","question":"Depuis combien de temps le patient est-il malade ?","options":["un jour","deux jours","une semaine","cinq jours"],"answer":"deux jours","explanation":""},{"id":"tq2","question":"Que dit le médecin pour le travail ?","options":["Il ne faut pas y aller cette semaine.","Il faut y aller demain.","Il peut travailler à mi-temps.","Il faut changer de travail."],"answer":"Il ne faut pas y aller cette semaine.","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"J''ai mal ___ dos.","options":["aux","à le","au","à la"],"answer":"au","accepted":[],"explanation":"à + le → au.","tag":"avoir-mal-a","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"J''ai mal ___ dents.","options":["aux","des","à les","au"],"answer":"aux","accepted":[],"explanation":"à + les → aux.","tag":"avoir-mal-a","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"Il ___ boire beaucoup d''eau.","options":[],"answer":"faut","accepted":[],"explanation":"il faut + infinitive.","tag":"il-faut","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["ici","Il","ne","fumer","faut","pas"],"answer":"Il ne faut pas fumer ici","accepted":[],"explanation":"il ne faut pas + infinitive.","tag":"il-faut","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"I have a headache and a fever.\"","options":[],"answer":"J''ai mal à la tête et j''ai de la fièvre.","accepted":["J''ai mal à la tête et de la fièvre."],"explanation":"avoir mal à la tête; avoir de la fièvre.","tag":"avoir-mal-a","id":"ex5"}],"writing_prompt":"Vous êtes malade. Écrivez un message à votre professeur ou à votre chef pour expliquer vos symptômes.","writing_model":"Bonjour Madame Diop, je suis désolé, mais je ne peux pas venir aujourd''hui. J''ai de la fièvre et j''ai mal à la gorge. Le médecin dit qu''il faut me reposer deux jours. Cordialement, Benjamin.","writing_checklist":["avoir mal à + partie du corps","il faut + infinitif","formule d''excuse et de politesse"],"email_snippet":{"word_of_day":{"fr":"avoir mal à","en":"to have a pain in","example":"J''ai mal à la tête."},"mini_question":{"prompt":"J''ai mal ___ dos.","options":["aux","à le","au","à la"],"answer":"au"}}}'::jsonb, 'approved', 'curriculum'),
  ('A2', 7, 'Souvenirs d''enfance', '{"level":"A2","seq":7,"theme":"Souvenirs d''enfance","vocabulary":[{"fr":"quand j''étais petit(e)","en":"when I was little","example":"Quand j''étais petit, j''habitais à Jos."},{"fr":"l''enfance (f.)","en":"childhood","example":"J''ai eu une enfance heureuse."},{"fr":"le village","en":"the village","example":"Mes grands-parents habitaient dans un village."},{"fr":"souvent","en":"often","example":"Nous jouions souvent dehors."},{"fr":"tous les jours","en":"every day","example":"Je marchais à l''école tous les jours."},{"fr":"le jouet","en":"the toy","example":"Mon jouet préféré était un ballon."},{"fr":"gentil / gentille","en":"kind","example":"Ma maîtresse était très gentille."},{"fr":"avoir peur de","en":"to be afraid of","example":"J''avais peur des chiens."}],"grammar":{"topic":"L''imparfait (formation et emploi)","explanation":"Imparfait = nous-form stem (present) without -ons + endings -ais, -ais, -ait, -ions, -iez, -aient.\nnous jouons → je jouais; nous finissons → je finissais; nous faisons → je faisais.\nOnly irregular stem: être → ét- (j''étais).\nUse it for habits, descriptions and situations in the past: « Quand j''étais petit, je jouais au foot tous les jours. »","examples":["Nous habitions près de la mer.","Il faisait toujours beau.","Ma mère travaillait à l''hôpital.","Tu avais un chien ?"]},"text":{"title":"Le village de mon grand-père","body":"Quand mon grand-père était petit, il habitait dans un village au bord d''une rivière. Il n''y avait pas d''électricité. Tous les matins, il allait chercher de l''eau avec ses frères. L''après-midi, les enfants nageaient dans la rivière et jouaient avec des jouets en bois. Le soir, sa grand-mère racontait des histoires. Il dit que c''était une enfance simple mais heureuse.","questions":[{"id":"tq1","question":"Qu''est-ce qu''il n''y avait pas au village ?","options":["d''école","de rivière","d''enfants","d''électricité"],"answer":"d''électricité","explanation":""},{"id":"tq2","question":"Que faisait la grand-mère le soir ?","options":["Elle racontait des histoires.","Elle nageait.","Elle allait chercher de l''eau.","Elle travaillait."],"answer":"Elle racontait des histoires.","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"Quand j''étais petit, je ___ au foot.","options":["joue","ai joué","jouais","jouerai"],"answer":"jouais","accepted":[],"explanation":"Past habit → imparfait.","tag":"imparfait","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"Imparfait de « être » (nous) :","options":["nous êtions","nous étons","nous étions","nous serions"],"answer":"nous étions","accepted":[],"explanation":"être → ét- + -ions.","tag":"imparfait","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"Ils ___ dans un petit village. (habiter)","options":[],"answer":"habitaient","accepted":[],"explanation":"ils → -aient.","tag":"imparfait","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["à","la","tous","allions","plage","Nous","les","dimanches"],"answer":"Nous allions à la plage tous les dimanches","accepted":[],"explanation":"Habit with imparfait + time.","tag":"imparfait","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"When I was a child, I was afraid of dogs.\"","options":[],"answer":"Quand j''étais enfant, j''avais peur des chiens.","accepted":["Quand j''étais petit, j''avais peur des chiens.","Quand j''étais petite, j''avais peur des chiens."],"explanation":"Description in the past → imparfait.","tag":"imparfait","id":"ex5"}],"writing_prompt":"Décrivez votre enfance : où vous habitiez, ce que vous faisiez, ce que vous aimiez.","writing_model":"Quand j''étais petit, j''habitais à Enugu avec mes parents. Notre maison était près d''une école. Tous les après-midi, je jouais au football avec mes voisins. J''adorais les mangues et j''avais peur du noir.","writing_checklist":["imparfait pour les habitudes et descriptions","quand j''étais petit(e)","expressions de fréquence : souvent, tous les jours"],"email_snippet":{"word_of_day":{"fr":"quand j''étais petit(e)","en":"when I was little","example":"Quand j''étais petit, j''habitais à Jos."},"mini_question":{"prompt":"Quand j''étais petit, je ___ au foot.","options":["joue","ai joué","jouais","jouerai"],"answer":"jouais"}}}'::jsonb, 'approved', 'curriculum'),
  ('A2', 8, 'Les achats en ligne', '{"level":"A2","seq":8,"theme":"Les achats en ligne","vocabulary":[{"fr":"commander","en":"to order","example":"J''ai commandé un livre en ligne."},{"fr":"livrer / la livraison","en":"to deliver / delivery","example":"La livraison est gratuite."},{"fr":"le colis","en":"the parcel","example":"Le colis est arrivé."},{"fr":"le site","en":"the website","example":"Ce site est fiable ?"},{"fr":"rembourser","en":"to refund","example":"Ils m''ont remboursé."},{"fr":"la taille","en":"the size","example":"Quelle est votre taille ?"},{"fr":"essayer","en":"to try (on)","example":"Je l''ai essayé, il est trop grand."},{"fr":"renvoyer","en":"to send back","example":"Je vais renvoyer la chemise."}],"grammar":{"topic":"Les pronoms COD : le, la, les","explanation":"Direct object pronouns replace a noun with no preposition: me, te, le, la, nous, vous, les. le/la → l'' before a vowel.\nThey go before the conjugated verb: « Je le prends. » « Tu les as ? »\nIn the passé composé, before avoir: « Je l''ai commandé. » With an infinitive, before the infinitive: « Je vais le renvoyer. »","examples":["Ce pull ? Je le trouve joli.","Mes chaussures ? Je les ai achetées en ligne.","La robe, tu vas la garder ?","Il ne la connaît pas."]},"text":{"title":"Un colis problématique","body":"La semaine dernière, Sarah a commandé une veste sur un site de mode. Le colis est arrivé en trois jours. Elle l''a ouvert tout de suite, mais la veste était trop petite. Elle l''a essayée deux fois, puis elle a décidé de la renvoyer. Le site l''a remboursée rapidement. Maintenant, elle vérifie toujours le guide des tailles.","questions":[{"id":"tq1","question":"Quel était le problème avec la veste ?","options":["Elle était trop petite.","Elle était sale.","Elle était trop chère.","Elle n''est jamais arrivée."],"answer":"Elle était trop petite.","explanation":""},{"id":"tq2","question":"Qu''est-ce que Sarah fait maintenant ?","options":["Elle n''achète plus en ligne.","Elle va au magasin.","Elle achète deux tailles.","Elle vérifie le guide des tailles."],"answer":"Elle vérifie le guide des tailles.","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"Tu prends le bus ? — Oui, je ___ prends.","options":["le","la","lui","les"],"answer":"le","accepted":[],"explanation":"le bus (masculine) → le.","tag":"cod-pronouns","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"Les chaussures ? Je ___ ai achetées hier.","options":["les","leur","en","la"],"answer":"les","accepted":[],"explanation":"les chaussures → les.","tag":"cod-pronouns","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"La veste ? Je vais ___ renvoyer.","options":[],"answer":"la","accepted":[],"explanation":"Pronoun before the infinitive.","tag":"cod-pronouns","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["Je","sur","l''ai","internet","commandé"],"answer":"Je l''ai commandé sur internet","accepted":[],"explanation":"Pronoun before avoir in the passé composé.","tag":"cod-pronouns","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"I bought it online. (the dress)\"","options":[],"answer":"Je l''ai achetée en ligne.","accepted":["Je l''ai achetée sur internet."],"explanation":"la robe → l''; agreement with a preceding direct object.","tag":"cod-pronouns","id":"ex5"}],"writing_prompt":"Racontez un achat (en ligne ou en magasin) : qu''est-ce que vous avez acheté et qu''est-ce que vous en pensez ?","writing_model":"Le mois dernier, j''ai acheté un téléphone en ligne. Je l''ai reçu après une semaine. Je le trouve très pratique et je l''utilise tous les jours. Mes amis le trouvent beau aussi.","writing_checklist":["le / la / les / l'' pour éviter la répétition","pronom avant le verbe conjugué","passé composé"],"email_snippet":{"word_of_day":{"fr":"commander","en":"to order","example":"J''ai commandé un livre en ligne."},"mini_question":{"prompt":"Tu prends le bus ? — Oui, je ___ prends.","options":["le","la","lui","les"],"answer":"le"}}}'::jsonb, 'approved', 'curriculum'),
  ('A2', 9, 'Écrire à un ami', '{"level":"A2","seq":9,"theme":"Écrire à un ami","vocabulary":[{"fr":"envoyer","en":"to send","example":"Je t''envoie une photo."},{"fr":"répondre à","en":"to reply to","example":"Elle répond à ses messages."},{"fr":"téléphoner à","en":"to phone","example":"Je téléphone à ma mère."},{"fr":"donner","en":"to give","example":"Il donne un cadeau à son ami."},{"fr":"prêter","en":"to lend","example":"Tu me prêtes ton livre ?"},{"fr":"demander à","en":"to ask","example":"Demande à ton père."},{"fr":"Bises / Je t''embrasse","en":"Love / Kisses (letter ending)","example":"Bises, à bientôt !"},{"fr":"Cher / Chère","en":"Dear","example":"Chère Amina,"}],"grammar":{"topic":"Les pronoms COI : lui, leur","explanation":"Indirect object pronouns replace à + person: me, te, lui (him / her), nous, vous, leur (them).\nVerbs with à: parler à, téléphoner à, répondre à, donner à, envoyer à, demander à.\nThey go before the verb: « Je lui parle. » « Je leur ai téléphoné. »\nlui is used for both him and her. Don''t confuse leur (pronoun, no s) with leurs (their, plural).","examples":["Je téléphone à Paul → Je lui téléphone.","Elle parle à ses parents → Elle leur parle.","Tu m''envoies le document ?","Je ne lui ai pas répondu."]},"text":{"title":"Un message de Lisbonne","body":"Chère Nadia,\nJe t''écris de Lisbonne ! La ville est magnifique. Hier, j''ai rencontré tes amis portugais : je leur ai donné ton cadeau et ils te remercient. Demain, je vais téléphoner à ta sœur pour lui demander l''adresse du restaurant. Je t''envoie des photos ce soir.\nJe t''embrasse,\nAnna","questions":[{"id":"tq1","question":"Qu''est-ce qu''Anna a donné aux amis portugais ?","options":["le cadeau de Nadia","des photos","une lettre","une adresse"],"answer":"le cadeau de Nadia","explanation":""},{"id":"tq2","question":"Pourquoi Anna va-t-elle téléphoner à la sœur de Nadia ?","options":["pour l''inviter","pour lui envoyer des photos","pour lui donner un cadeau","pour lui demander l''adresse d''un restaurant"],"answer":"pour lui demander l''adresse d''un restaurant","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"Je parle à Marie. → Je ___ parle.","options":["lui","la","leur","le"],"answer":"lui","accepted":[],"explanation":"à + one person → lui.","tag":"coi-pronouns","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"Tu réponds à tes parents ? — Oui, je ___ réponds.","options":["leur","lui","les","leurs"],"answer":"leur","accepted":[],"explanation":"à + several people → leur.","tag":"coi-pronouns","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"Je ___ ai envoyé un message. (to them)","options":[],"answer":"leur","accepted":[],"explanation":"leur = to them.","tag":"coi-pronouns","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["Je","soir","ai","téléphoné","hier","lui"],"answer":"Je lui ai téléphoné hier soir","accepted":[],"explanation":"Pronoun before avoir.","tag":"coi-pronouns","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"I''m going to give him a present.\"","options":[],"answer":"Je vais lui donner un cadeau.","accepted":["Je vais lui offrir un cadeau."],"explanation":"Pronoun before the infinitive.","tag":"coi-pronouns","id":"ex5"}],"writing_prompt":"Écrivez un court message à un ami pour lui raconter une nouvelle et lui demander un service.","writing_model":"Cher Tolu,\nJ''ai une bonne nouvelle : j''ai trouvé un nouveau travail ! Je commence lundi. Est-ce que tu peux me prêter ta valise pour le voyage ? Je te la rends dans deux semaines. Dis bonjour à tes parents et dis-leur merci pour le dîner.\nBises,\nBen","writing_checklist":["Cher / Chère + prénom","lui / leur / te pour éviter la répétition","une formule de fin : Bises, À bientôt"],"email_snippet":{"word_of_day":{"fr":"envoyer","en":"to send","example":"Je t''envoie une photo."},"mini_question":{"prompt":"Je parle à Marie. → Je ___ parle.","options":["lui","la","leur","le"],"answer":"lui"}}}'::jsonb, 'approved', 'curriculum'),
  ('A2', 10, 'Comparer les villes', '{"level":"A2","seq":10,"theme":"Comparer les villes","vocabulary":[{"fr":"grand / petit","en":"big / small","example":"Lagos est plus grande qu''Accra."},{"fr":"peuplé","en":"populated","example":"C''est une ville très peuplée."},{"fr":"bruyant","en":"noisy","example":"Le centre est bruyant."},{"fr":"calme","en":"quiet","example":"Mon quartier est plus calme."},{"fr":"la circulation","en":"traffic","example":"Il y a beaucoup de circulation."},{"fr":"le coût de la vie","en":"the cost of living","example":"Le coût de la vie est élevé à Paris."},{"fr":"agréable","en":"pleasant","example":"C''est une ville agréable."},{"fr":"dangereux / dangereuse","en":"dangerous","example":"Cette route est dangereuse."}],"grammar":{"topic":"Le comparatif et le superlatif","explanation":"Comparative: plus / moins / aussi + adjective + que: « Abuja est plus calme que Lagos. »\nWith nouns: plus de / moins de / autant de + noun + que.\nIrregular: bon → meilleur (better), bien → mieux.\nSuperlative: le / la / les plus + adjective: « la ville la plus peuplée », « le meilleur restaurant ».","examples":["Le train est plus rapide que le bus.","Il y a moins de circulation le dimanche.","Ce restaurant est meilleur que l''autre.","C''est la plus belle plage du pays."]},"text":{"title":"Lagos ou Abuja ?","body":"Tobi a habité à Lagos pendant dix ans, mais maintenant il habite à Abuja. Pour lui, Abuja est plus calme et plus propre que Lagos. Il y a moins de circulation et les routes sont plus larges. Mais Lagos est plus animée : les restaurants sont meilleurs et la vie nocturne est plus intéressante. Selon Tobi, Lagos est la ville la plus dynamique du pays.","questions":[{"id":"tq1","question":"Selon Tobi, quelle ville est plus calme ?","options":["aucune","Abuja","Lagos","les deux"],"answer":"Abuja","explanation":""},{"id":"tq2","question":"Qu''est-ce qui est meilleur à Lagos ?","options":["la propreté","le calme","les routes","les restaurants"],"answer":"les restaurants","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"Ce gâteau est ___ que l''autre. (better)","options":["mieux","plus bon","plus meilleur","meilleur"],"answer":"meilleur","accepted":[],"explanation":"bon → meilleur.","tag":"comparative","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"Il y a ___ voitures à Lagos qu''à Abuja.","options":["plus que","plus de","plus","plus des"],"answer":"plus de","accepted":[],"explanation":"With nouns: plus de + noun.","tag":"comparative","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"C''est la ville ___ plus peuplée du pays.","options":[],"answer":"la","accepted":[],"explanation":"Superlative: la + plus + adjective.","tag":"superlative","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["rapide","plus","est","que","le","train","bus","Le"],"answer":"Le train est plus rapide que le bus","accepted":[],"explanation":"plus + adjective + que.","tag":"comparative","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"My neighbourhood is quieter than the city centre.\"","options":[],"answer":"Mon quartier est plus calme que le centre-ville.","accepted":[],"explanation":"plus + adjective + que.","tag":"comparative","id":"ex5"}],"writing_prompt":"Comparez deux villes que vous connaissez (taille, circulation, coût de la vie, ambiance).","writing_model":"Je connais Ibadan et Lagos. Lagos est plus grande et plus chère qu''Ibadan. Il y a plus de circulation à Lagos. Ibadan est moins bruyante, mais Lagos a les meilleurs restaurants. Pour moi, Ibadan est la ville la plus agréable pour vivre.","writing_checklist":["plus / moins / aussi + adjectif + que","plus de / moins de + nom","un superlatif : le / la plus…"],"email_snippet":{"word_of_day":{"fr":"grand / petit","en":"big / small","example":"Lagos est plus grande qu''Accra."},"mini_question":{"prompt":"Ce gâteau est ___ que l''autre. (better)","options":["mieux","plus bon","plus meilleur","meilleur"],"answer":"meilleur"}}}'::jsonb, 'approved', 'curriculum'),
  ('A2', 11, 'Le logement', '{"level":"A2","seq":11,"theme":"Le logement","vocabulary":[{"fr":"le loyer","en":"the rent","example":"Le loyer est de 500 euros."},{"fr":"le propriétaire","en":"the landlord / owner","example":"Le propriétaire habite à côté."},{"fr":"louer","en":"to rent","example":"Nous louons un appartement."},{"fr":"meublé","en":"furnished","example":"Je cherche un studio meublé."},{"fr":"l''étage (m.)","en":"the floor (storey)","example":"J''habite au troisième étage."},{"fr":"l''ascenseur (m.)","en":"the lift / elevator","example":"Il n''y a pas d''ascenseur."},{"fr":"lumineux / lumineuse","en":"bright","example":"La chambre est lumineuse."},{"fr":"le voisin / la voisine","en":"the neighbour","example":"Mes voisins sont bruyants."}],"grammar":{"topic":"Les pronoms relatifs qui et que","explanation":"Relative pronouns join two sentences.\nqui = subject of the next verb: « C''est un appartement qui a deux chambres. »\nque (qu'') = direct object (followed by a subject + verb): « C''est l''appartement que je loue. »\nque → qu'' before a vowel, but qui never changes.","examples":["J''ai un voisin qui joue du piano.","La maison que nous avons visitée est grande.","C''est une rue qui est très calme.","Le studio qu''il loue est meublé."]},"text":{"title":"Petite annonce","body":"À louer : appartement de 60 m² qui se trouve au deuxième étage d''un immeuble calme, près de la gare. Il a deux chambres lumineuses et une cuisine équipée. Le salon, que les anciens locataires ont repeint, donne sur un jardin. Loyer : 650 euros par mois, charges comprises. Pas d''animaux. Contactez le propriétaire, qui répond le soir.","questions":[{"id":"tq1","question":"À quel étage est l''appartement ?","options":["au deuxième étage","au rez-de-chaussée","au premier étage","au troisième étage"],"answer":"au deuxième étage","explanation":""},{"id":"tq2","question":"Qu''est-ce qui est interdit ?","options":["les enfants","la musique","fumer","les animaux"],"answer":"les animaux","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"C''est un quartier ___ est très animé.","options":["que","qu''","qui","où"],"answer":"qui","accepted":[],"explanation":"Subject of « est » → qui.","tag":"relative-pronouns","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"L''appartement ___ nous louons est petit.","options":["où","qui","dont","que"],"answer":"que","accepted":[],"explanation":"Object of « louons » (subject nous) → que.","tag":"relative-pronouns","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"Le voisin ___ habite en face est médecin.","options":[],"answer":"qui","accepted":[],"explanation":"qui + verb.","tag":"relative-pronouns","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["maison","la","achetée","j''ai","C''est","que"],"answer":"C''est la maison que j''ai achetée","accepted":[],"explanation":"que + subject + verb.","tag":"relative-pronouns","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"I am looking for a flat that has a balcony.\"","options":[],"answer":"Je cherche un appartement qui a un balcon.","accepted":[],"explanation":"qui = subject of « a ».","tag":"relative-pronouns","id":"ex5"}],"writing_prompt":"Décrivez votre logement idéal en utilisant qui et que.","writing_model":"Je voudrais une maison qui est proche de la mer. Elle a un jardin que je peux cultiver et une cuisine qui est grande. Je voudrais des voisins qui sont calmes et un loyer que je peux payer facilement.","writing_checklist":["qui + verbe","que + sujet + verbe","vocabulaire du logement"],"email_snippet":{"word_of_day":{"fr":"le loyer","en":"the rent","example":"Le loyer est de 500 euros."},"mini_question":{"prompt":"C''est un quartier ___ est très animé.","options":["que","qu''","qui","où"],"answer":"qui"}}}'::jsonb, 'approved', 'curriculum'),
  ('A2', 12, 'Les transports', '{"level":"A2","seq":12,"theme":"Les transports","vocabulary":[{"fr":"prendre le bus / le train","en":"to take the bus / train","example":"Je prends le bus tous les jours."},{"fr":"à pied","en":"on foot","example":"Je vais au bureau à pied."},{"fr":"en voiture","en":"by car","example":"Ils voyagent en voiture."},{"fr":"à vélo","en":"by bike","example":"Elle va à l''école à vélo."},{"fr":"l''arrêt (m.) de bus","en":"the bus stop","example":"L''arrêt de bus est en face."},{"fr":"le retard","en":"the delay","example":"Le train a vingt minutes de retard."},{"fr":"les embouteillages (m.)","en":"traffic jams","example":"Il y a des embouteillages le matin."},{"fr":"le trajet","en":"the journey / commute","example":"Mon trajet dure une heure."}],"grammar":{"topic":"Le pronom y et le verbe prendre","explanation":"y replaces a place introduced by à, en, dans, chez…: « Tu vas à la gare ? — Oui, j''y vais. » It goes before the verb.\nprendre: je prends, tu prends, il prend, nous prenons, vous prenez, ils prennent.\nMeans of transport: en bus / en voiture / en train / en avion, but à pied / à vélo / à moto.","examples":["Tu vas à Lagos ? — J''y vais demain.","Nous prenons le métro.","Elle y travaille depuis deux ans.","Je n''y vais jamais en voiture."]},"text":{"title":"Le trajet de Musa","body":"Musa travaille dans le centre-ville. Avant, il y allait en voiture, mais il y avait trop d''embouteillages : son trajet durait une heure et demie ! Maintenant, il prend le train. La gare est à dix minutes de chez lui, alors il y va à pied. Le train a parfois du retard, mais Musa peut lire pendant le trajet.","questions":[{"id":"tq1","question":"Pourquoi Musa ne va-t-il plus au travail en voiture ?","options":["il n''a pas de permis","l''essence est chère","à cause des embouteillages","sa voiture est en panne"],"answer":"à cause des embouteillages","explanation":""},{"id":"tq2","question":"Comment va-t-il à la gare ?","options":["en bus","en taxi","à vélo","à pied"],"answer":"à pied","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"Tu vas au marché ? — Oui, j''___ vais.","options":["en","le","y","lui"],"answer":"y","accepted":[],"explanation":"y replaces à + place.","tag":"pronoun-y","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"Nous ___ le train à huit heures.","options":["prenons","prennons","prenez","prendons"],"answer":"prenons","accepted":[],"explanation":"prendre with nous: prenons.","tag":"prendre","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"Je vais au travail ___ pied.","options":[],"answer":"à","accepted":[],"explanation":"à pied / à vélo.","tag":"transport-prepositions","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["Ils","matins","prennent","tous","bus","les","le"],"answer":"Ils prennent le bus tous les matins","accepted":[],"explanation":"Subject + prendre + transport + time.","tag":"prendre","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"I go there by train.\"","options":[],"answer":"J''y vais en train.","accepted":[],"explanation":"y before the verb; en train.","tag":"pronoun-y","id":"ex5"}],"writing_prompt":"Décrivez votre trajet quotidien : moyen de transport, durée, problèmes.","writing_model":"Je vais au travail en bus. Je prends le bus à sept heures à l''arrêt devant ma maison. Le trajet dure quarante minutes. Le matin, il y a souvent des embouteillages. Le vendredi, j''y vais à pied parce que c''est plus calme.","writing_checklist":["en bus / à pied / à vélo","le pronom y","prendre bien conjugué"],"email_snippet":{"word_of_day":{"fr":"prendre le bus / le train","en":"to take the bus / train","example":"Je prends le bus tous les jours."},"mini_question":{"prompt":"Tu vas au marché ? — Oui, j''___ vais.","options":["en","le","y","lui"],"answer":"y"}}}'::jsonb, 'approved', 'curriculum'),
  ('B1', 1, 'Raconter une histoire', '{"level":"B1","seq":1,"theme":"Raconter une histoire","vocabulary":[{"fr":"soudain / tout à coup","en":"suddenly","example":"Tout à coup, la lumière s''est éteinte."},{"fr":"pendant que","en":"while","example":"Pendant que je cuisinais, il est arrivé."},{"fr":"se rendre compte","en":"to realise","example":"Je me suis rendu compte de mon erreur."},{"fr":"une panne","en":"a breakdown","example":"La voiture est tombée en panne."},{"fr":"un inconnu","en":"a stranger","example":"Un inconnu m''a aidé."},{"fr":"heureusement","en":"fortunately","example":"Heureusement, personne n''était blessé."},{"fr":"malheureusement","en":"unfortunately","example":"Malheureusement, il pleuvait."},{"fr":"finalement","en":"in the end","example":"Finalement, tout s''est bien passé."}],"grammar":{"topic":"Imparfait ou passé composé ?","explanation":"In a story, the two tenses work together:\n• Imparfait = the background: description, weather, feelings, ongoing actions, habits. « Il faisait nuit, je rentrais chez moi… »\n• Passé composé = the events: completed, specific actions that move the story forward. « … quand j''ai entendu un bruit. »\nTypical pattern: imparfait (ongoing) + quand + passé composé (interruption).","examples":["Je dormais quand le téléphone a sonné.","Il pleuvait, alors nous sommes restés à la maison.","Elle était fatiguée, mais elle a fini son travail.","Pendant que nous mangions, il est parti."]},"text":{"title":"Une panne sur la route","body":"C''était un dimanche soir de juillet. Il faisait chaud et nous rentrions de la plage en voiture. Les enfants dormaient à l''arrière. Tout à coup, le moteur a fait un bruit étrange et la voiture s''est arrêtée. Il n''y avait personne sur la route et mon téléphone n''avait plus de batterie. Après vingt minutes, un inconnu s''est arrêté. Il était mécanicien ! Il a réparé la voiture en dix minutes et il n''a pas voulu d''argent. Finalement, nous sommes arrivés à la maison à minuit.","questions":[{"id":"tq1","question":"Que faisaient les enfants quand la voiture s''est arrêtée ?","options":["Ils dormaient.","Ils chantaient.","Ils mangeaient.","Ils jouaient."],"answer":"Ils dormaient.","explanation":""},{"id":"tq2","question":"Qui a aidé la famille ?","options":["un ami de la famille","un policier","un mécanicien qui passait","un voisin"],"answer":"un mécanicien qui passait","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"Je ___ un livre quand Paul est entré.","options":["lisais","lis","lirai","ai lu"],"answer":"lisais","accepted":[],"explanation":"Ongoing action interrupted → imparfait.","tag":"imparfait-passe-compose","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"Il faisait beau, alors nous ___ à la plage.","options":["sommes allés","allions","allons","irons"],"answer":"sommes allés","accepted":[],"explanation":"A specific completed event → passé composé.","tag":"imparfait-passe-compose","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"Quand j''___ jeune, je jouais du piano. (être)","options":[],"answer":"étais","accepted":[],"explanation":"Description / state in the past → imparfait.","tag":"imparfait","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["quand","Nous","dormions","commencé","l''orage","a"],"answer":"Nous dormions quand l''orage a commencé","accepted":[],"explanation":"Imparfait + quand + passé composé.","tag":"imparfait-passe-compose","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"It was raining when I left the house.\"","options":[],"answer":"Il pleuvait quand je suis sorti de la maison.","accepted":["Il pleuvait quand je suis sortie de la maison.","Il pleuvait quand j''ai quitté la maison."],"explanation":"Background (imparfait) + event (passé composé).","tag":"imparfait-passe-compose","id":"ex5"}],"writing_prompt":"Racontez un souvenir surprenant ou un petit incident (100 mots).","writing_model":"L''année dernière, je rentrais du travail en bus. Il était tard et il pleuvait beaucoup. Je regardais mon téléphone quand une femme s''est assise à côté de moi. Elle m''a souri : c''était ma maîtresse d''école primaire ! Nous ne nous étions pas vus depuis vingt ans. Nous avons parlé pendant tout le trajet et nous avons échangé nos numéros. Depuis, nous nous écrivons souvent.","writing_checklist":["imparfait pour le décor et les actions en cours","passé composé pour les événements","connecteurs : soudain, ensuite, finalement"],"email_snippet":{"word_of_day":{"fr":"soudain / tout à coup","en":"suddenly","example":"Tout à coup, la lumière s''est éteinte."},"mini_question":{"prompt":"Je ___ un livre quand Paul est entré.","options":["lisais","lis","lirai","ai lu"],"answer":"lisais"}}}'::jsonb, 'approved', 'curriculum'),
  ('B1', 2, 'Le monde du travail', '{"level":"B1","seq":2,"theme":"Le monde du travail","vocabulary":[{"fr":"l''entretien (m.) d''embauche","en":"the job interview","example":"J''ai un entretien d''embauche demain."},{"fr":"le CV","en":"the CV / résumé","example":"Envoyez votre CV par e-mail."},{"fr":"le poste","en":"the position / job","example":"Je postule pour ce poste."},{"fr":"postuler","en":"to apply","example":"Elle a postulé chez Total."},{"fr":"le salaire","en":"the salary","example":"Le salaire est intéressant."},{"fr":"l''expérience (f.)","en":"experience","example":"J''ai trois ans d''expérience."},{"fr":"embaucher","en":"to hire","example":"L''entreprise va embaucher dix personnes."},{"fr":"une augmentation","en":"a pay rise","example":"J''espère avoir une augmentation."}],"grammar":{"topic":"Le futur simple","explanation":"Futur simple = infinitive + -ai, -as, -a, -ons, -ez, -ont (drop the final -e of -re verbs): je travaillerai, tu finiras, il prendra.\nIrregular stems: être → ser-, avoir → aur-, aller → ir-, faire → fer-, pouvoir → pourr-, venir → viendr-, voir → verr-, vouloir → voudr-, devoir → devr-.\nUse it for predictions, promises and plans in the more distant future. After quand referring to the future, French uses the futur: « Quand je serai riche… »","examples":["Je commencerai lundi.","Nous aurons une réponse demain.","Quand tu seras à Paris, tu m''appelleras.","Ils feront une réunion vendredi."]},"text":{"title":"Le premier jour","body":"Chère Mme Okafor,\nNous avons le plaisir de vous confirmer votre embauche au poste d''assistante commerciale. Vous commencerez le lundi 3 mars à 9 heures. Le premier jour, vous rencontrerez l''équipe et vous visiterez les locaux. Votre responsable, M. Lambert, vous expliquera vos missions. Vous aurez une période d''essai de trois mois. Nous serons ravis de vous accueillir.\nCordialement,\nLe service des ressources humaines","questions":[{"id":"tq1","question":"Quel poste Mme Okafor a-t-elle obtenu ?","options":["comptable","assistante commerciale","directrice","responsable d''équipe"],"answer":"assistante commerciale","explanation":""},{"id":"tq2","question":"Combien de temps dure la période d''essai ?","options":["six mois","trois mois","une semaine","un mois"],"answer":"trois mois","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"Demain, nous ___ une réunion. (avoir)","options":["aurons","aurions","avrons","avons"],"answer":"aurons","accepted":[],"explanation":"avoir → aur-.","tag":"futur-simple","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"Quand il ___ le diplôme, il cherchera un poste.","options":["avait","aura","aurait","a"],"answer":"aura","accepted":[],"explanation":"quand + future meaning → futur simple.","tag":"futur-simple","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"L''année prochaine, je ___ en France. (aller)","options":[],"answer":"irai","accepted":[],"explanation":"aller → ir-.","tag":"futur-simple","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["recevrez","une","Vous","prochaine","semaine","la","réponse"],"answer":"Vous recevrez une réponse la semaine prochaine","accepted":[],"explanation":"Subject + futur + object + time.","tag":"futur-simple","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"When I am in Paris, I will visit the Louvre.\"","options":[],"answer":"Quand je serai à Paris, je visiterai le Louvre.","accepted":[],"explanation":"Futur after quand in French.","tag":"futur-simple","id":"ex5"}],"writing_prompt":"Imaginez votre vie professionnelle dans dix ans.","writing_model":"Dans dix ans, je serai chef de projet dans une entreprise internationale. Je travaillerai avec des équipes en France et au Canada, donc je parlerai français tous les jours. J''aurai une maison avec un jardin et je pourrai voyager souvent. Quand j''aurai assez d''expérience, je créerai ma propre entreprise.","writing_checklist":["futur simple régulier et irrégulier (serai, aurai, pourrai)","quand + futur","vocabulaire du travail"],"email_snippet":{"word_of_day":{"fr":"l''entretien (m.) d''embauche","en":"the job interview","example":"J''ai un entretien d''embauche demain."},"mini_question":{"prompt":"Demain, nous ___ une réunion. (avoir)","options":["aurons","aurions","avrons","avons"],"answer":"aurons"}}}'::jsonb, 'approved', 'curriculum'),
  ('B1', 3, 'Si j''avais le choix…', '{"level":"B1","seq":3,"theme":"Si j''avais le choix…","vocabulary":[{"fr":"gagner au loto","en":"to win the lottery","example":"Si je gagnais au loto, j''achèterais une maison."},{"fr":"rêver de","en":"to dream of","example":"Elle rêve de voyager."},{"fr":"un tour du monde","en":"a round-the-world trip","example":"Ils ont fait un tour du monde."},{"fr":"le bénévolat","en":"volunteering","example":"Je fais du bénévolat le samedi."},{"fr":"aider","en":"to help","example":"J''aimerais aider les autres."},{"fr":"à ta place","en":"if I were you","example":"À ta place, je partirais."},{"fr":"le conseil","en":"advice","example":"Tu peux me donner un conseil ?"},{"fr":"il vaudrait mieux","en":"it would be better","example":"Il vaudrait mieux attendre."}],"grammar":{"topic":"Le conditionnel présent et l''hypothèse avec si","explanation":"Conditionnel présent = future stem + imparfait endings (-ais, -ais, -ait, -ions, -iez, -aient): je voudrais, tu serais, nous ferions.\nUses: wishes (j''aimerais), polite requests (pourriez-vous…), advice (tu devrais…), and imaginary situations.\nHypothesis: si + imparfait → conditionnel. « Si j''avais le temps, je voyagerais. »\nNever put the conditionnel right after si.","examples":["Si j''étais riche, j''aiderais ma famille.","Tu devrais te reposer.","Pourriez-vous m''aider ?","S''il faisait beau, nous irions à la plage."]},"text":{"title":"Et si… ?","body":"On a demandé à trois personnes ce qu''elles feraient si elles gagnaient un million d''euros. Aïcha, 24 ans, ferait le tour du monde et visiterait l''Amérique du Sud. Paul, 45 ans, ne quitterait pas son travail : il paierait la maison de ses parents et il donnerait de l''argent à une association. Quant à Mariam, elle ouvrirait une école dans son village. « Si j''avais cet argent, dit-elle, je voudrais qu''il serve à tout le monde. »","questions":[{"id":"tq1","question":"Que ferait Paul ?","options":["Il ferait le tour du monde.","Il quitterait son travail.","Il aiderait ses parents et une association.","Il ouvrirait une école."],"answer":"Il aiderait ses parents et une association.","explanation":""},{"id":"tq2","question":"Quel est le projet de Mariam ?","options":["acheter une maison","ouvrir une école dans son village","créer une entreprise","visiter l''Amérique du Sud"],"answer":"ouvrir une école dans son village","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"Si j''avais le temps, je ___ plus de sport.","options":["ferais","ferai","fais","faisais"],"answer":"ferais","accepted":[],"explanation":"si + imparfait → conditionnel.","tag":"conditional-si","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"Si nous ___ riches, nous voyagerions.","options":["serons","serions","étions","sommes"],"answer":"étions","accepted":[],"explanation":"Never the conditionnel after si: si + imparfait.","tag":"conditional-si","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"Tu ___ voir un médecin. (devoir – advice)","options":[],"answer":"devrais","accepted":[],"explanation":"Advice: conditionnel of devoir.","tag":"conditional","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["fermer","Pourriez-vous","plaît","fenêtre","vous","s''il","la"],"answer":"Pourriez-vous fermer la fenêtre s''il vous plaît","accepted":[],"explanation":"Polite request with the conditionnel.","tag":"conditional","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"If I won the lottery, I would buy a house for my mother.\"","options":[],"answer":"Si je gagnais au loto, j''achèterais une maison pour ma mère.","accepted":["Si je gagnais à la loterie, j''achèterais une maison pour ma mère."],"explanation":"si + imparfait, conditionnel.","tag":"conditional-si","id":"ex5"}],"writing_prompt":"Que feriez-vous si vous pouviez changer une chose dans votre ville ?","writing_model":"Si je pouvais changer une chose dans ma ville, je construirais plus de parcs. Les enfants auraient des endroits sûrs pour jouer et les familles pourraient se promener le week-end. Si la mairie plantait des arbres, il ferait moins chaud en été. À mon avis, la ville serait plus agréable pour tout le monde.","writing_checklist":["si + imparfait","conditionnel dans la proposition principale","au moins trois conséquences"],"email_snippet":{"word_of_day":{"fr":"gagner au loto","en":"to win the lottery","example":"Si je gagnais au loto, j''achèterais une maison."},"mini_question":{"prompt":"Si j''avais le temps, je ___ plus de sport.","options":["ferais","ferai","fais","faisais"],"answer":"ferais"}}}'::jsonb, 'approved', 'curriculum'),
  ('B1', 4, 'Donner son opinion', '{"level":"B1","seq":4,"theme":"Donner son opinion","vocabulary":[{"fr":"à mon avis","en":"in my opinion","example":"À mon avis, c''est une bonne idée."},{"fr":"d''après moi","en":"according to me","example":"D''après moi, il a raison."},{"fr":"être d''accord avec","en":"to agree with","example":"Je suis d''accord avec toi."},{"fr":"avoir raison / tort","en":"to be right / wrong","example":"Tu as tort."},{"fr":"un avantage / un inconvénient","en":"an advantage / a drawback","example":"Le télétravail a des avantages."},{"fr":"d''un côté… de l''autre","en":"on one hand… on the other","example":"D''un côté c''est pratique, de l''autre c''est cher."},{"fr":"en effet","en":"indeed","example":"En effet, les prix ont augmenté."},{"fr":"pourtant","en":"yet / however","example":"Il est riche ; pourtant, il n''est pas heureux."}],"grammar":{"topic":"Exprimer et justifier une opinion","explanation":"Give an opinion: je pense que, je crois que, je trouve que, il me semble que + indicative.\nJustify: parce que, car, puisque (since, obvious reason), comme (at the start of a sentence).\nContrast: mais, pourtant, cependant, par contre.\nNote: in the negative, je ne pense pas que / je ne crois pas que are followed by the subjunctive (you''ll study it at B2): « Je ne pense pas qu''il soit là. »","examples":["Je trouve que ce film est trop long.","Je pense qu''il a raison, car il connaît bien le sujet.","Comme il pleut, je reste ici.","C''est cher ; pourtant, beaucoup de gens l''achètent."]},"text":{"title":"Faut-il interdire les téléphones à l''école ?","body":"Pour Mme Dupont, professeure, les téléphones devraient être interdits en classe. Elle pense que les élèves se concentrent mieux sans écran et qu''ils parlent davantage entre eux. Son collègue M. Ba n''est pas d''accord. D''après lui, le téléphone peut être un outil pédagogique : on peut chercher une information ou utiliser un dictionnaire. Pourtant, il reconnaît qu''il faut des règles claires. Les parents, eux, sont divisés.","questions":[{"id":"tq1","question":"Quelle est la position de Mme Dupont ?","options":["Elle n''a pas d''avis.","Elle veut des règles plus souples.","Elle veut les autoriser.","Elle veut interdire les téléphones en classe."],"answer":"Elle veut interdire les téléphones en classe.","explanation":""},{"id":"tq2","question":"Qu''est-ce que M. Ba reconnaît ?","options":["que Mme Dupont a raison","qu''il faut des règles claires","que le téléphone est inutile","que les parents sont d''accord"],"answer":"qu''il faut des règles claires","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"Je pense qu''il ___ raison.","options":["ayant","avoir","ait","a"],"answer":"a","accepted":[],"explanation":"je pense que + indicative.","tag":"opinion","id":"ex1"},{"type":"mcq","skill":"vocabulary","prompt":"Il est fatigué ; ___, il continue à travailler.","options":["pourtant","car","donc","parce que"],"answer":"pourtant","accepted":[],"explanation":"Contrast → pourtant.","tag":"connectors","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"___ il fait beau, nous allons sortir. (as – at the start)","options":[],"answer":"Comme","accepted":["comme"],"explanation":"comme at the start of a sentence = since / as.","tag":"connectors","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["d''avantages","beaucoup","À","avis","télétravail","mon","le","a"],"answer":"À mon avis le télétravail a beaucoup d''avantages","accepted":[],"explanation":"Opinion phrase + statement.","tag":"opinion","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"I agree with you because it''s a good idea.\"","options":[],"answer":"Je suis d''accord avec toi parce que c''est une bonne idée.","accepted":["Je suis d''accord avec vous parce que c''est une bonne idée.","Je suis d''accord avec toi car c''est une bonne idée."],"explanation":"être d''accord avec + parce que.","tag":"opinion","id":"ex5"}],"writing_prompt":"Le télétravail : êtes-vous pour ou contre ? Donnez votre avis avec deux arguments (100 mots).","writing_model":"À mon avis, le télétravail est une bonne chose, mais pas tous les jours. D''un côté, on gagne du temps car on ne perd pas deux heures dans les transports. En effet, à Lagos, les embouteillages sont terribles. De l''autre côté, on se sent parfois seul et on communique moins bien avec ses collègues. Pourtant, avec deux ou trois jours au bureau, je pense qu''on peut trouver un bon équilibre.","writing_checklist":["à mon avis / je pense que","deux arguments justifiés (car, parce que, en effet)","une concession (pourtant, de l''autre côté)"],"email_snippet":{"word_of_day":{"fr":"à mon avis","en":"in my opinion","example":"À mon avis, c''est une bonne idée."},"mini_question":{"prompt":"Je pense qu''il ___ raison.","options":["ayant","avoir","ait","a"],"answer":"a"}}}'::jsonb, 'approved', 'curriculum'),
  ('B1', 5, 'L''environnement', '{"level":"B1","seq":5,"theme":"L''environnement","vocabulary":[{"fr":"les déchets (m.)","en":"waste","example":"Il faut réduire nos déchets."},{"fr":"recycler","en":"to recycle","example":"Nous recyclons le plastique."},{"fr":"la pollution","en":"pollution","example":"La pollution de l''air est grave."},{"fr":"le réchauffement climatique","en":"global warming","example":"Le réchauffement climatique menace les côtes."},{"fr":"gaspiller","en":"to waste","example":"Ne gaspille pas l''eau !"},{"fr":"l''énergie (f.) solaire","en":"solar energy","example":"Ils utilisent l''énergie solaire."},{"fr":"protéger","en":"to protect","example":"Il faut protéger les forêts."},{"fr":"la sécheresse","en":"drought","example":"La sécheresse touche le Sahel."}],"grammar":{"topic":"Les pronoms relatifs dont et où","explanation":"dont replaces de + noun: parler de, avoir besoin de, avoir peur de, être fier de… « C''est le projet dont je t''ai parlé. » It also expresses possession: « une ville dont les rues sont propres » (whose).\noù replaces a place or a time: « la ville où j''habite », « le jour où je suis arrivé ».","examples":["Voici le livre dont j''ai besoin.","C''est un problème dont tout le monde parle.","La région où il vit manque d''eau.","Je me souviens de l''année où il a beaucoup plu."]},"text":{"title":"Un village solaire","body":"Dans le nord du Burkina Faso, il y a un village où les habitants ont installé des panneaux solaires. Avant, ils utilisaient des générateurs dont le bruit et la fumée posaient des problèmes. Aujourd''hui, l''école a de la lumière le soir et le centre de santé peut conserver des médicaments au froid. Le projet dont tout le monde est fier a été financé par une coopérative de femmes. D''autres villages veulent maintenant suivre cet exemple.","questions":[{"id":"tq1","question":"Quel problème posaient les générateurs ?","options":["le manque de médicaments","le prix des panneaux","la sécheresse","le bruit et la fumée"],"answer":"le bruit et la fumée","explanation":""},{"id":"tq2","question":"Qui a financé le projet ?","options":["l''école","une coopérative de femmes","le gouvernement","une entreprise étrangère"],"answer":"une coopérative de femmes","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"C''est le film ___ je t''ai parlé.","options":["que","qui","où","dont"],"answer":"dont","accepted":[],"explanation":"parler de → dont.","tag":"relative-dont","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"La ville ___ je suis né est au bord de la mer.","options":["qui","que","dont","où"],"answer":"où","accepted":[],"explanation":"Place → où.","tag":"relative-ou","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"Voici l''outil ___ tu as besoin.","options":[],"answer":"dont","accepted":[],"explanation":"avoir besoin de → dont.","tag":"relative-dont","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["il","chaud","pays","fait","un","toujours","C''est","où"],"answer":"C''est un pays où il fait toujours chaud","accepted":[],"explanation":"où for a place.","tag":"relative-ou","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"This is the problem everyone is talking about.\"","options":[],"answer":"C''est le problème dont tout le monde parle.","accepted":["Voici le problème dont tout le monde parle."],"explanation":"parler de → dont.","tag":"relative-dont","id":"ex5"}],"writing_prompt":"Quels gestes faites-vous (ou pourriez-vous faire) pour protéger l''environnement ?","writing_model":"Chez moi, nous essayons de réduire nos déchets. Nous recyclons les bouteilles en plastique et nous utilisons des sacs en tissu dont nous avons toujours besoin au marché. Je ne gaspille pas l''eau et j''éteins la lumière quand je quitte une pièce. Dans le quartier où j''habite, il n''y a pas de bus, mais je voudrais faire plus de trajets à vélo.","writing_checklist":["dont et où correctement utilisés","vocabulaire de l''environnement","au moins trois actions concrètes"],"email_snippet":{"word_of_day":{"fr":"les déchets (m.)","en":"waste","example":"Il faut réduire nos déchets."},"mini_question":{"prompt":"C''est le film ___ je t''ai parlé.","options":["que","qui","où","dont"],"answer":"dont"}}}'::jsonb, 'approved', 'curriculum'),
  ('B1', 6, 'Les médias et l''information', '{"level":"B1","seq":6,"theme":"Les médias et l''information","vocabulary":[{"fr":"les informations / les infos (f.)","en":"the news","example":"Je regarde les infos le soir."},{"fr":"un article","en":"an article","example":"J''ai lu un article intéressant."},{"fr":"le journaliste","en":"the journalist","example":"Le journaliste a interviewé le ministre."},{"fr":"une fausse information","en":"fake news","example":"Attention aux fausses informations !"},{"fr":"les réseaux sociaux","en":"social media","example":"Elle passe trop de temps sur les réseaux sociaux."},{"fr":"annoncer","en":"to announce","example":"Le gouvernement a annoncé une réforme."},{"fr":"affirmer","en":"to state / claim","example":"Il affirme qu''il est innocent."},{"fr":"vérifier","en":"to check","example":"Il faut vérifier la source."}],"grammar":{"topic":"Le discours indirect (au présent)","explanation":"Reported speech with a verb in the present (il dit, elle explique, ils affirment):\n• statement → que: « Je suis fatigué. » → Il dit qu''il est fatigué.\n• yes/no question → si: « Tu viens ? » → Elle demande si je viens.\n• question word stays: « Où vas-tu ? » → Il demande où je vais.\n• qu''est-ce que → ce que: « Qu''est-ce que tu veux ? » → Il demande ce que je veux.\n• imperative → de + infinitive: « Viens ! » → Il me dit de venir.\nPronouns and possessives change to fit the new speaker.","examples":["Le ministre affirme que la situation s''améliore.","Ma mère demande si nous venons dimanche.","Il me demande ce que je fais ce soir.","Le médecin me dit de rester au lit."]},"text":{"title":"Une interview","body":"La journaliste demande à la chanteuse Aya ce qu''elle prépare en ce moment. Aya répond qu''elle enregistre un nouvel album et qu''il sortira en septembre. La journaliste veut savoir si elle fera une tournée en Afrique. La chanteuse explique qu''elle donnera des concerts à Abidjan, Dakar et Lagos. Enfin, elle conseille aux jeunes artistes de ne jamais abandonner.","questions":[{"id":"tq1","question":"Quand l''album sortira-t-il ?","options":["en juin","en septembre","l''année prochaine","en décembre"],"answer":"en septembre","explanation":""},{"id":"tq2","question":"Quel conseil Aya donne-t-elle aux jeunes artistes ?","options":["d''utiliser les réseaux sociaux","de ne jamais abandonner","de partir en tournée","d''étudier la musique"],"answer":"de ne jamais abandonner","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"« Tu as faim ? » → Il me demande ___ j''ai faim.","options":["si","qu''est-ce que","ce que","que"],"answer":"si","accepted":[],"explanation":"Yes/no question → si.","tag":"reported-speech","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"« Qu''est-ce que tu lis ? » → Elle demande ___ je lis.","options":["qu''est-ce que","ce que","que","quoi"],"answer":"ce que","accepted":[],"explanation":"qu''est-ce que → ce que.","tag":"reported-speech","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"« Ferme la porte ! » → Il me dit ___ fermer la porte.","options":[],"answer":"de","accepted":[],"explanation":"Imperative → de + infinitive.","tag":"reported-speech","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["demain","qu''elle","Elle","dit","arrivera"],"answer":"Elle dit qu''elle arrivera demain","accepted":[],"explanation":"dit que + clause.","tag":"reported-speech","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"He asks where we live.\"","options":[],"answer":"Il demande où nous habitons.","accepted":["Il demande où on habite."],"explanation":"Question word stays; no inversion.","tag":"reported-speech","id":"ex5"}],"writing_prompt":"Rapportez une conversation récente avec un ami ou un collègue au discours indirect.","writing_model":"Hier, mon collègue m''a appelé. Il me dit qu''il cherche un nouvel appartement et il me demande si je connais un bon quartier. Je lui réponds que Yaba est pratique. Il veut savoir combien coûte le loyer. Je lui conseille de regarder sur internet et de visiter avant de signer.","writing_checklist":["que / si / ce que / où","de + infinitif pour les ordres et conseils","changement des pronoms"],"email_snippet":{"word_of_day":{"fr":"les informations / les infos (f.)","en":"the news","example":"Je regarde les infos le soir."},"mini_question":{"prompt":"« Tu as faim ? » → Il me demande ___ j''ai faim.","options":["si","qu''est-ce que","ce que","que"],"answer":"si"}}}'::jsonb, 'approved', 'curriculum'),
  ('B1', 7, 'La santé et le bien-être', '{"level":"B1","seq":7,"theme":"La santé et le bien-être","vocabulary":[{"fr":"le sommeil","en":"sleep","example":"Le sommeil est essentiel."},{"fr":"le stress","en":"stress","example":"Le sport réduit le stress."},{"fr":"une alimentation équilibrée","en":"a balanced diet","example":"Il faut une alimentation équilibrée."},{"fr":"faire de l''exercice","en":"to exercise","example":"Je fais de l''exercice trois fois par semaine."},{"fr":"prendre soin de","en":"to take care of","example":"Prends soin de toi."},{"fr":"être en forme","en":"to be fit / well","example":"Je suis en forme aujourd''hui."},{"fr":"se sentir","en":"to feel","example":"Je me sens mieux."},{"fr":"éviter","en":"to avoid","example":"Évitez le sucre."}],"grammar":{"topic":"Le plus-que-parfait","explanation":"Plus-que-parfait = avoir / être in the imparfait + past participle: j''avais mangé, elle était partie.\nIt expresses an action that happened BEFORE another past action: « Quand je suis arrivé, le film avait déjà commencé. »\nSame rules as the passé composé for être / avoir and agreement.","examples":["Il était fatigué parce qu''il avait mal dormi.","Nous avions déjà mangé quand ils sont arrivés.","Elle m''a dit qu''elle était allée chez le médecin.","Je n''avais jamais fait de yoga avant."]},"text":{"title":"Un changement de vie","body":"L''année dernière, Daniel se sentait toujours fatigué. Il avait pris dix kilos et il dormait mal. Il avait travaillé sans vacances pendant trois ans. Un jour, son médecin lui a conseillé de changer ses habitudes. Daniel a commencé à marcher trente minutes par jour et il a arrêté les boissons sucrées. Six mois plus tard, il avait perdu huit kilos et il se sentait beaucoup plus en forme.","questions":[{"id":"tq1","question":"Pourquoi Daniel était-il fatigué ?","options":["Il avait travaillé sans vacances pendant trois ans.","Il était malade.","Il avait déménagé.","Il avait fait trop de sport."],"answer":"Il avait travaillé sans vacances pendant trois ans.","explanation":""},{"id":"tq2","question":"Qu''a-t-il arrêté ?","options":["la marche","le café","le travail","les boissons sucrées"],"answer":"les boissons sucrées","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"Quand je suis arrivé, ils ___ déjà mangé.","options":["ont","auraient","avait","avaient"],"answer":"avaient","accepted":[],"explanation":"Earlier past action → plus-que-parfait.","tag":"plus-que-parfait","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"Elle était triste parce qu''elle ___ son examen.","options":["raterait","rate","avait raté","a raté"],"answer":"avait raté","accepted":[],"explanation":"Cause earlier than « était triste ».","tag":"plus-que-parfait","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"Nous ___ partis avant la pluie. (être, plus-que-parfait)","options":[],"answer":"étions","accepted":[],"explanation":"être verbs: étions + participle.","tag":"plus-que-parfait","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["jamais","Il","sport","fait","de","n''avait","avant"],"answer":"Il n''avait jamais fait de sport avant","accepted":[],"explanation":"ne + avait + jamais + participle.","tag":"plus-que-parfait","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"I felt better because I had slept well.\"","options":[],"answer":"Je me sentais mieux parce que j''avais bien dormi.","accepted":[],"explanation":"Earlier cause → plus-que-parfait.","tag":"plus-que-parfait","id":"ex5"}],"writing_prompt":"Racontez un changement d''habitude que vous avez fait, en expliquant la situation d''avant.","writing_model":"Il y a deux ans, j''ai décidé de dormir plus. Avant, je me couchais à deux heures du matin parce que j''avais pris l''habitude de regarder des séries. J''étais souvent fatigué et j''avais oublié ce que c''était d''être en forme. Maintenant, j''éteins mon téléphone à dix heures et je me sens beaucoup mieux.","writing_checklist":["plus-que-parfait pour l''antériorité","imparfait pour la situation passée","vocabulaire de la santé"],"email_snippet":{"word_of_day":{"fr":"le sommeil","en":"sleep","example":"Le sommeil est essentiel."},"mini_question":{"prompt":"Quand je suis arrivé, ils ___ déjà mangé.","options":["ont","auraient","avait","avaient"],"answer":"avaient"}}}'::jsonb, 'approved', 'curriculum'),
  ('B1', 8, 'Les études', '{"level":"B1","seq":8,"theme":"Les études","vocabulary":[{"fr":"s''inscrire","en":"to enrol","example":"Je me suis inscrit à l''université."},{"fr":"le diplôme","en":"the degree / diploma","example":"Elle a obtenu son diplôme."},{"fr":"réussir un examen","en":"to pass an exam","example":"Il a réussi son examen."},{"fr":"échouer / rater","en":"to fail","example":"J''ai raté le test."},{"fr":"réviser","en":"to revise / study","example":"Nous révisons pour l''examen."},{"fr":"la bourse","en":"the scholarship","example":"Elle a obtenu une bourse."},{"fr":"le mémoire","en":"the dissertation","example":"Il écrit son mémoire."},{"fr":"la licence / le master","en":"bachelor''s / master''s degree","example":"Je prépare un master."}],"grammar":{"topic":"Le gérondif","explanation":"Gérondif = en + present participle (nous-stem + -ant): parler → en parlant, finir → en finissant, faire → en faisant.\nIrregular: être → en étant, avoir → en ayant, savoir → en sachant.\nIt expresses simultaneity (« Il écoute de la musique en travaillant. »), manner or means (« On apprend en pratiquant. ») or a condition.\nThe subject of the gérondif is the same as the main verb.","examples":["Elle révise en écoutant de la musique.","C''est en forgeant qu''on devient forgeron.","En partant tôt, tu éviteras les embouteillages.","Je l''ai rencontré en allant au travail."]},"text":{"title":"Étudier à l''étranger","body":"Ngozi a obtenu une bourse pour faire un master à Lyon. Au début, c''était difficile : elle comprenait mal les cours et elle se sentait seule. Elle a fait des progrès en regardant des séries françaises et en parlant avec ses voisins. En travaillant le week-end dans une librairie, elle a aussi rencontré beaucoup de gens. L''année dernière, elle a réussi son master avec mention et elle a trouvé un emploi en France.","questions":[{"id":"tq1","question":"Comment Ngozi a-t-elle progressé en français ?","options":["en écoutant la radio","en prenant des cours privés","en lisant des journaux","en regardant des séries et en parlant avec ses voisins"],"answer":"en regardant des séries et en parlant avec ses voisins","explanation":""},{"id":"tq2","question":"Où travaillait-elle le week-end ?","options":["dans une librairie","dans un restaurant","à l''université","dans un hôtel"],"answer":"dans une librairie","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"On apprend une langue ___ la pratiquant.","options":["par","en","à","pour"],"answer":"en","accepted":[],"explanation":"Gérondif: en + participle.","tag":"gerondif","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"Gérondif de « faire » :","options":["en faisant","en fesant","en fait","en faire"],"answer":"en faisant","accepted":[],"explanation":"nous faisons → faisant.","tag":"gerondif","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"Il s''est blessé en ___ au football. (jouer)","options":[],"answer":"jouant","accepted":[],"explanation":"jouer → jouant.","tag":"gerondif","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["en","Elle","faisant","la","cuisine","chante"],"answer":"Elle chante en faisant la cuisine","accepted":[],"explanation":"Main verb + en + participle.","tag":"gerondif","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"By studying every day, you will pass the exam.\"","options":[],"answer":"En étudiant tous les jours, tu réussiras l''examen.","accepted":["En étudiant chaque jour, tu réussiras l''examen.","En étudiant tous les jours, vous réussirez l''examen."],"explanation":"Gérondif of means + futur.","tag":"gerondif","id":"ex5"}],"writing_prompt":"Comment apprenez-vous le mieux ? Donnez trois conseils à un nouvel étudiant (avec des gérondifs).","writing_model":"Pour bien apprendre, je conseille d''abord d''organiser son temps en faisant un planning chaque semaine. Ensuite, on retient mieux en expliquant les cours à quelqu''un d''autre. Enfin, en dormant suffisamment avant un examen, on est plus concentré. Personnellement, j''apprends le vocabulaire en écoutant des podcasts dans le bus.","writing_checklist":["au moins trois gérondifs (en + -ant)","même sujet que le verbe principal","connecteurs : d''abord, ensuite, enfin"],"email_snippet":{"word_of_day":{"fr":"s''inscrire","en":"to enrol","example":"Je me suis inscrit à l''université."},"mini_question":{"prompt":"On apprend une langue ___ la pratiquant.","options":["par","en","à","pour"],"answer":"en"}}}'::jsonb, 'approved', 'curriculum'),
  ('B1', 9, 'Celui-ci ou celui-là ?', '{"level":"B1","seq":9,"theme":"Celui-ci ou celui-là ?","vocabulary":[{"fr":"comparer","en":"to compare","example":"J''ai comparé les prix."},{"fr":"la marque","en":"the brand","example":"Quelle marque préfères-tu ?"},{"fr":"la qualité","en":"quality","example":"Ce produit est de bonne qualité."},{"fr":"solide","en":"sturdy","example":"Cette table est très solide."},{"fr":"pratique","en":"practical","example":"Ce sac est pratique."},{"fr":"d''occasion","en":"second-hand","example":"J''ai acheté une voiture d''occasion."},{"fr":"une promotion / en solde","en":"a special offer / on sale","example":"Ces chaussures sont en solde."},{"fr":"hésiter","en":"to hesitate","example":"J''hésite entre les deux."}],"grammar":{"topic":"Les pronoms démonstratifs","explanation":"Demonstrative pronouns replace ce / cette / ces + noun: celui (m. sg.), celle (f. sg.), ceux (m. pl.), celles (f. pl.).\nThey are followed by:\n• -ci / -là: celui-ci (this one), celle-là (that one)\n• de + noun: « le téléphone de Paul et celui de Marie »\n• qui / que / dont: « Prends celle que tu préfères. »","examples":["Quel sac veux-tu ? Celui-ci ou celui-là ?","Ma voiture est blanche ; celle de mon frère est noire.","Ces chaussures sont jolies, mais je préfère celles qui sont en solde.","Les étudiants qui ont réussi et ceux qui ont échoué."]},"text":{"title":"Quel ordinateur choisir ?","body":"Esther veut acheter un ordinateur portable pour ses études. Le vendeur lui montre deux modèles. Celui-ci est léger et pratique, mais sa batterie dure seulement cinq heures. Celui-là est plus lourd, mais il est plus puissant et sa batterie dure dix heures. Esther hésite. Finalement, elle choisit celui qui a la meilleure batterie, parce qu''elle travaille souvent à la bibliothèque.","questions":[{"id":"tq1","question":"Quel est le défaut du premier ordinateur ?","options":["Il est lent.","Il est cher.","Il est lourd.","La batterie dure peu."],"answer":"La batterie dure peu.","explanation":""},{"id":"tq2","question":"Pourquoi Esther choisit-elle le deuxième ?","options":["parce qu''il est en solde","parce qu''il est léger","pour sa batterie, car elle travaille à la bibliothèque","pour sa couleur"],"answer":"pour sa batterie, car elle travaille à la bibliothèque","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"Cette robe est belle, mais je préfère ___-là.","options":["ceux","celui","celle","celles"],"answer":"celle","accepted":[],"explanation":"robe (f. sg.) → celle.","tag":"demonstrative-pronouns","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"Mes livres et ___ de mon frère sont sur la table.","options":["celles","ceux","celui","ces"],"answer":"ceux","accepted":[],"explanation":"livres (m. pl.) → ceux.","tag":"demonstrative-pronouns","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"Ce téléphone est plus cher que ___ de Marc.","options":[],"answer":"celui","accepted":[],"explanation":"téléphone (m. sg.) → celui.","tag":"demonstrative-pronouns","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["prends","celle","solde","qui","Je","en","est"],"answer":"Je prends celle qui est en solde","accepted":[],"explanation":"celle + qui + clause.","tag":"demonstrative-pronouns","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"These shoes are nicer than those.\"","options":[],"answer":"Ces chaussures sont plus jolies que celles-là.","accepted":["Ces chaussures sont plus belles que celles-là."],"explanation":"chaussures (f. pl.) → celles-là.","tag":"demonstrative-pronouns","id":"ex5"}],"writing_prompt":"Vous hésitez entre deux produits (téléphones, voitures, appartements…). Comparez-les avec des pronoms démonstratifs.","writing_model":"J''hésite entre deux téléphones. Celui de la marque A est moins cher, mais sa caméra est moyenne. Celui de la marque B est plus cher, mais ses photos sont superbes. Mes amis ont tous celui-là. Finalement, je vais acheter celui qui a la meilleure batterie, parce que je voyage souvent.","writing_checklist":["celui / celle / ceux / celles","-ci / -là, de, qui / que","comparatifs"],"email_snippet":{"word_of_day":{"fr":"comparer","en":"to compare","example":"J''ai comparé les prix."},"mini_question":{"prompt":"Cette robe est belle, mais je préfère ___-là.","options":["ceux","celui","celle","celles"],"answer":"celle"}}}'::jsonb, 'approved', 'curriculum'),
  ('B1', 10, 'Les relations', '{"level":"B1","seq":10,"theme":"Les relations","vocabulary":[{"fr":"un(e) ami(e) d''enfance","en":"a childhood friend","example":"C''est mon ami d''enfance."},{"fr":"se disputer","en":"to argue","example":"Ils se disputent souvent."},{"fr":"se réconcilier","en":"to make up","example":"Nous nous sommes réconciliés."},{"fr":"faire confiance à","en":"to trust","example":"Je lui fais confiance."},{"fr":"la jalousie","en":"jealousy","example":"La jalousie détruit l''amitié."},{"fr":"tomber amoureux de","en":"to fall in love with","example":"Il est tombé amoureux d''elle."},{"fr":"s''entendre bien avec","en":"to get on well with","example":"Je m''entends bien avec mes collègues."},{"fr":"se marier avec","en":"to marry","example":"Elle s''est mariée avec un Ivoirien."}],"grammar":{"topic":"Les pronoms possessifs","explanation":"Possessive pronouns replace a possessive adjective + noun and agree with the thing owned:\nmine: le mien, la mienne, les miens, les miennes\nyours: le tien, la tienne… (informal) / le vôtre, la vôtre, les vôtres (formal)\nhis/hers: le sien, la sienne, les siens, les siennes\nours: le nôtre, la nôtre, les nôtres · theirs: le leur, la leur, les leurs.\nà + le mien → au mien; de + le mien → du mien.","examples":["Ce n''est pas ton livre, c''est le mien.","Ta maison est grande ; la nôtre est petite.","Mes parents s''entendent bien avec les siens.","Je pense souvent aux miens."]},"text":{"title":"Deux amies","body":"Clarisse et Hawa sont amies depuis l''école primaire. Leurs familles sont très différentes : celle de Clarisse est petite et calme, la sienne est grande et bruyante. Un jour, elles se sont disputées à cause d''un garçon dont elles étaient toutes les deux amoureuses. Elles ne se sont pas parlé pendant un an. Puis Hawa a écrit une lettre et elles se sont réconciliées. Aujourd''hui, chacune dit que leur amitié est plus forte que jamais.","questions":[{"id":"tq1","question":"Pourquoi se sont-elles disputées ?","options":["à cause d''un garçon","à cause de l''argent","à cause de l''école","à cause de leurs familles"],"answer":"à cause d''un garçon","explanation":""},{"id":"tq2","question":"Comment se sont-elles réconciliées ?","options":["Elles se sont rencontrées par hasard.","Clarisse a téléphoné.","Leurs familles les ont aidées.","Hawa a écrit une lettre."],"answer":"Hawa a écrit une lettre.","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"C''est ta voiture ? — Non, ce n''est pas ___.","options":["le mien","les miennes","ma","la mienne"],"answer":"la mienne","accepted":[],"explanation":"voiture (f. sg.) → la mienne.","tag":"possessive-pronouns","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"Nos enfants jouent avec ___. (their children)","options":["les leur","les leurs","le leur","leurs"],"answer":"les leurs","accepted":[],"explanation":"plural → les leurs.","tag":"possessive-pronouns","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"J''ai oublié mon stylo ; tu peux me prêter ___ ? (yours, informal)","options":[],"answer":"le tien","accepted":[],"explanation":"stylo (m. sg.) → le tien.","tag":"possessive-pronouns","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["ne","Ces","les","miennes","clés","pas","sont"],"answer":"Ces clés ne sont pas les miennes","accepted":[],"explanation":"Possessive pronoun agrees with clés (f. pl.).","tag":"possessive-pronouns","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"Your house is bigger than ours.\"","options":[],"answer":"Ta maison est plus grande que la nôtre.","accepted":["Votre maison est plus grande que la nôtre."],"explanation":"maison (f.) → la nôtre.","tag":"possessive-pronouns","id":"ex5"}],"writing_prompt":"Parlez d''une amitié importante pour vous : comment vous vous êtes rencontrés, vos points communs et vos différences.","writing_model":"Mon meilleur ami s''appelle Seun. Nous nous sommes rencontrés à l''université. Nos personnalités sont différentes : la mienne est calme, la sienne est très énergique. Ses parents sont commerçants, les miens sont enseignants. Nous nous sommes disputés une fois, mais nous nous sommes vite réconciliés. Je lui fais totalement confiance.","writing_checklist":["pronoms possessifs (le mien, la sienne…)","verbes pronominaux réciproques (se disputer, se réconcilier)","passé composé et présent"],"email_snippet":{"word_of_day":{"fr":"un(e) ami(e) d''enfance","en":"a childhood friend","example":"C''est mon ami d''enfance."},"mini_question":{"prompt":"C''est ta voiture ? — Non, ce n''est pas ___.","options":["le mien","les miennes","ma","la mienne"],"answer":"la mienne"}}}'::jsonb, 'approved', 'curriculum'),
  ('B1', 11, 'Fêtes et traditions', '{"level":"B1","seq":11,"theme":"Fêtes et traditions","vocabulary":[{"fr":"fêter / célébrer","en":"to celebrate","example":"Nous fêtons la Tabaski en famille."},{"fr":"une coutume","en":"a custom","example":"C''est une vieille coutume."},{"fr":"un jour férié","en":"a public holiday","example":"Le 1er mai est un jour férié."},{"fr":"se réunir","en":"to get together","example":"La famille se réunit pour Noël."},{"fr":"les invités (m.)","en":"the guests","example":"Les invités sont arrivés."},{"fr":"un plat traditionnel","en":"a traditional dish","example":"Le jollof est un plat traditionnel."},{"fr":"le défilé","en":"the parade","example":"Il y a un défilé le 14 juillet."},{"fr":"offrir","en":"to give (a gift)","example":"On offre des cadeaux."}],"grammar":{"topic":"Exprimer la durée : depuis, il y a, pendant, en","explanation":"• depuis + present = an action that started in the past and is still going on: « J''habite ici depuis 2019 / depuis trois ans. »\n• il y a + past = ago: « Je suis arrivé il y a trois ans. »\n• pendant = for (a completed duration): « J''ai vécu à Paris pendant deux ans. »\n• en = time needed to do something: « J''ai écrit le rapport en deux heures. »","examples":["Nous fêtons cette tradition depuis des siècles.","Il est parti il y a une semaine.","La fête a duré pendant trois jours.","Elle a préparé le repas en une heure."]},"text":{"title":"Le Fespaco","body":"Depuis 1969, Ouagadougou accueille le Fespaco, le grand festival du cinéma africain. Il a lieu tous les deux ans et dure pendant une semaine. Des réalisateurs de tout le continent viennent présenter leurs films. Il y a quelques années, un film sénégalais a remporté l''Étalon d''or, le prix le plus important. Pendant le festival, la ville se transforme : il y a des concerts, des défilés et des marchés partout.","questions":[{"id":"tq1","question":"Depuis quand le Fespaco existe-t-il ?","options":["depuis 1996","depuis 1969","depuis une semaine","depuis deux ans"],"answer":"depuis 1969","explanation":""},{"id":"tq2","question":"Combien de temps dure le festival ?","options":["un mois","trois jours","une semaine","deux ans"],"answer":"une semaine","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"J''apprends le français ___ deux ans. (and still learning)","options":["pendant","depuis","en","il y a"],"answer":"depuis","accepted":[],"explanation":"Ongoing action → depuis + present.","tag":"duration","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"Il est arrivé ___ trois jours.","options":["dans","pendant","depuis","il y a"],"answer":"il y a","accepted":[],"explanation":"ago → il y a.","tag":"duration","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"J''ai fini ce livre ___ une semaine. (time needed)","options":[],"answer":"en","accepted":[],"explanation":"Time needed → en.","tag":"duration","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["ont","Ils","à","ans","pendant","Dakar","cinq","vécu"],"answer":"Ils ont vécu à Dakar pendant cinq ans","accepted":[],"explanation":"Completed duration → pendant.","tag":"duration","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"We have been celebrating this festival for a long time.\"","options":[],"answer":"Nous fêtons ce festival depuis longtemps.","accepted":["Nous célébrons ce festival depuis longtemps.","On fête ce festival depuis longtemps."],"explanation":"depuis + present for ongoing actions.","tag":"duration","id":"ex5"}],"writing_prompt":"Décrivez une fête ou une tradition de votre pays : depuis quand, comment on la célèbre, ce qu''on mange.","writing_model":"Dans ma famille, nous célébrons le Nouvel An Igbo depuis toujours. Chaque année, nous nous réunissons au village pendant trois jours. On prépare de la soupe d''igname et on offre des cadeaux aux enfants. Il y a deux ans, j''ai aidé ma grand-mère à cuisiner pour cinquante invités : nous avons tout préparé en une journée !","writing_checklist":["depuis / il y a / pendant / en","vocabulaire des fêtes","présent et passé composé"],"email_snippet":{"word_of_day":{"fr":"fêter / célébrer","en":"to celebrate","example":"Nous fêtons la Tabaski en famille."},"mini_question":{"prompt":"J''apprends le français ___ deux ans. (and still learning)","options":["pendant","depuis","en","il y a"],"answer":"depuis"}}}'::jsonb, 'approved', 'curriculum'),
  ('B1', 12, 'Faire une réclamation', '{"level":"B1","seq":12,"theme":"Faire une réclamation","vocabulary":[{"fr":"se plaindre","en":"to complain","example":"Le client s''est plaint du service."},{"fr":"une réclamation","en":"a complaint","example":"J''ai fait une réclamation."},{"fr":"endommagé","en":"damaged","example":"Le colis est arrivé endommagé."},{"fr":"le service client","en":"customer service","example":"J''ai contacté le service client."},{"fr":"un remboursement","en":"a refund","example":"Je demande un remboursement."},{"fr":"un échange","en":"an exchange","example":"Vous pouvez faire un échange."},{"fr":"la garantie","en":"the warranty","example":"L''appareil est sous garantie."},{"fr":"inadmissible","en":"unacceptable","example":"Ce retard est inadmissible."}],"grammar":{"topic":"La politesse : le conditionnel et la lettre formelle","explanation":"In formal requests, use the conditionnel to soften: je voudrais, j''aimerais, pourriez-vous, seriez-vous…, je vous serais reconnaissant(e) de + infinitive.\nFormal letter structure: Madame, Monsieur, → reason (Je vous écris au sujet de… / Suite à…) → facts → request → closing: Je vous prie d''agréer, Madame, Monsieur, mes salutations distinguées.\nAlways use vous.","examples":["Pourriez-vous me rembourser ?","Je vous serais reconnaissant de me répondre rapidement.","Je vous écris au sujet de ma commande n° 2045.","J''aimerais obtenir un échange."]},"text":{"title":"Une lettre de réclamation","body":"Madame, Monsieur,\nJe vous écris au sujet de la machine à laver que j''ai achetée dans votre magasin le 12 mars. Depuis la semaine dernière, elle ne fonctionne plus : l''eau ne s''écoule pas. L''appareil est encore sous garantie. Pourriez-vous envoyer un technicien ou procéder à un échange ? Je vous serais reconnaissant de me répondre dans les meilleurs délais.\nJe vous prie d''agréer, Madame, Monsieur, mes salutations distinguées.\nKwame Mensah","questions":[{"id":"tq1","question":"Quel est le problème ?","options":["La machine est trop bruyante.","La livraison est en retard.","L''eau ne s''écoule pas de la machine.","Le prix est trop élevé."],"answer":"L''eau ne s''écoule pas de la machine.","explanation":""},{"id":"tq2","question":"Que demande Kwame ?","options":["une nouvelle garantie","un technicien ou un échange","une réduction","un remboursement immédiat"],"answer":"un technicien ou un échange","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"Polite request:","options":["Vous m''aidez.","Tu peux m''aider ?","Aidez-moi !","Pourriez-vous m''aider ?"],"answer":"Pourriez-vous m''aider ?","accepted":[],"explanation":"Conditionnel of pouvoir for politeness.","tag":"politeness-conditional","id":"ex1"},{"type":"mcq","skill":"vocabulary","prompt":"Formal closing:","options":["Bisous !","Je vous prie d''agréer mes salutations distinguées.","À plus !","Salut et merci."],"answer":"Je vous prie d''agréer mes salutations distinguées.","accepted":[],"explanation":"Standard formal closing.","tag":"formal-letter","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"Je vous ___ reconnaissant de me répondre. (être, conditionnel)","options":[],"answer":"serais","accepted":[],"explanation":"être → ser- + -ais.","tag":"politeness-conditional","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["écris","sujet","vous","Je","au","ma","commande","de"],"answer":"Je vous écris au sujet de ma commande","accepted":[],"explanation":"Opening of a formal letter.","tag":"formal-letter","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"I would like a refund, please.\"","options":[],"answer":"Je voudrais un remboursement, s''il vous plaît.","accepted":["J''aimerais un remboursement, s''il vous plaît.","Je voudrais être remboursé, s''il vous plaît."],"explanation":"je voudrais for polite requests.","tag":"politeness-conditional","id":"ex5"}],"writing_prompt":"Écrivez une lettre de réclamation : vous avez reçu un téléphone endommagé.","writing_model":"Madame, Monsieur,\nSuite à ma commande n° 7731 du 2 juin, j''ai reçu hier un téléphone dont l''écran était cassé. Le carton était également endommagé. Je vous joins des photos. Pourriez-vous m''envoyer un nouvel appareil ou me rembourser ? Je vous serais reconnaissant de traiter ma demande rapidement.\nJe vous prie d''agréer, Madame, Monsieur, mes salutations distinguées.","writing_checklist":["structure formelle complète","conditionnel de politesse","faits précis : date, numéro, problème"],"email_snippet":{"word_of_day":{"fr":"se plaindre","en":"to complain","example":"Le client s''est plaint du service."},"mini_question":{"prompt":"Polite request:","options":["Vous m''aidez.","Tu peux m''aider ?","Aidez-moi !","Pourriez-vous m''aider ?"],"answer":"Pourriez-vous m''aider ?"}}}'::jsonb, 'approved', 'curriculum'),
  ('B2', 1, 'Les obligations au travail', '{"level":"B2","seq":1,"theme":"Les obligations au travail","vocabulary":[{"fr":"respecter un délai","en":"to meet a deadline","example":"Il faut que nous respections le délai."},{"fr":"un rapport","en":"a report","example":"Je dois rendre le rapport vendredi."},{"fr":"une réunion","en":"a meeting","example":"La réunion est reportée."},{"fr":"déléguer","en":"to delegate","example":"Un bon manager sait déléguer."},{"fr":"la charge de travail","en":"the workload","example":"Ma charge de travail est énorme."},{"fr":"être débordé","en":"to be swamped","example":"Je suis débordé cette semaine."},{"fr":"prévenir","en":"to warn / inform in advance","example":"Prévenez-moi si vous êtes en retard."},{"fr":"un collaborateur","en":"a co-worker / team member","example":"Elle a cinq collaborateurs."}],"grammar":{"topic":"Le subjonctif présent après il faut que","explanation":"Formation: take the ils form of the present, drop -ent, add -e, -es, -e, -ions, -iez, -ent: ils finissent → que je finisse.\nIrregular: être (que je sois, que nous soyons), avoir (que j''aie, qu''il ait), aller (que j''aille), faire (que je fasse), pouvoir (que je puisse), savoir (que je sache), vouloir (que je veuille).\nUse after expressions of necessity: il faut que, il est nécessaire que, il est important que.\nIf there''s no change of subject, use the infinitive: « Il faut partir. »","examples":["Il faut que tu finisses ce rapport.","Il est important que nous soyons à l''heure.","Il faut qu''elle fasse une pause.","Il est nécessaire que vous preniez une décision."]},"text":{"title":"Message du directeur","body":"Chers collaborateurs,\nComme vous le savez, le projet doit être livré au client le 30 novembre. Pour respecter ce délai, il faut que chaque équipe termine sa partie avant le 20. Il est important que vous signaliez immédiatement tout problème à votre responsable. Par ailleurs, il est essentiel que personne ne fasse d''heures supplémentaires sans accord préalable : la santé de chacun reste notre priorité. Je compte sur vous.\nM. Adeyemi, directeur","questions":[{"id":"tq1","question":"Avant quelle date chaque équipe doit-elle terminer ?","options":["le 20","le 30 novembre","demain","la fin de l''année"],"answer":"le 20","explanation":""},{"id":"tq2","question":"Qu''est-ce qui est interdit sans accord ?","options":["les heures supplémentaires","le télétravail","les réunions","les congés"],"answer":"les heures supplémentaires","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"Il faut que tu ___ ce dossier aujourd''hui.","options":["finis","finisses","finirais","finiras"],"answer":"finisses","accepted":[],"explanation":"il faut que + subjonctif.","tag":"subjunctive","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"Il est important que nous ___ à l''heure.","options":["soyions","soyons","serons","sommes"],"answer":"soyons","accepted":[],"explanation":"être → que nous soyons.","tag":"subjunctive","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"Il faut qu''il ___ ses devoirs. (faire)","options":[],"answer":"fasse","accepted":[],"explanation":"faire → qu''il fasse.","tag":"subjunctive","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["que","preniez","une","vous","Il","faut","décision"],"answer":"Il faut que vous preniez une décision","accepted":[],"explanation":"il faut que + subject + subjonctif.","tag":"subjunctive","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"It is necessary that she goes to the meeting.\"","options":[],"answer":"Il faut qu''elle aille à la réunion.","accepted":["Il est nécessaire qu''elle aille à la réunion."],"explanation":"aller → qu''elle aille.","tag":"subjunctive","id":"ex5"}],"writing_prompt":"Vous êtes responsable d''une équipe. Écrivez un message pour organiser un projet urgent (5 obligations).","writing_model":"Chère équipe, pour finir le projet à temps, il faut que chacun soit disponible lundi matin. Il est important que Tunde prépare le budget et qu''Aïcha contacte le client. Il faut aussi que nous fassions un point tous les jours à 9 h. Enfin, il est essentiel que vous me préveniez en cas de difficulté. Merci à tous.","writing_checklist":["il faut que / il est important que + subjonctif","subjonctifs irréguliers (soit, fasse, aille…)","registre professionnel"],"email_snippet":{"word_of_day":{"fr":"respecter un délai","en":"to meet a deadline","example":"Il faut que nous respections le délai."},"mini_question":{"prompt":"Il faut que tu ___ ce dossier aujourd''hui.","options":["finis","finisses","finirais","finiras"],"answer":"finisses"}}}'::jsonb, 'approved', 'curriculum'),
  ('B2', 2, 'Désirs et émotions', '{"level":"B2","seq":2,"theme":"Désirs et émotions","vocabulary":[{"fr":"souhaiter","en":"to wish","example":"Je souhaite que tu réussisses."},{"fr":"exiger","en":"to demand","example":"Le client exige qu''on le rembourse."},{"fr":"regretter","en":"to regret / be sorry","example":"Je regrette que tu partes."},{"fr":"avoir peur que","en":"to be afraid that","example":"J''ai peur qu''il soit en retard."},{"fr":"être ravi","en":"to be delighted","example":"Je suis ravi que vous soyez là."},{"fr":"déçu","en":"disappointed","example":"Elle est déçue que le concert soit annulé."},{"fr":"étonné","en":"surprised","example":"Je suis étonné qu''il ne dise rien."},{"fr":"fier / fière","en":"proud","example":"Ma mère est fière que j''aie réussi."}],"grammar":{"topic":"Le subjonctif après la volonté et les sentiments","explanation":"Use the subjunctive after verbs of will (vouloir que, souhaiter que, exiger que, préférer que) and emotions (être content / triste / surpris que, avoir peur que, regretter que) when the subject changes.\nSame subject → infinitive: « Je veux partir » but « Je veux que tu partes ».\nespérer que is an exception: it takes the indicative (« J''espère qu''il viendra »).","examples":["Je veux que tu viennes avec moi.","Elle est contente que nous puissions venir.","J''ai peur qu''il fasse froid.","J''espère que tu vas bien."]},"text":{"title":"Une lettre de mère","body":"Mon cher fils,\nJe suis si fière que tu aies obtenu ce poste à Montréal ! Bien sûr, je regrette que tu partes si loin, et j''ai un peu peur que tu te sentes seul pendant l''hiver. Ton père souhaite que tu nous appelles chaque dimanche — tu le connais ! Moi, je voudrais simplement que tu sois heureux. J''espère que tu trouveras vite des amis.\nJe t''embrasse,\nMaman","questions":[{"id":"tq1","question":"De quoi la mère a-t-elle peur ?","options":["que son fils se sente seul","qu''il tombe malade","qu''il oublie le français","qu''il perde son poste"],"answer":"que son fils se sente seul","explanation":""},{"id":"tq2","question":"Que souhaite le père ?","options":["que son fils appelle chaque dimanche","qu''il rentre vite","qu''il change de travail","qu''il trouve des amis"],"answer":"que son fils appelle chaque dimanche","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"Je veux que tu ___ la vérité.","options":["dire","dis","dises","diras"],"answer":"dises","accepted":[],"explanation":"vouloir que + subjonctif.","tag":"subjunctive-will","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"J''espère qu''il ___ demain.","options":["venir","vienne","viendrait","viendra"],"answer":"viendra","accepted":[],"explanation":"espérer que + indicative.","tag":"subjunctive-exceptions","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"Je suis ravi que vous ___ venir. (pouvoir)","options":[],"answer":"puissiez","accepted":[],"explanation":"pouvoir → que vous puissiez.","tag":"subjunctive-emotion","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["son","peur","a","fils","que","malade","Elle","soit"],"answer":"Elle a peur que son fils soit malade","accepted":[],"explanation":"avoir peur que + subjonctif.","tag":"subjunctive-emotion","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"I''m sorry that you can''t come.\"","options":[],"answer":"Je regrette que tu ne puisses pas venir.","accepted":["Je regrette que vous ne puissiez pas venir.","Je suis désolé que tu ne puisses pas venir."],"explanation":"regretter que + subjonctif.","tag":"subjunctive-emotion","id":"ex5"}],"writing_prompt":"Un ami part vivre à l''étranger. Écrivez-lui un message exprimant vos sentiments et vos souhaits.","writing_model":"Cher Femi, je suis vraiment heureux que tu aies trouvé ce travail à Paris, même si je regrette que tu partes si vite. J''ai un peu peur que nous perdions le contact, alors je voudrais que tu m''écrives de temps en temps. J''espère que tu t''adapteras facilement. Je souhaite que cette aventure soit magnifique !","writing_checklist":["sentiments + que + subjonctif","volonté + que + subjonctif","espérer + indicatif"],"email_snippet":{"word_of_day":{"fr":"souhaiter","en":"to wish","example":"Je souhaite que tu réussisses."},"mini_question":{"prompt":"Je veux que tu ___ la vérité.","options":["dire","dis","dises","diras"],"answer":"dises"}}}'::jsonb, 'approved', 'curriculum'),
  ('B2', 3, 'Bien que, pour que, avant que', '{"level":"B2","seq":3,"theme":"Bien que, pour que, avant que","vocabulary":[{"fr":"malgré","en":"despite","example":"Malgré la pluie, le match a eu lieu."},{"fr":"afin de / afin que","en":"in order to / so that","example":"Il parle lentement afin que tout le monde comprenne."},{"fr":"à moins que","en":"unless","example":"Je viendrai, à moins qu''il pleuve."},{"fr":"jusqu''à ce que","en":"until","example":"Attends jusqu''à ce que je revienne."},{"fr":"sans que","en":"without","example":"Il est parti sans que je le voie."},{"fr":"une contrainte","en":"a constraint","example":"Le budget est une contrainte."},{"fr":"un compromis","en":"a compromise","example":"Ils ont trouvé un compromis."},{"fr":"néanmoins","en":"nevertheless","example":"C''est difficile ; néanmoins, c''est possible."}],"grammar":{"topic":"Les conjonctions suivies du subjonctif","explanation":"These conjunctions always take the subjunctive: bien que / quoique (although), pour que / afin que (so that), avant que (before), jusqu''à ce que (until), à moins que (unless), sans que (without), à condition que (provided that).\nIf the subject is the same, use a preposition + infinitive instead: pour partir, avant de partir, sans dire, afin de comprendre.\nBUT après que takes the indicative in standard French.","examples":["Bien qu''il soit fatigué, il continue.","Je t''explique pour que tu comprennes.","Rentre avant qu''il fasse nuit.","Je partirai après qu''il sera arrivé."]},"text":{"title":"Le marathon de Lagos","body":"Bien qu''il ait commencé à courir il y a seulement un an, Emeka a terminé le marathon de Lagos en quatre heures. Il s''est entraîné tous les matins avant que la chaleur ne devienne trop forte. Son entraîneur l''a suivi de près afin qu''il ne se blesse pas. « Je ne pensais pas réussir à moins d''avoir de la chance », dit-il en riant. Malgré la fatigue, il prépare déjà le prochain, à condition que son genou tienne le coup.","questions":[{"id":"tq1","question":"Pourquoi s''entraînait-il le matin ?","options":["parce que la route était fermée","pour courir avec son entraîneur","parce qu''il travaillait le soir","avant qu''il fasse trop chaud"],"answer":"avant qu''il fasse trop chaud","explanation":""},{"id":"tq2","question":"À quelle condition fera-t-il le prochain marathon ?","options":["si son genou tient le coup","si son entraîneur est d''accord","s''il gagne de l''argent","s''il a de la chance"],"answer":"si son genou tient le coup","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"Bien qu''il ___ riche, il vit simplement.","options":["soit","sera","est","était"],"answer":"soit","accepted":[],"explanation":"bien que + subjonctif.","tag":"conjunctions-subjunctive","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"Je parle fort ___ tout le monde m''entende.","options":["parce que","pour que","pour","après que"],"answer":"pour que","accepted":[],"explanation":"Purpose + change of subject → pour que + subjonctif.","tag":"conjunctions-subjunctive","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"Finis ton travail avant de ___. (partir — same subject)","options":[],"answer":"partir","accepted":[],"explanation":"Same subject → avant de + infinitive.","tag":"conjunctions-infinitive","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["nous","sachions","le","sans","que","parti","Il","est"],"answer":"Il est parti sans que nous le sachions","accepted":[],"explanation":"sans que + subjonctif.","tag":"conjunctions-subjunctive","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"I will wait until you come back.\"","options":[],"answer":"J''attendrai jusqu''à ce que tu reviennes.","accepted":["J''attendrai jusqu''à ce que vous reveniez."],"explanation":"jusqu''à ce que + subjonctif.","tag":"conjunctions-subjunctive","id":"ex5"}],"writing_prompt":"Racontez un défi que vous avez relevé malgré des difficultés (utilisez au moins trois conjonctions + subjonctif).","writing_model":"L''année dernière, j''ai passé le DELF B1 bien que je n''aie eu que trois mois pour me préparer. Je révisais chaque soir avant que les enfants ne se réveillent le matin, puis je relisais mes notes jusqu''à ce que je les connaisse par cœur. Ma femme m''aidait pour que je puisse pratiquer l''oral. Malgré le stress, j''ai réussi !","writing_checklist":["bien que / pour que / avant que / jusqu''à ce que + subjonctif","malgré + nom","après que + indicatif si utilisé"],"email_snippet":{"word_of_day":{"fr":"malgré","en":"despite","example":"Malgré la pluie, le match a eu lieu."},"mini_question":{"prompt":"Bien qu''il ___ riche, il vit simplement.","options":["soit","sera","est","était"],"answer":"soit"}}}'::jsonb, 'approved', 'curriculum'),
  ('B2', 4, 'Regrets et hypothèses', '{"level":"B2","seq":4,"theme":"Regrets et hypothèses","vocabulary":[{"fr":"regretter de","en":"to regret","example":"Je regrette de ne pas avoir étudié."},{"fr":"une occasion","en":"an opportunity","example":"J''ai raté une belle occasion."},{"fr":"si seulement","en":"if only","example":"Si seulement je l''avais su !"},{"fr":"prendre une décision","en":"to make a decision","example":"Il a pris la mauvaise décision."},{"fr":"le hasard","en":"chance","example":"Je l''ai rencontré par hasard."},{"fr":"éviter","en":"to avoid","example":"Nous aurions pu éviter cette erreur."},{"fr":"la conséquence","en":"the consequence","example":"Les conséquences ont été graves."},{"fr":"un tournant","en":"a turning point","example":"Ce voyage a été un tournant dans ma vie."}],"grammar":{"topic":"Le conditionnel passé et le si irréel du passé","explanation":"Conditionnel passé = avoir / être in the conditionnel + past participle: j''aurais fait, elle serait venue.\nUses: regret (« J''aurais dû partir »), reproach (« Tu aurais pu m''appeler ! »), unconfirmed information in the news (« L''accident aurait fait trois victimes »).\nPast hypothesis: si + plus-que-parfait → conditionnel passé: « Si j''avais su, je serais venu. »","examples":["Si tu m''avais prévenu, je t''aurais aidé.","J''aurais aimé voyager davantage.","Elle serait partie plus tôt si elle avait pu.","Le président aurait démissionné."]},"text":{"title":"Et si j''avais dit non ?","body":"Il y a dix ans, Rachida a refusé un poste stable dans une banque pour créer une petite entreprise de mode. « Si j''avais accepté ce poste, j''aurais eu un bon salaire, mais je n''aurais jamais connu cette liberté », explique-t-elle. Elle reconnaît qu''elle aurait pu éviter certaines erreurs : « J''aurais dû demander plus de conseils au début. » Aujourd''hui, son entreprise emploie vingt personnes et vend ses créations dans six pays.","questions":[{"id":"tq1","question":"Qu''a refusé Rachida ?","options":["une bourse","un voyage","un poste dans une banque","un prêt"],"answer":"un poste dans une banque","explanation":""},{"id":"tq2","question":"Quel regret exprime-t-elle ?","options":["ne pas avoir voyagé","avoir quitté la banque","ne pas avoir demandé assez de conseils","avoir créé l''entreprise"],"answer":"ne pas avoir demandé assez de conseils","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"Si j''avais su, je ___ venu.","options":["suis","serais","serai","étais"],"answer":"serais","accepted":[],"explanation":"si + plus-que-parfait → conditionnel passé.","tag":"conditional-past","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"Si tu ___ plus tôt, tu aurais vu le début.","options":["es arrivé","étais arrivé","arrivais","serais arrivé"],"answer":"étais arrivé","accepted":[],"explanation":"si + plus-que-parfait.","tag":"conditional-past","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"Tu ___ dû me le dire ! (avoir, reproach)","options":[],"answer":"aurais","accepted":[],"explanation":"Reproach: tu aurais dû.","tag":"conditional-past","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["le","J''aurais","piano","apprendre","aimé"],"answer":"J''aurais aimé apprendre le piano","accepted":[],"explanation":"Regret with conditionnel passé.","tag":"conditional-past","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"If we had left earlier, we would have caught the train.\"","options":[],"answer":"Si nous étions partis plus tôt, nous aurions pris le train.","accepted":["Si on était partis plus tôt, on aurait pris le train.","Si nous étions partis plus tôt, nous n''aurions pas raté le train."],"explanation":"si + plus-que-parfait, conditionnel passé.","tag":"conditional-past","id":"ex5"}],"writing_prompt":"Pensez à une décision importante de votre vie. Que se serait-il passé si vous aviez fait un autre choix ?","writing_model":"Après l''université, j''ai choisi de rester au Nigeria au lieu de partir étudier en Angleterre. Si j''étais parti, j''aurais peut-être obtenu un diplôme plus prestigieux, mais je n''aurais pas rencontré ma femme. J''aurais aimé voyager davantage à cette époque. Pourtant, je ne regrette pas : si je n''étais pas resté, je n''aurais jamais créé mon entreprise.","writing_checklist":["si + plus-que-parfait → conditionnel passé","j''aurais dû / j''aurais aimé","accord avec être (serais parti(e))"],"email_snippet":{"word_of_day":{"fr":"regretter de","en":"to regret","example":"Je regrette de ne pas avoir étudié."},"mini_question":{"prompt":"Si j''avais su, je ___ venu.","options":["suis","serais","serai","étais"],"answer":"serais"}}}'::jsonb, 'approved', 'curriculum'),
  ('B2', 5, 'La voix passive', '{"level":"B2","seq":5,"theme":"La voix passive","vocabulary":[{"fr":"construire","en":"to build","example":"Le pont a été construit en 1990."},{"fr":"inaugurer","en":"to inaugurate / open","example":"Le musée sera inauguré en mai."},{"fr":"élire","en":"to elect","example":"Le maire a été élu l''an dernier."},{"fr":"arrêter","en":"to arrest / stop","example":"Le suspect a été arrêté."},{"fr":"publier","en":"to publish","example":"Le rapport sera publié demain."},{"fr":"détruire","en":"to destroy","example":"La maison a été détruite par le feu."},{"fr":"une enquête","en":"an investigation / survey","example":"Une enquête a été ouverte."},{"fr":"les autorités (f.)","en":"the authorities","example":"Les autorités ont été informées."}],"grammar":{"topic":"La voix passive","explanation":"Passive = être (in the tense of the active verb) + past participle (agreeing with the subject) + par + agent.\nActive: La police a arrêté les voleurs. → Passive: Les voleurs ont été arrêtés par la police.\nThe agent is often omitted. With verbs of feeling or state, de may replace par: « Il est aimé de tous. »\nFrench often prefers on or a pronominal verb to the passive: « On a construit le pont » / « Ce plat se mange froid. »","examples":["Le pont a été construit par une entreprise chinoise.","Les résultats seront publiés lundi.","La décision est prise par le directeur.","Ce livre est lu dans le monde entier."]},"text":{"title":"Un nouveau stade","body":"Le nouveau stade de la ville a été inauguré samedi par le ministre des Sports. Il a été construit en deux ans et peut accueillir 40 000 spectateurs. Le projet avait été critiqué par plusieurs associations à cause de son coût. Selon la mairie, le stade sera aussi utilisé pour des concerts. Une enquête sur le budget a cependant été ouverte la semaine dernière.","questions":[{"id":"tq1","question":"Par qui le stade a-t-il été inauguré ?","options":["par le ministre des Sports","par le maire","par le président","par des associations"],"answer":"par le ministre des Sports","explanation":""},{"id":"tq2","question":"Pourquoi le projet avait-il été critiqué ?","options":["à cause des concerts","à cause de son coût","à cause du bruit","parce qu''il était trop petit"],"answer":"à cause de son coût","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"Active: Le chef prépare le repas. → Passive:","options":["Le repas a préparé le chef.","Le repas est préparé par le chef.","Le repas est préparer par le chef.","Le chef est préparé par le repas."],"answer":"Le repas est préparé par le chef.","accepted":[],"explanation":"être (present) + participle + par.","tag":"passive-voice","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"La maison ___ vendue l''année dernière.","options":["avait","a été","est été","sera"],"answer":"a été","accepted":[],"explanation":"Past passive: a été + participle.","tag":"passive-voice","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"Les lettres ont été ___ par la secrétaire. (écrire)","options":[],"answer":"écrites","accepted":[],"explanation":"Agreement with lettres (f. pl.).","tag":"passive-agreement","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["a","été","par","suspect","Le","la","arrêté","police"],"answer":"Le suspect a été arrêté par la police","accepted":[],"explanation":"Subject + a été + participle + par + agent.","tag":"passive-voice","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"The results will be announced tomorrow.\"","options":[],"answer":"Les résultats seront annoncés demain.","accepted":[],"explanation":"Future passive: seront + participle.","tag":"passive-voice","id":"ex5"}],"writing_prompt":"Rédigez un court article de presse (5 phrases) sur un événement local en utilisant la voix passive.","writing_model":"Un nouvel hôpital a été inauguré hier à Ibadan. Il a été financé par le gouvernement de l''État et construit en dix-huit mois. Cent lits ont été installés et deux cents infirmiers seront recrutés d''ici la fin de l''année. Le projet a été salué par les habitants. Les premiers patients seront accueillis lundi.","writing_checklist":["être + participe passé accordé","différents temps (passé, futur)","par + agent quand c''est utile"],"email_snippet":{"word_of_day":{"fr":"construire","en":"to build","example":"Le pont a été construit en 1990."},"mini_question":{"prompt":"Active: Le chef prépare le repas. → Passive:","options":["Le repas a préparé le chef.","Le repas est préparé par le chef.","Le repas est préparer par le chef.","Le chef est préparé par le repas."],"answer":"Le repas est préparé par le chef."}}}'::jsonb, 'approved', 'curriculum'),
  ('B2', 6, 'Rapporter des paroles au passé', '{"level":"B2","seq":6,"theme":"Rapporter des paroles au passé","vocabulary":[{"fr":"déclarer","en":"to declare","example":"Le ministre a déclaré qu''il démissionnerait."},{"fr":"expliquer","en":"to explain","example":"Elle a expliqué qu''elle était malade."},{"fr":"promettre","en":"to promise","example":"Il a promis qu''il viendrait."},{"fr":"avouer","en":"to admit","example":"Il a avoué qu''il avait menti."},{"fr":"prétendre","en":"to claim","example":"Il prétend qu''il n''était pas là."},{"fr":"la veille","en":"the day before","example":"Il m''a dit qu''il était arrivé la veille."},{"fr":"le lendemain","en":"the next day","example":"Elle a promis de revenir le lendemain."},{"fr":"un témoin","en":"a witness","example":"Le témoin a affirmé qu''il avait tout vu."}],"grammar":{"topic":"Le discours indirect au passé (concordance des temps)","explanation":"When the reporting verb is in the past (il a dit, elle expliquait), tenses shift back:\n• présent → imparfait (« Je suis prêt » → il a dit qu''il était prêt)\n• passé composé → plus-que-parfait (« J''ai fini » → qu''il avait fini)\n• futur → conditionnel présent (« Je viendrai » → qu''il viendrait)\n• imparfait, plus-que-parfait and conditionnel don''t change.\nTime words change: aujourd''hui → ce jour-là, hier → la veille, demain → le lendemain, la semaine prochaine → la semaine suivante.","examples":["Il a dit qu''il était fatigué.","Elle m''a expliqué qu''elle avait perdu ses clés.","Ils ont promis qu''ils viendraient le lendemain.","Il m''a demandé si j''avais compris."]},"text":{"title":"Un témoignage","body":"Le témoin a raconté à la police qu''il rentrait du travail vers 22 heures quand il avait entendu un grand bruit. Il a expliqué qu''il avait vu deux hommes sortir de la bijouterie et qu''ils étaient partis en moto. Il a ajouté qu''il ne pouvait pas décrire leurs visages parce qu''il faisait trop sombre. Enfin, il a promis qu''il reviendrait le lendemain pour signer sa déposition.","questions":[{"id":"tq1","question":"Comment les voleurs sont-ils partis ?","options":["en moto","à pied","en voiture","en bus"],"answer":"en moto","explanation":""},{"id":"tq2","question":"Pourquoi le témoin ne peut-il pas décrire les visages ?","options":["Il avait peur.","Ils portaient des masques.","Il faisait trop sombre.","Il était trop loin."],"answer":"Il faisait trop sombre.","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"« Je suis malade. » → Elle a dit qu''elle ___ malade.","options":["était","est","soit","sera"],"answer":"était","accepted":[],"explanation":"présent → imparfait.","tag":"reported-speech-past","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"« Je viendrai. » → Il a promis qu''il ___.","options":["venait","est venu","viendrait","viendra"],"answer":"viendrait","accepted":[],"explanation":"futur → conditionnel.","tag":"reported-speech-past","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"« J''ai fini. » → Il a dit qu''il ___ fini.","options":[],"answer":"avait","accepted":[],"explanation":"passé composé → plus-que-parfait.","tag":"reported-speech-past","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["qu''elle","m''a","dit","le","partirait","Elle","lendemain"],"answer":"Elle m''a dit qu''elle partirait le lendemain","accepted":[],"explanation":"Concordance: futur → conditionnel; demain → le lendemain.","tag":"reported-speech-past","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"He told me he had lost his keys the day before.\"","options":[],"answer":"Il m''a dit qu''il avait perdu ses clés la veille.","accepted":[],"explanation":"passé composé → plus-que-parfait; hier → la veille.","tag":"reported-speech-past","id":"ex5"}],"writing_prompt":"Rapportez au passé une conversation importante (entretien, dispute, annonce) en utilisant la concordance des temps.","writing_model":"Lors de mon entretien, la directrice m''a demandé pourquoi je voulais quitter mon poste. Je lui ai répondu que je cherchais de nouveaux défis et que j''avais toujours rêvé de travailler à l''international. Elle m''a expliqué que l''équipe était jeune et qu''elle voyagerait beaucoup. Elle a promis qu''elle me rappellerait la semaine suivante.","writing_checklist":["concordance des temps (imparfait, plus-que-parfait, conditionnel)","transformation des marqueurs de temps","verbes introducteurs variés"],"email_snippet":{"word_of_day":{"fr":"déclarer","en":"to declare","example":"Le ministre a déclaré qu''il démissionnerait."},"mini_question":{"prompt":"« Je suis malade. » → Elle a dit qu''elle ___ malade.","options":["était","est","soit","sera"],"answer":"était"}}}'::jsonb, 'approved', 'curriculum'),
  ('B2', 7, 'Argumenter', '{"level":"B2","seq":7,"theme":"Argumenter","vocabulary":[{"fr":"d''abord / tout d''abord","en":"first of all","example":"Tout d''abord, rappelons les faits."},{"fr":"de plus / en outre","en":"moreover","example":"De plus, cette solution est économique."},{"fr":"en revanche","en":"on the other hand","example":"En revanche, elle est difficile à appliquer."},{"fr":"par conséquent","en":"consequently","example":"Par conséquent, nous devons agir."},{"fr":"certes","en":"admittedly","example":"Certes, le projet est coûteux."},{"fr":"or","en":"yet / now (in an argument)","example":"Il faut investir ; or, le budget est limité."},{"fr":"en somme / en conclusion","en":"in short / in conclusion","example":"En conclusion, les avantages l''emportent."},{"fr":"un enjeu","en":"a stake / an issue","example":"C''est un enjeu majeur pour l''avenir."}],"grammar":{"topic":"Les connecteurs logiques","explanation":"Organise an argument with connectors:\n• adding: de plus, en outre, par ailleurs\n• contrasting: mais, cependant, en revanche, pourtant, toutefois\n• conceding: certes… mais, bien que + subjonctif, même si + indicatif\n• cause: car, puisque, en effet, étant donné que\n• consequence: donc, par conséquent, c''est pourquoi, si bien que\n• concluding: en conclusion, en somme, pour conclure.","examples":["Certes, internet facilite la vie, mais il crée aussi une dépendance.","Le prix a augmenté ; par conséquent, les ventes ont baissé.","Même si c''est difficile, il faut essayer.","En outre, cette mesure protège l''environnement."]},"text":{"title":"Faut-il rendre les transports publics gratuits ?","body":"Plusieurs villes européennes ont rendu leurs transports publics gratuits. Certes, cette mesure coûte cher aux collectivités. En revanche, elle encourage les habitants à laisser leur voiture au garage ; par conséquent, la pollution et les embouteillages diminuent. De plus, elle aide les familles modestes. Toutefois, certains experts soulignent que la gratuité ne suffit pas : si les bus sont rares ou lents, les automobilistes ne changeront pas leurs habitudes. En somme, la gratuité est utile, à condition d''améliorer aussi le service.","questions":[{"id":"tq1","question":"Quel argument est présenté contre la gratuité ?","options":["Elle augmente la pollution.","Elle rend les bus plus rapides.","Elle coûte cher aux collectivités.","Elle nuit aux familles modestes."],"answer":"Elle coûte cher aux collectivités.","explanation":""},{"id":"tq2","question":"Quelle est la conclusion du texte ?","options":["La gratuité est inutile.","Il faut interdire les voitures.","La gratuité est utile si le service s''améliore aussi.","Il faut supprimer les bus."],"answer":"La gratuité est utile si le service s''améliore aussi.","explanation":""}]},"exercises":[{"type":"mcq","skill":"vocabulary","prompt":"Le projet est utile ; ___, il coûte très cher.","options":["en revanche","de plus","par conséquent","en effet"],"answer":"en revanche","accepted":[],"explanation":"Contrast → en revanche.","tag":"connectors","id":"ex1"},{"type":"mcq","skill":"vocabulary","prompt":"Il a beaucoup plu ; ___, la route est fermée.","options":["or","par conséquent","toutefois","certes"],"answer":"par conséquent","accepted":[],"explanation":"Consequence → par conséquent.","tag":"connectors","id":"ex2"},{"type":"fill_blank","skill":"vocabulary","prompt":"___, ce n''est pas facile, mais c''est possible. (admittedly)","options":[],"answer":"Certes","accepted":["certes"],"explanation":"Concession → certes… mais.","tag":"connectors","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["élevé","si","le","qualité","Même","la","prix","est","est","excellente"],"answer":"Même si le prix est élevé la qualité est excellente","accepted":[],"explanation":"même si + indicatif.","tag":"concession","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"Moreover, this solution protects the environment.\"","options":[],"answer":"De plus, cette solution protège l''environnement.","accepted":["En outre, cette solution protège l''environnement."],"explanation":"Adding an argument → de plus / en outre.","tag":"connectors","id":"ex5"}],"writing_prompt":"Les réseaux sociaux font-ils plus de bien que de mal ? Rédigez un paragraphe argumenté (150 mots) avec au moins cinq connecteurs.","writing_model":"Tout d''abord, les réseaux sociaux permettent de rester en contact avec sa famille, même à des milliers de kilomètres. De plus, ils offrent aux petites entreprises une visibilité gratuite. Certes, ils présentent aussi des dangers : les fausses informations y circulent vite et beaucoup de jeunes y passent trop de temps. Or, ces problèmes viennent surtout de l''usage qu''on en fait. Par conséquent, il me semble plus utile d''éduquer les utilisateurs que d''interdire ces plateformes. En conclusion, les réseaux sociaux font plus de bien que de mal, à condition qu''on les utilise avec esprit critique.","writing_checklist":["introduction, arguments, concession, conclusion","au moins cinq connecteurs variés","un subjonctif (à condition que…)"],"email_snippet":{"word_of_day":{"fr":"d''abord / tout d''abord","en":"first of all","example":"Tout d''abord, rappelons les faits."},"mini_question":{"prompt":"Le projet est utile ; ___, il coûte très cher.","options":["en revanche","de plus","par conséquent","en effet"],"answer":"en revanche"}}}'::jsonb, 'approved', 'curriculum'),
  ('B2', 8, 'L''accord du participe passé', '{"level":"B2","seq":8,"theme":"L''accord du participe passé","vocabulary":[{"fr":"la lettre","en":"the letter","example":"Les lettres que j''ai reçues sont anciennes."},{"fr":"les photos (f.)","en":"the photos","example":"Voici les photos qu''il a prises."},{"fr":"la décision","en":"the decision","example":"La décision qu''ils ont prise est juste."},{"fr":"les fleurs (f.)","en":"the flowers","example":"Les fleurs que tu m''as offertes sont belles."},{"fr":"la clé","en":"the key","example":"Je l''ai perdue."},{"fr":"les erreurs (f.)","en":"the mistakes","example":"Quelles erreurs avez-vous faites ?"},{"fr":"relire","en":"to reread","example":"Tu as relu ta lettre ?"},{"fr":"une faute d''orthographe","en":"a spelling mistake","example":"Il y a trop de fautes d''orthographe."}],"grammar":{"topic":"L''accord du participe passé avec avoir","explanation":"With avoir, the past participle does NOT agree with the subject. It agrees with the direct object (COD) only if the COD comes BEFORE the verb:\n• « J''ai acheté des fleurs. » (COD after → no agreement)\n• « Les fleurs que j''ai achetées » (que = les fleurs, before)\n• « Ces fleurs, je les ai achetées. » (les before)\n• « Quelles fleurs as-tu achetées ? »\nNo agreement with en: « Des pommes ? J''en ai mangé. »","examples":["La robe qu''elle a choisie est rouge.","Mes clés ? Je les ai trouvées.","Les efforts que nous avons faits ont payé.","Combien de livres as-tu lus ?"]},"text":{"title":"Correction de copie","body":"Le professeur a rendu les rédactions qu''il avait corrigées pendant le week-end. Awa était inquiète : elle avait écrit sa copie très vite. En la relisant, elle a découvert les fautes qu''elle avait faites. Le professeur les avait toutes soulignées en rouge, surtout les accords du participe passé. Mais il avait aussi écrit : « Les idées que tu as développées sont excellentes. »","questions":[{"id":"tq1","question":"Quelles fautes Awa avait-elle surtout faites ?","options":["des erreurs de ponctuation","des accords du participe passé","des fautes de conjugaison au futur","des fautes de vocabulaire"],"answer":"des accords du participe passé","explanation":""},{"id":"tq2","question":"Quel compliment le professeur a-t-il fait ?","options":["L''écriture est belle.","Le texte est court.","Les idées sont excellentes.","Il n''y a aucune faute."],"answer":"Les idées sont excellentes.","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"Les fleurs que tu m''as ___ sont magnifiques.","options":["offerts","offert","offertes","offerte"],"answer":"offertes","accepted":[],"explanation":"COD que (= les fleurs, f. pl.) before → offertes.","tag":"past-participle-agreement","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"Elle a ___ des chaussures.","options":["acheté","achetés","achetée","achetées"],"answer":"acheté","accepted":[],"explanation":"COD after the verb → no agreement.","tag":"past-participle-agreement","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"Ma montre ? Je l''ai ___ hier. (perdre)","options":[],"answer":"perdue","accepted":[],"explanation":"l'' = la montre (f.) before → perdue.","tag":"past-participle-agreement","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["les","Voici","j''ai","écrites","lettres","que"],"answer":"Voici les lettres que j''ai écrites","accepted":[],"explanation":"que + avoir + agreed participle.","tag":"past-participle-agreement","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"Which films have you seen?\"","options":[],"answer":"Quels films as-tu vus ?","accepted":["Quels films avez-vous vus ?"],"explanation":"Quels films (m. pl.) before → vus.","tag":"past-participle-agreement","id":"ex5"}],"writing_prompt":"Décrivez les cadeaux que vous avez reçus ou offerts récemment, en faisant attention aux accords.","writing_model":"Pour mon anniversaire, ma sœur m''a offert une montre. Je l''ai portée tous les jours depuis. Les livres que mes collègues m''ont donnés sont passionnants : je les ai déjà lus. Quant aux fleurs que ma mère a envoyées, je les ai mises dans le salon.","writing_checklist":["accord avec le COD placé avant (que, les, l'')","pas d''accord avec le sujet quand on utilise avoir","pas d''accord avec en"],"email_snippet":{"word_of_day":{"fr":"la lettre","en":"the letter","example":"Les lettres que j''ai reçues sont anciennes."},"mini_question":{"prompt":"Les fleurs que tu m''as ___ sont magnifiques.","options":["offerts","offert","offertes","offerte"],"answer":"offertes"}}}'::jsonb, 'approved', 'curriculum'),
  ('B2', 9, 'Lequel, auquel, duquel', '{"level":"B2","seq":9,"theme":"Lequel, auquel, duquel","vocabulary":[{"fr":"l''outil (m.)","en":"the tool","example":"C''est l''outil avec lequel je travaille."},{"fr":"le projet","en":"the project","example":"Le projet auquel je participe est passionnant."},{"fr":"le bâtiment","en":"the building","example":"Le bâtiment près duquel j''habite est ancien."},{"fr":"l''association (f.)","en":"the association / charity","example":"L''association pour laquelle elle travaille aide les réfugiés."},{"fr":"la raison","en":"the reason","example":"C''est la raison pour laquelle je suis parti."},{"fr":"la conférence","en":"the conference","example":"La conférence à laquelle j''ai assisté était intéressante."},{"fr":"au cours de","en":"during","example":"Au cours de la réunion, il a parlé."},{"fr":"grâce à","en":"thanks to","example":"Grâce à lui, j''ai trouvé un travail."}],"grammar":{"topic":"Les pronoms relatifs composés","explanation":"After a preposition, use lequel, laquelle, lesquels, lesquelles (for things, agreeing with the noun): avec lequel, pour laquelle, sur lesquels.\nà + lequel → auquel, à laquelle, auxquels, auxquelles.\nde + lequel → duquel, de laquelle, desquels, desquelles (with compound prepositions: près de, à côté de, au cours de…).\nFor people, qui is usually preferred: « la personne avec qui je travaille ».","examples":["Le stylo avec lequel j''écris est bleu.","Le concours auquel il participe est difficile.","La rivière au bord de laquelle nous avons pique-niqué.","L''amie pour qui j''ai acheté ce cadeau."]},"text":{"title":"Une association de quartier","body":"L''association pour laquelle travaille Nadia aide les jeunes du quartier à trouver un emploi. Le local dans lequel elle organise ses ateliers est petit, mais bien équipé. Les entreprises auxquelles elle envoie les CV sont de plus en plus nombreuses. Au cours de la dernière réunion, au terme de laquelle tout le monde a applaudi, Nadia a annoncé que trente jeunes avaient été embauchés cette année.","questions":[{"id":"tq1","question":"Que fait l''association ?","options":["Elle organise des concerts.","Elle donne des bourses.","Elle aide les jeunes à trouver un emploi.","Elle construit des locaux."],"answer":"Elle aide les jeunes à trouver un emploi.","explanation":""},{"id":"tq2","question":"Combien de jeunes ont été embauchés ?","options":["vingt","treize","trente","cent"],"answer":"trente","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"La raison pour ___ il est parti reste un mystère.","options":["quoi","laquelle","lequel","qui"],"answer":"laquelle","accepted":[],"explanation":"raison (f.) → laquelle.","tag":"relative-lequel","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"Le projet ___ je pense est ambitieux. (penser à)","options":["lequel","duquel","auquel","dont"],"answer":"auquel","accepted":[],"explanation":"à + lequel → auquel.","tag":"relative-lequel","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"La maison près ___ il habite est à vendre.","options":[],"answer":"de laquelle","accepted":[],"explanation":"près de + laquelle.","tag":"relative-lequel","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["je","avec","lequel","l''ordinateur","C''est","travaille"],"answer":"C''est l''ordinateur avec lequel je travaille","accepted":[],"explanation":"preposition + lequel.","tag":"relative-lequel","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"The meetings I take part in are long.\"","options":[],"answer":"Les réunions auxquelles je participe sont longues.","accepted":[],"explanation":"participer à + réunions (f. pl.) → auxquelles.","tag":"relative-lequel","id":"ex5"}],"writing_prompt":"Présentez une organisation, un club ou une entreprise que vous connaissez, avec au moins trois pronoms relatifs composés.","writing_model":"L''entreprise pour laquelle je travaille développe des applications bancaires. Les clients avec lesquels nous collaborons sont en Afrique de l''Ouest. Le projet auquel je consacre le plus de temps est une application de paiement mobile. Le bureau à côté duquel se trouve notre cantine est très moderne.","writing_checklist":["lequel / laquelle / lesquels après préposition","auquel / duquel et leurs formes","accord avec le nom repris"],"email_snippet":{"word_of_day":{"fr":"l''outil (m.)","en":"the tool","example":"C''est l''outil avec lequel je travaille."},"mini_question":{"prompt":"La raison pour ___ il est parti reste un mystère.","options":["quoi","laquelle","lequel","qui"],"answer":"laquelle"}}}'::jsonb, 'approved', 'curriculum'),
  ('B2', 10, 'Projeter l''avenir', '{"level":"B2","seq":10,"theme":"Projeter l''avenir","vocabulary":[{"fr":"d''ici (à) 2030","en":"by 2030","example":"D''ici 2030, la ville aura doublé."},{"fr":"dès que","en":"as soon as","example":"Dès que j''aurai fini, je t''appellerai."},{"fr":"une fois que","en":"once","example":"Une fois que tu auras signé, ce sera officiel."},{"fr":"achever","en":"to complete","example":"Les travaux seront achevés en mai."},{"fr":"atteindre un objectif","en":"to reach a goal","example":"Nous aurons atteint notre objectif."},{"fr":"prévoir","en":"to plan / forecast","example":"Les experts prévoient une hausse."},{"fr":"à long terme","en":"in the long term","example":"À long terme, c''est rentable."},{"fr":"la croissance","en":"growth","example":"La croissance sera forte."}],"grammar":{"topic":"Le futur antérieur","explanation":"Futur antérieur = avoir / être in the futur simple + past participle: j''aurai fini, elle sera partie.\nIt expresses a future action completed BEFORE another future action or a future moment: « Quand tu arriveras, j''aurai préparé le dîner. »\nCommon after quand, lorsque, dès que, une fois que, après que: « Dès que j''aurai reçu ma paie, je t''achèterai un cadeau. »\nIt can also express a supposition about the past: « Il n''est pas là ? Il aura oublié. »","examples":["D''ici juin, nous aurons terminé le projet.","Dès qu''il sera arrivé, nous commencerons.","Une fois que vous aurez lu le contrat, signez-le.","Elle aura raté son bus."]},"text":{"title":"La ville en 2040","body":"Selon le plan d''urbanisme présenté hier, la ville aura profondément changé d''ici 2040. Une nouvelle ligne de métro aura été construite et les vieux quartiers du centre auront été rénovés. Dès que les premiers travaux seront achevés, en 2027, un grand parc ouvrira au bord du fleuve. Le maire espère qu''une fois que ces projets auront été réalisés, la population aura retrouvé confiance dans l''avenir de la ville.","questions":[{"id":"tq1","question":"Que se passera-t-il quand les premiers travaux seront finis ?","options":["le métro fonctionnera","la population doublera","un parc ouvrira au bord du fleuve","le maire démissionnera"],"answer":"un parc ouvrira au bord du fleuve","explanation":""},{"id":"tq2","question":"D''ici quand la ville aura-t-elle changé ?","options":["l''année prochaine","2040","2027","2030"],"answer":"2040","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"Quand tu arriveras, nous ___ déjà mangé.","options":["aurons","avions","avons","aurions"],"answer":"aurons","accepted":[],"explanation":"Completed before another future action → futur antérieur.","tag":"futur-anterieur","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"Dès qu''elle ___, nous partirons.","options":["sera arrivée","arrive","est arrivée","serait arrivée"],"answer":"sera arrivée","accepted":[],"explanation":"dès que + futur antérieur.","tag":"futur-anterieur","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"D''ici ce soir, j''___ fini ce rapport. (avoir)","options":[],"answer":"aurai","accepted":[],"explanation":"aurai + participle.","tag":"futur-anterieur","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["le","commencerons","fois","vous","nous","aurez","contrat","Une","que","signé"],"answer":"Une fois que vous aurez signé le contrat nous commencerons","accepted":[],"explanation":"une fois que + futur antérieur + futur.","tag":"futur-anterieur","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"As soon as I have finished, I will call you.\"","options":[],"answer":"Dès que j''aurai fini, je t''appellerai.","accepted":["Dès que j''aurai terminé, je t''appellerai.","Dès que j''aurai fini, je vous appellerai."],"explanation":"dès que + futur antérieur.","tag":"futur-anterieur","id":"ex5"}],"writing_prompt":"Où en serez-vous dans cinq ans ? Décrivez ce que vous aurez accompli.","writing_model":"Dans cinq ans, j''aurai obtenu mon master et j''aurai passé le DALF C1. J''aurai sûrement déménagé à Montréal et j''aurai trouvé un poste d''ingénieur. Dès que je me serai installé, je ferai venir ma famille. Une fois que nous aurons acheté une maison, je commencerai à apprendre l''espagnol !","writing_checklist":["futur antérieur (aurai + participe, serai + participe)","dès que / une fois que / quand","futur simple pour l''action suivante"],"email_snippet":{"word_of_day":{"fr":"d''ici (à) 2030","en":"by 2030","example":"D''ici 2030, la ville aura doublé."},"mini_question":{"prompt":"Quand tu arriveras, nous ___ déjà mangé.","options":["aurons","avions","avons","aurions"],"answer":"aurons"}}}'::jsonb, 'approved', 'curriculum'),
  ('B2', 11, 'Mettre en relief', '{"level":"B2","seq":11,"theme":"Mettre en relief","vocabulary":[{"fr":"souligner","en":"to emphasise","example":"Je tiens à souligner ce point."},{"fr":"l''essentiel (m.)","en":"the main thing","example":"L''essentiel, c''est de participer."},{"fr":"en réalité","en":"in reality","example":"En réalité, il n''a rien dit."},{"fr":"justement","en":"precisely / exactly","example":"C''est justement ce que je voulais dire."},{"fr":"surtout","en":"above all","example":"Ce qui compte surtout, c''est la santé."},{"fr":"insister sur","en":"to insist on","example":"Elle insiste sur l''importance du travail."},{"fr":"le malentendu","en":"the misunderstanding","example":"Il y a eu un malentendu."},{"fr":"préciser","en":"to specify / clarify","example":"Je voudrais préciser une chose."}],"grammar":{"topic":"La mise en relief","explanation":"To highlight an element:\n• C''est… qui (subject): « C''est Marie qui a gagné. »\n• C''est… que (other elements): « C''est à Paris que je l''ai rencontré. »\n• Ce qui… c''est (subject): « Ce qui me plaît, c''est la musique. »\n• Ce que… c''est (object): « Ce que je veux, c''est partir. »\n• Ce dont… c''est (with de): « Ce dont j''ai besoin, c''est de repos. »\nUse ce sont for plural nouns in careful French: « Ce sont mes amis qui l''ont fait. »","examples":["C''est lui qui a raison.","C''est demain que nous partons.","Ce qui m''inquiète, c''est le prix.","Ce dont il rêve, c''est d''un long voyage."]},"text":{"title":"Ce qui compte vraiment","body":"On demande souvent à la cheffe Fatou Ndiaye le secret de son succès. « Ce qui compte, ce n''est pas le prix des produits, c''est leur fraîcheur », répond-elle. « C''est ma grand-mère qui m''a appris à cuisiner, et c''est au marché de Dakar que j''ai découvert les épices. Ce dont un cuisinier a besoin, c''est de curiosité. Et ce que je déteste, c''est le gaspillage. »","questions":[{"id":"tq1","question":"Selon Fatou, qu''est-ce qui compte le plus ?","options":["le prix des produits","la rapidité","la décoration","la fraîcheur des produits"],"answer":"la fraîcheur des produits","explanation":""},{"id":"tq2","question":"Qui lui a appris à cuisiner ?","options":["sa mère","sa grand-mère","un chef français","son mari"],"answer":"sa grand-mère","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"___ me dérange, c''est le bruit.","options":["Qui","Ce qui","Ce que","Ce dont"],"answer":"Ce qui","accepted":[],"explanation":"Subject of « dérange » → ce qui.","tag":"mise-en-relief","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"___ j''ai besoin, c''est de dormir.","options":["Ce qui","Ce dont","Dont","Ce que"],"answer":"Ce dont","accepted":[],"explanation":"avoir besoin de → ce dont.","tag":"mise-en-relief","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"C''est à Lagos ___ je suis né.","options":[],"answer":"que","accepted":[],"explanation":"C''est + place + que.","tag":"mise-en-relief","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["frère","repas","mon","préparé","qui","le","C''est","a"],"answer":"C''est mon frère qui a préparé le repas","accepted":[],"explanation":"C''est + subject + qui.","tag":"mise-en-relief","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"What I want is to travel.\"","options":[],"answer":"Ce que je veux, c''est voyager.","accepted":["Ce que je veux c''est voyager."],"explanation":"Object → ce que… c''est.","tag":"mise-en-relief","id":"ex5"}],"writing_prompt":"Qu''est-ce qui est vraiment important pour vous dans la vie ? Utilisez au moins quatre structures de mise en relief.","writing_model":"Ce qui compte le plus pour moi, c''est ma famille. C''est elle qui m''a soutenu quand j''ai perdu mon emploi. Ce que j''apprécie aussi, c''est le temps libre : c''est le week-end que je recharge mes batteries. Enfin, ce dont j''ai vraiment besoin, c''est d''apprendre sans cesse de nouvelles choses.","writing_checklist":["c''est… qui / c''est… que","ce qui / ce que / ce dont… c''est","virgule avant c''est"],"email_snippet":{"word_of_day":{"fr":"souligner","en":"to emphasise","example":"Je tiens à souligner ce point."},"mini_question":{"prompt":"___ me dérange, c''est le bruit.","options":["Qui","Ce qui","Ce que","Ce dont"],"answer":"Ce qui"}}}'::jsonb, 'approved', 'curriculum'),
  ('B2', 12, 'L''e-mail professionnel', '{"level":"B2","seq":12,"theme":"L''e-mail professionnel","vocabulary":[{"fr":"Objet :","en":"Subject:","example":"Objet : demande de rendez-vous"},{"fr":"Madame, Monsieur,","en":"Dear Sir or Madam,","example":"Madame, Monsieur, je vous écris…"},{"fr":"ci-joint","en":"attached","example":"Veuillez trouver ci-joint mon CV."},{"fr":"dans l''attente de","en":"looking forward to","example":"Dans l''attente de votre réponse…"},{"fr":"un rendez-vous","en":"an appointment","example":"Je souhaiterais prendre rendez-vous."},{"fr":"disponible","en":"available","example":"Je suis disponible mardi."},{"fr":"Cordialement","en":"Kind regards","example":"Cordialement, Ben Shaibu"},{"fr":"relancer","en":"to follow up","example":"Je me permets de vous relancer."}],"grammar":{"topic":"Les formules de l''écrit professionnel","explanation":"Opening: Madame, Monsieur, (unknown) / Madame Dupont, (known). Never « Cher Monsieur » in a first formal contact.\nReason: Je vous écris au sujet de… / Je me permets de vous contacter afin de… / Suite à notre conversation…\nRequest: Je souhaiterais… / Pourriez-vous… / Je vous serais reconnaissant(e) de…\nAttachment: Veuillez trouver ci-joint…\nClosing: Dans l''attente de votre réponse, je vous prie d''agréer, Madame, Monsieur, l''expression de mes salutations distinguées. In an e-mail, « Cordialement » or « Bien cordialement » is enough.","examples":["Je me permets de vous relancer concernant ma candidature.","Veuillez trouver ci-joint le devis demandé.","Pourriez-vous me confirmer votre disponibilité ?","Je reste à votre disposition pour tout renseignement."]},"text":{"title":"Demande de rendez-vous","body":"Objet : Demande de rendez-vous – partenariat\nMadame Leroy,\nSuite à notre échange lors du salon de Dakar, je me permets de vous contacter afin de vous présenter notre projet de plateforme éducative. Je souhaiterais vous rencontrer pour en discuter plus en détail. Je serai à Paris du 10 au 14 juin et je suis disponible à la date qui vous conviendra. Veuillez trouver ci-joint une présentation de notre entreprise.\nDans l''attente de votre réponse, je vous prie d''agréer, Madame, mes salutations distinguées.\nBenjamin Shaibu","questions":[{"id":"tq1","question":"Où l''auteur a-t-il rencontré Mme Leroy ?","options":["en ligne","au salon de Dakar","dans son entreprise","à Paris"],"answer":"au salon de Dakar","explanation":""},{"id":"tq2","question":"Que joint-il à son e-mail ?","options":["son CV","une présentation de son entreprise","un devis","un contrat"],"answer":"une présentation de son entreprise","explanation":""}]},"exercises":[{"type":"mcq","skill":"vocabulary","prompt":"Formule correcte pour joindre un document :","options":["Voilà mon CV attaché.","Je vous attache mon CV.","Regardez mon CV joint.","Veuillez trouver ci-joint mon CV."],"answer":"Veuillez trouver ci-joint mon CV.","accepted":[],"explanation":"Standard: Veuillez trouver ci-joint…","tag":"formal-email","id":"ex1"},{"type":"mcq","skill":"vocabulary","prompt":"Pour une première prise de contact formelle :","options":["Madame, Monsieur,","Salut,","Coucou,","Cher ami,"],"answer":"Madame, Monsieur,","accepted":[],"explanation":"Unknown recipient → Madame, Monsieur,","tag":"formal-email","id":"ex2"},{"type":"fill_blank","skill":"vocabulary","prompt":"Je me ___ de vous relancer concernant ma demande.","options":[],"answer":"permets","accepted":[],"explanation":"Je me permets de… (polite formula).","tag":"formal-email","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["à","tout","renseignement","Je","pour","disposition","reste","votre"],"answer":"Je reste à votre disposition pour tout renseignement","accepted":[],"explanation":"Closing formula.","tag":"formal-email","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"Could you confirm the date of the meeting?\"","options":[],"answer":"Pourriez-vous me confirmer la date de la réunion ?","accepted":["Pourriez-vous confirmer la date de la réunion ?"],"explanation":"Polite request with the conditionnel.","tag":"formal-email","id":"ex5"}],"writing_prompt":"Écrivez un e-mail professionnel pour demander un stage dans une entreprise française (120 mots).","writing_model":"Objet : Candidature pour un stage en marketing\nMadame, Monsieur,\nÉtudiant en master de commerce à l''université de Lagos, je me permets de vous contacter afin de solliciter un stage de six mois au sein de votre service marketing, à partir de septembre. Votre entreprise m''intéresse particulièrement pour son développement en Afrique de l''Ouest. Je parle anglais, français et yoruba. Veuillez trouver ci-joint mon CV. Je serais ravi de vous présenter ma motivation lors d''un entretien.\nDans l''attente de votre réponse, je vous prie d''agréer, Madame, Monsieur, mes salutations distinguées.","writing_checklist":["objet clair","formule d''appel et formule finale adaptées","je me permets de / je souhaiterais / veuillez trouver ci-joint"],"email_snippet":{"word_of_day":{"fr":"Objet :","en":"Subject:","example":"Objet : demande de rendez-vous"},"mini_question":{"prompt":"Formule correcte pour joindre un document :","options":["Voilà mon CV attaché.","Je vous attache mon CV.","Regardez mon CV joint.","Veuillez trouver ci-joint mon CV."],"answer":"Veuillez trouver ci-joint mon CV."}}}'::jsonb, 'approved', 'curriculum'),
  ('C1', 1, 'Le subjonctif passé', '{"level":"C1","seq":1,"theme":"Le subjonctif passé","vocabulary":[{"fr":"douter que","en":"to doubt that","example":"Je doute qu''il ait compris."},{"fr":"il est dommage que","en":"it''s a pity that","example":"Il est dommage que tu sois parti si tôt."},{"fr":"avant que… ne","en":"before","example":"Partons avant qu''il ne soit trop tard."},{"fr":"s''étonner que","en":"to be surprised that","example":"Je m''étonne qu''elle n''ait rien dit."},{"fr":"déplorer","en":"to deplore","example":"Nous déplorons que la réunion ait été annulée."},{"fr":"il se peut que","en":"it may be that","example":"Il se peut qu''il se soit trompé."},{"fr":"le premier / le seul… qui","en":"the first / the only… who","example":"C''est le seul qui ait répondu."},{"fr":"à supposer que","en":"assuming that","example":"À supposer qu''il ait raison…"}],"grammar":{"topic":"Le subjonctif passé","explanation":"Formation : auxiliaire avoir ou être au subjonctif présent + participe passé : que j''aie fini, qu''elle soit partie.\nIl exprime une action antérieure à celle du verbe principal, dans les contextes qui exigent le subjonctif : « Je suis content que tu aies réussi » (la réussite précède la joie).\nOn l''emploie aussi après un superlatif ou le seul / le premier / l''unique pour exprimer une appréciation subjective : « C''est le meilleur film que j''aie vu. »","examples":["Je doute qu''il ait reçu mon message.","Bien qu''elle soit arrivée en retard, elle a tout compris.","C''est la plus belle ville que nous ayons visitée.","Il est regrettable qu''aucune décision n''ait été prise."]},"text":{"title":"Bilan d''un projet","body":"Le comité regrette que le projet de bibliothèque numérique n''ait pas été achevé dans les délais. Il est vrai que les financements sont arrivés tardivement, mais il est étonnant que personne n''ait alerté la direction plus tôt. Bien que l''équipe ait fourni un travail considérable, il se peut que certains choix techniques aient été mal évalués. C''est pourtant le projet le plus ambitieux que l''université ait jamais lancé, et le comité souhaite qu''il soit relancé dès l''an prochain.","questions":[{"id":"tq1","question":"Qu''est-ce que le comité trouve étonnant ?","options":["que personne n''ait alerté la direction plus tôt","que le projet soit ambitieux","que le projet ait été financé","que l''équipe ait travaillé dur"],"answer":"que personne n''ait alerté la direction plus tôt","explanation":""},{"id":"tq2","question":"Que souhaite le comité ?","options":["que le projet soit relancé l''an prochain","que le projet soit abandonné","que l''équipe soit remplacée","que les financements soient remboursés"],"answer":"que le projet soit relancé l''an prochain","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"Je suis heureux que vous ___ venir hier.","options":["pouviez","ayez pu","avez pu","puissiez"],"answer":"ayez pu","accepted":[],"explanation":"Action passée par rapport à la joie → subjonctif passé.","tag":"subjonctif-passe","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"C''est le meilleur livre que j''___ lu.","options":["aurais","aie","avais","ai"],"answer":"aie","accepted":[],"explanation":"Superlatif + que → subjonctif (passé ici).","tag":"subjonctif-passe","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"Bien qu''elle ___ partie tôt, elle a raté le train. (être)","options":[],"answer":"soit","accepted":[],"explanation":"Partir → être ; bien que + subjonctif passé.","tag":"subjonctif-passe","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["question","qu''il","compris","doute","ait","la","Je"],"answer":"Je doute qu''il ait compris la question","accepted":[],"explanation":"douter que + subjonctif passé.","tag":"subjonctif-passe","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"It''s a pity that you didn''t see the exhibition.\"","options":[],"answer":"Il est dommage que tu n''aies pas vu l''exposition.","accepted":["C''est dommage que tu n''aies pas vu l''exposition.","Il est dommage que vous n''ayez pas vu l''exposition."],"explanation":"il est dommage que + subjonctif passé.","tag":"subjonctif-passe","id":"ex5"}],"writing_prompt":"Rédigez un bref bilan (120 mots) d''une expérience passée (projet, voyage, formation) en exprimant regrets et satisfactions au subjonctif passé.","writing_model":"Je suis ravi que notre équipe ait terminé le site internet à temps, même si je regrette que nous n''ayons pas pu tester toutes les fonctionnalités. Il est dommage que le client ait changé d''avis si tard, mais je suis fier que chacun soit resté motivé. C''est sans doute le projet le plus formateur que j''aie mené cette année. À l''avenir, il faudra que nous prévoyions davantage de temps pour les imprévus.","writing_checklist":["subjonctif passé (aie / sois + participe)","verbes de sentiment, doute ou superlatif","nuance entre regrets et satisfactions"],"email_snippet":{"word_of_day":{"fr":"douter que","en":"to doubt that","example":"Je doute qu''il ait compris."},"mini_question":{"prompt":"Je suis heureux que vous ___ venir hier.","options":["pouviez","ayez pu","avez pu","puissiez"],"answer":"ayez pu"}}}'::jsonb, 'approved', 'curriculum'),
  ('C1', 2, 'Nuancer une concession', '{"level":"C1","seq":2,"theme":"Nuancer une concession","vocabulary":[{"fr":"quoique","en":"although","example":"Quoiqu''il soit jeune, il est très compétent."},{"fr":"quel que soit","en":"whatever","example":"Quel que soit le prix, je l''achète."},{"fr":"quoi que","en":"whatever (pronoun)","example":"Quoi que tu dises, je ne changerai pas d''avis."},{"fr":"si… que","en":"however… (+ adj.)","example":"Si difficile que ce soit, nous y arriverons."},{"fr":"avoir beau","en":"however much / no matter how","example":"J''ai beau chercher, je ne trouve pas."},{"fr":"toujours est-il que","en":"the fact remains that","example":"Toujours est-il qu''il est en retard."},{"fr":"il n''en reste pas moins que","en":"nonetheless","example":"Il n''en reste pas moins que c''est une erreur."},{"fr":"quand bien même","en":"even if","example":"Quand bien même il viendrait, rien ne changerait."}],"grammar":{"topic":"Les nuances de la concession","explanation":"• quoique / bien que + subjonctif.\n• quel(le)(s) que + être au subjonctif, accordé avec le sujet : quelle que soit la difficulté, quels que soient les risques.\n• quoi que (en deux mots) = quelle que soit la chose que : quoi qu''il arrive.\n• si / aussi / pour + adjectif + que + subjonctif : si intelligent qu''il soit.\n• avoir beau + infinitif : j''ai beau insister, il refuse.\n• quand bien même + conditionnel.\n• Après la concession : toujours est-il que, il n''en reste pas moins que, il n''empêche que.","examples":["Quelles que soient vos raisons, c''est inacceptable.","Quoi que vous fassiez, faites-le bien.","Elle a beau travailler, elle n''est jamais satisfaite.","Si compétent qu''il soit, il a besoin d''aide."]},"text":{"title":"L''éloge de l''échec","body":"Nous avons beau répéter aux jeunes que l''échec fait partie de l''apprentissage, la peur de se tromper reste paralysante. Quelles que soient leurs qualités, beaucoup d''étudiants renoncent à des projets ambitieux par crainte du jugement. Certes, un échec coûte du temps et parfois de l''argent. Il n''en reste pas moins qu''il apprend davantage qu''une réussite facile. Quoi qu''en disent les classements et les notes, la persévérance est sans doute la compétence la plus précieuse.","questions":[{"id":"tq1","question":"Selon l''auteur, pourquoi des étudiants renoncent-ils à leurs projets ?","options":["par manque de temps","par manque d''argent","parce qu''ils sont paresseux","par peur du jugement"],"answer":"par peur du jugement","explanation":""},{"id":"tq2","question":"Quelle est, selon l''auteur, la compétence la plus précieuse ?","options":["la prudence","la réussite scolaire","la persévérance","l''intelligence"],"answer":"la persévérance","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"___ soient les difficultés, nous continuerons.","options":["Quelque","Quoique","Quelles que","Quels que"],"answer":"Quelles que","accepted":[],"explanation":"difficultés (f. pl.) → quelles que soient.","tag":"concession","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"___ tu fasses, il ne sera pas content.","options":["Quel que","Quoique","Quoi que","Bien que"],"answer":"Quoi que","accepted":[],"explanation":"quoi que (deux mots) = whatever.","tag":"concession","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"J''ai ___ lui expliquer, il ne comprend pas.","options":[],"answer":"beau","accepted":[],"explanation":"avoir beau + infinitif.","tag":"avoir-beau","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["fatigué","il","son","finira","travail","Si","soit","qu''il"],"answer":"Si fatigué qu''il soit il finira son travail","accepted":[],"explanation":"si + adjectif + que + subjonctif.","tag":"concession","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"Whatever the price, we will buy this house.\"","options":[],"answer":"Quel que soit le prix, nous achèterons cette maison.","accepted":["Quel que soit son prix, nous achèterons cette maison."],"explanation":"prix (m. sg.) → quel que soit.","tag":"concession","id":"ex5"}],"writing_prompt":"« Il faut toujours suivre ses rêves. » Nuancez cette affirmation en un paragraphe de 150 mots, avec au moins trois structures concessives.","writing_model":"Suivre ses rêves est sans doute une belle ambition. On a beau être réaliste, une vie sans projet personnel paraît vite terne. Toutefois, quelles que soient nos aspirations, il faut tenir compte de nos responsabilités : une famille à nourrir, des dettes à rembourser. Si légitime que soit le désir de tout quitter pour vivre de sa passion, il n''en reste pas moins qu''un plan solide est indispensable. Quoi qu''en disent les discours de motivation, le courage ne remplace pas la préparation. Il me semble donc plus sage de poursuivre ses rêves progressivement, en sécurisant chaque étape.","writing_checklist":["au moins trois structures concessives variées","accord de quel que","progression logique de l''argument"],"email_snippet":{"word_of_day":{"fr":"quoique","en":"although","example":"Quoiqu''il soit jeune, il est très compétent."},"mini_question":{"prompt":"___ soient les difficultés, nous continuerons.","options":["Quelque","Quoique","Quelles que","Quels que"],"answer":"Quelles que"}}}'::jsonb, 'approved', 'curriculum'),
  ('C1', 3, 'Expressions imagées', '{"level":"C1","seq":3,"theme":"Expressions imagées","vocabulary":[{"fr":"poser un lapin","en":"to stand someone up","example":"Il m''a posé un lapin hier soir."},{"fr":"avoir un chat dans la gorge","en":"to have a frog in one''s throat","example":"Excusez-moi, j''ai un chat dans la gorge."},{"fr":"être têtu comme une mule","en":"to be as stubborn as a mule","example":"Mon frère est têtu comme une mule."},{"fr":"donner sa langue au chat","en":"to give up guessing","example":"Je donne ma langue au chat : c''est quoi ?"},{"fr":"tomber dans les pommes","en":"to faint","example":"Avec la chaleur, elle est tombée dans les pommes."},{"fr":"coûter les yeux de la tête","en":"to cost an arm and a leg","example":"Cette voiture coûte les yeux de la tête."},{"fr":"mettre la main à la pâte","en":"to pitch in","example":"Tout le monde a mis la main à la pâte."},{"fr":"avoir la puce à l''oreille","en":"to become suspicious","example":"Son silence m''a mis la puce à l''oreille."}],"grammar":{"topic":"Les expressions idiomatiques","explanation":"Les expressions idiomatiques ne se traduisent pas mot à mot. Elles marquent souvent un registre courant ou familier et donnent du naturel au discours.\nQuelques familles utiles :\n• animaux : poser un lapin, quand les poules auront des dents (jamais), il fait un froid de canard ;\n• corps : coûter les yeux de la tête, avoir le bras long (avoir de l''influence), casser les pieds (ennuyer) ;\n• nourriture : raconter des salades (mentir), ce n''est pas de la tarte (c''est difficile).\nÀ l''écrit soutenu, on les évite ou on les met entre guillemets.","examples":["Il raconte des salades : ne le crois pas.","Ce projet, ce n''est pas de la tarte !","Elle a le bras long dans ce ministère.","Arrête de me casser les pieds !"]},"text":{"title":"Une soirée ratée","body":"Samedi, Julien avait réservé une table dans un restaurant qui coûte les yeux de la tête. Il attendait Inès, mais elle lui a posé un lapin. Au bout d''une heure, il a commencé à avoir la puce à l''oreille : elle ne répondait plus à ses messages. Le lendemain, elle lui a raconté qu''elle était tombée dans les pommes à cause de la chaleur. Julien pense qu''elle raconte des salades, mais il est têtu comme une mule : il compte bien l''inviter à nouveau.","questions":[{"id":"tq1","question":"Que s''est-il passé samedi ?","options":["Inès n''est pas venue au rendez-vous.","Julien est tombé malade.","Le restaurant était fermé.","Ils se sont disputés."],"answer":"Inès n''est pas venue au rendez-vous.","explanation":""},{"id":"tq2","question":"Que pense Julien de l''explication d''Inès ?","options":["Il pense qu''elle ment.","Il la croit totalement.","Il ne veut plus la voir.","Il est inquiet pour sa santé."],"answer":"Il pense qu''elle ment.","explanation":""}]},"exercises":[{"type":"mcq","skill":"vocabulary","prompt":"« Il m''a posé un lapin » signifie :","options":["Il n''est pas venu au rendez-vous.","Il m''a fait une blague.","Il m''a offert un animal.","Il m''a invité à dîner."],"answer":"Il n''est pas venu au rendez-vous.","accepted":[],"explanation":"poser un lapin = ne pas venir.","tag":"idioms","id":"ex1"},{"type":"mcq","skill":"vocabulary","prompt":"« Ce n''est pas de la tarte » signifie :","options":["C''est difficile.","C''est délicieux.","C''est bon marché.","C''est une erreur."],"answer":"C''est difficile.","accepted":[],"explanation":"Expression familière : c''est difficile.","tag":"idioms","id":"ex2"},{"type":"fill_blank","skill":"vocabulary","prompt":"Ce sac coûte les yeux de la ___.","options":[],"answer":"tête","accepted":[],"explanation":"coûter les yeux de la tête = très cher.","tag":"idioms","id":"ex3"},{"type":"reorder","skill":"vocabulary","prompt":"Put the words in the right order.","options":["le","monde","pâte","a","la","mis","la","à","Tout","main"],"answer":"Tout le monde a mis la main à la pâte","accepted":[],"explanation":"Expression : participer au travail.","tag":"idioms","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"I give up, tell me the answer!\"","options":[],"answer":"Je donne ma langue au chat, dis-moi la réponse !","accepted":["Je donne ma langue au chat, donne-moi la réponse !"],"explanation":"give up guessing → donner sa langue au chat.","tag":"idioms","id":"ex5"}],"writing_prompt":"Racontez une anecdote drôle ou embarrassante en utilisant au moins quatre expressions idiomatiques.","writing_model":"La semaine dernière, mon collègue devait présenter un rapport important, mais il avait un chat dans la gorge et ne pouvait presque pas parler. Notre chef, têtu comme une mule, a refusé de reporter la réunion. Finalement, toute l''équipe a mis la main à la pâte et j''ai lu le rapport à sa place. Ce n''était pas de la tarte, mais le client a été convaincu !","writing_checklist":["au moins quatre expressions idiomatiques bien employées","récit cohérent au passé","registre courant"],"email_snippet":{"word_of_day":{"fr":"poser un lapin","en":"to stand someone up","example":"Il m''a posé un lapin hier soir."},"mini_question":{"prompt":"« Il m''a posé un lapin » signifie :","options":["Il n''est pas venu au rendez-vous.","Il m''a fait une blague.","Il m''a offert un animal.","Il m''a invité à dîner."],"answer":"Il n''est pas venu au rendez-vous."}}}'::jsonb, 'approved', 'curriculum'),
  ('C1', 4, 'Les registres de langue', '{"level":"C1","seq":4,"theme":"Les registres de langue","vocabulary":[{"fr":"une bagnole (fam.)","en":"a car (slang)","example":"Il a une nouvelle bagnole."},{"fr":"le boulot (fam.)","en":"work / job (slang)","example":"Je vais au boulot."},{"fr":"bosser (fam.)","en":"to work (slang)","example":"Il bosse dur."},{"fr":"se casser (fam.)","en":"to leave / clear off (slang)","example":"On se casse ?"},{"fr":"fric (fam.)","en":"money (slang)","example":"Il n''a pas de fric."},{"fr":"demeurer (sout.)","en":"to reside / remain (formal)","example":"Il demeure à Lyon."},{"fr":"se rendre (sout.)","en":"to go (formal)","example":"Je me rendrai à la réunion."},{"fr":"solliciter (sout.)","en":"to request (formal)","example":"Je sollicite un entretien."}],"grammar":{"topic":"Familier, courant, soutenu","explanation":"Le français distingue trois grands registres :\n• familier : vocabulaire argotique (boulot, bouquin, flic), négation sans ne (« je sais pas »), on pour nous, questions par intonation ;\n• courant : langue standard (travail, livre, policier) ;\n• soutenu : vocabulaire recherché (labeur, ouvrage), inversion du sujet (« Puis-je… ? »), subjonctif imparfait possible à l''écrit littéraire.\nSavoir passer d''un registre à l''autre selon l''interlocuteur est une compétence clé du niveau C1.","examples":["Familier : T''as vu ma bagnole ?","Courant : Tu as vu ma voiture ?","Soutenu : Avez-vous aperçu mon véhicule ?","Familier : J''ai pas le temps. / Courant : Je n''ai pas le temps."]},"text":{"title":"Trois façons de dire la même chose","body":"Kader raconte sa journée à un ami : « J''en ai marre de mon boulot, mon chef me prend la tête et je suis crevé. » Le soir, il explique à sa mère : « Je suis fatigué ; mon travail est difficile et mon responsable est très exigeant. » Enfin, dans sa lettre de démission, il écrit : « Je vous informe de ma décision de quitter mes fonctions, les conditions actuelles ne me permettant plus de m''épanouir. » Le message est le même ; seul le registre change.","questions":[{"id":"tq1","question":"Dans quel registre Kader parle-t-il à son ami ?","options":["administratif","courant","familier","soutenu"],"answer":"familier","explanation":""},{"id":"tq2","question":"Que signifie « mon chef me prend la tête » ?","options":["mon chef m''agace","mon chef me licencie","mon chef me félicite","mon chef me paie bien"],"answer":"mon chef m''agace","explanation":""}]},"exercises":[{"type":"mcq","skill":"vocabulary","prompt":"Équivalent courant de « bouquin » :","options":["journal","livre","cahier","ouvrage"],"answer":"livre","accepted":[],"explanation":"bouquin (fam.) → livre (courant) → ouvrage (soutenu).","tag":"registers","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"Quelle phrase est au registre soutenu ?","options":["J''peux t''aider ?","Puis-je vous aider ?","Je peux t''aider ?","Tu veux un coup de main ?"],"answer":"Puis-je vous aider ?","accepted":[],"explanation":"Inversion + vous → soutenu.","tag":"registers","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"Familier : « J''ai pas faim. » → Courant : « Je ___ pas faim. »","options":[],"answer":"n''ai","accepted":[],"explanation":"La négation complète ne… pas.","tag":"registers","id":"ex3"},{"type":"reorder","skill":"vocabulary","prompt":"Put the words in the right order.","options":["la","me","rendrai","Je","à","matin","réunion","demain"],"answer":"Je me rendrai à la réunion demain matin","accepted":[],"explanation":"se rendre = aller (soutenu).","tag":"registers","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"I''m fed up with my job. (informal)\"","options":[],"answer":"J''en ai marre de mon boulot.","accepted":["J''en ai marre de mon travail.","J''en ai ras le bol de mon boulot."],"explanation":"Registre familier : en avoir marre, boulot.","tag":"registers","id":"ex5"}],"writing_prompt":"Racontez le même petit incident (un retard, une panne…) dans les trois registres : à un ami (SMS), à un collègue, puis dans un courriel formel.","writing_model":"SMS : « Désolé, j''suis à la bourre, ma bagnole est en rade ! »\nCollègue : « Je suis désolé, je vais être en retard : ma voiture est tombée en panne. »\nCourriel formel : « Je vous prie de bien vouloir excuser mon retard, imputable à une panne de mon véhicule. Je serai présent dans les meilleurs délais. »","writing_checklist":["vocabulaire adapté à chaque registre","négation et questions selon le registre","même information transmise trois fois"],"email_snippet":{"word_of_day":{"fr":"une bagnole (fam.)","en":"a car (slang)","example":"Il a une nouvelle bagnole."},"mini_question":{"prompt":"Équivalent courant de « bouquin » :","options":["journal","livre","cahier","ouvrage"],"answer":"livre"}}}'::jsonb, 'approved', 'curriculum'),
  ('C1', 5, 'La nominalisation', '{"level":"C1","seq":5,"theme":"La nominalisation","vocabulary":[{"fr":"la hausse","en":"the rise","example":"La hausse des prix inquiète."},{"fr":"la baisse","en":"the fall","example":"On constate une baisse du chômage."},{"fr":"la mise en place","en":"the implementation","example":"La mise en place de la réforme prendra du temps."},{"fr":"le report","en":"the postponement","example":"Le report du vote est confirmé."},{"fr":"la prise de conscience","en":"the awareness","example":"Il y a une prise de conscience écologique."},{"fr":"l''ouverture (f.)","en":"the opening","example":"L''ouverture du magasin est prévue lundi."},{"fr":"la suppression","en":"the removal / abolition","example":"La suppression de la taxe est annoncée."},{"fr":"l''adoption (f.)","en":"the adoption","example":"L''adoption de la loi a été rapide."}],"grammar":{"topic":"La nominalisation","explanation":"Nominaliser, c''est transformer un verbe ou un adjectif en nom pour condenser l''information. C''est typique des titres de presse, des rapports et de l''écrit académique.\n• Suffixes fréquents : -tion (adopter → l''adoption), -ment (lancer → le lancement), -age (nettoyer → le nettoyage), -ure (ouvrir → l''ouverture), -ée (arriver → l''arrivée), -té / -esse (rapide → la rapidité, faible → la faiblesse).\n• « Les prix augmentent fortement » → « Forte augmentation des prix ».\n• Attention : certains noms sont irréguliers (choisir → le choix, perdre → la perte).","examples":["Le gouvernement a annoncé qu''il réformait les retraites → Annonce d''une réforme des retraites.","Le magasin ouvre lundi → Ouverture du magasin lundi.","Les étudiants sont inquiets → L''inquiétude des étudiants.","On a reporté le match → Report du match."]},"text":{"title":"Revue de presse","body":"Hausse record du prix du carburant. Après l''annonce de la suppression des subventions, les transporteurs dénoncent une décision brutale. Le gouvernement promet la mise en place rapide d''aides ciblées et l''ouverture de négociations avec les syndicats. De leur côté, les économistes saluent une prise de conscience nécessaire, tout en redoutant une baisse de la consommation. Report probable de la grève prévue lundi.","questions":[{"id":"tq1","question":"Quelle décision a provoqué la colère des transporteurs ?","options":["l''ouverture des négociations","la hausse des salaires","le report de la grève","la suppression des subventions"],"answer":"la suppression des subventions","explanation":""},{"id":"tq2","question":"Que redoutent les économistes ?","options":["une grève générale","la fin des négociations","une hausse du chômage","une baisse de la consommation"],"answer":"une baisse de la consommation","explanation":""}]},"exercises":[{"type":"mcq","skill":"vocabulary","prompt":"Nom correspondant à « choisir » :","options":["le choisir","le choisissement","la choisie","le choix"],"answer":"le choix","accepted":[],"explanation":"Nominalisation irrégulière.","tag":"nominalisation","id":"ex1"},{"type":"mcq","skill":"vocabulary","prompt":"« Le train arrive à 10 h » → titre :","options":["Arrivée du train à 10 h","Arrivement du train à 10 h","Arrivage du train à 10 h","Arriver du train à 10 h"],"answer":"Arrivée du train à 10 h","accepted":[],"explanation":"arriver → l''arrivée.","tag":"nominalisation","id":"ex2"},{"type":"fill_blank","skill":"vocabulary","prompt":"« On a lancé le produit hier » → Le ___ du produit a eu lieu hier.","options":[],"answer":"lancement","accepted":[],"explanation":"lancer → le lancement.","tag":"nominalisation","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["augmentation","des","Forte","l''immobilier","de","prix"],"answer":"Forte augmentation des prix de l''immobilier","accepted":[],"explanation":"Titre de presse nominal.","tag":"nominalisation","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"Opening of the new bridge postponed.\"","options":[],"answer":"Report de l''ouverture du nouveau pont.","accepted":["Ouverture du nouveau pont reportée."],"explanation":"Style nominal des titres.","tag":"nominalisation","id":"ex5"}],"writing_prompt":"Transformez cinq informations d''actualité de votre pays en titres de presse nominaux, puis rédigez un court chapeau (3 phrases) pour l''un d''eux.","writing_model":"1. Baisse du prix du riz sur les marchés de Lagos.\n2. Ouverture d''un nouveau terminal à l''aéroport d''Abuja.\n3. Report des examens nationaux à juillet.\n4. Hausse des inscriptions dans les écoles de langues.\n5. Lancement d''une campagne de vaccination.\nChapeau (3) : Le ministère de l''Éducation a confirmé hier le report des examens nationaux. Cette décision fait suite aux inondations qui ont touché plusieurs régions. Les élèves disposeront ainsi de trois semaines supplémentaires de préparation.","writing_checklist":["noms dérivés corrects (-tion, -ment, -ée, -ure…)","absence de verbe conjugué dans les titres","chapeau informatif et concis"],"email_snippet":{"word_of_day":{"fr":"la hausse","en":"the rise","example":"La hausse des prix inquiète."},"mini_question":{"prompt":"Nom correspondant à « choisir » :","options":["le choisir","le choisissement","la choisie","le choix"],"answer":"le choix"}}}'::jsonb, 'approved', 'curriculum'),
  ('C1', 6, 'L''hypothèse avancée', '{"level":"C1","seq":6,"theme":"L''hypothèse avancée","vocabulary":[{"fr":"au cas où","en":"in case","example":"Prends un parapluie au cas où il pleuvrait."},{"fr":"à condition que","en":"provided that","example":"Je viendrai à condition que tu m''invites."},{"fr":"pour peu que","en":"if only / as long as","example":"Pour peu qu''il fasse beau, la fête sera réussie."},{"fr":"en admettant que","en":"assuming that","example":"En admettant que tu aies raison…"},{"fr":"à moins de","en":"unless","example":"À moins d''un miracle, nous perdrons."},{"fr":"sinon","en":"otherwise","example":"Dépêche-toi, sinon tu vas rater le bus."},{"fr":"dans l''hypothèse où","en":"in the event that","example":"Dans l''hypothèse où le contrat serait signé…"},{"fr":"faute de","en":"for lack of","example":"Faute de temps, je n''ai pas fini."}],"grammar":{"topic":"Exprimer la condition et l''hypothèse","explanation":"Au-delà de si :\n• + conditionnel : au cas où, dans l''hypothèse où, quand bien même.\n• + subjonctif : à condition que, pourvu que, pour peu que, en admettant que, à supposer que, à moins que.\n• + infinitif (même sujet) : à condition de, à moins de.\n• + nom : en cas de, à moins de, faute de, sans (« Sans ton aide, j''aurais échoué »).\n• Gérondif : En partant maintenant, tu arriveras à l''heure.","examples":["Au cas où tu aurais besoin de moi, appelle-moi.","Je t''aiderai à condition que tu sois honnête.","En cas de problème, contactez l''accueil.","Sans carte, impossible d''entrer."]},"text":{"title":"Plan de continuité","body":"Au cas où une coupure d''électricité surviendrait, les données seraient automatiquement sauvegardées sur un serveur distant. En cas de panne prolongée, le personnel pourra travailler depuis l''agence de Port-Harcourt, à condition que la connexion internet y soit disponible. Pour peu que chacun respecte ces consignes, l''activité ne sera pas interrompue. Faute de préparation, en revanche, une simple panne pourrait coûter plusieurs jours de travail.","questions":[{"id":"tq1","question":"Que se passerait-il en cas de coupure d''électricité ?","options":["Le personnel rentrerait chez lui.","Les données seraient sauvegardées automatiquement.","Les serveurs seraient éteints.","L''activité serait suspendue."],"answer":"Les données seraient sauvegardées automatiquement.","explanation":""},{"id":"tq2","question":"À quelle condition le personnel pourra-t-il travailler depuis Port-Harcourt ?","options":["si la connexion internet y est disponible","si le directeur l''accepte","si la panne dure moins d''un jour","si l''agence est ouverte le week-end"],"answer":"si la connexion internet y est disponible","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"Prends ton manteau au cas où il ___ froid.","options":["fera","fait","fasse","ferait"],"answer":"ferait","accepted":[],"explanation":"au cas où + conditionnel.","tag":"hypothesis","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"Je te prête ma voiture à condition que tu ___ prudent.","options":["serais","seras","sois","es"],"answer":"sois","accepted":[],"explanation":"à condition que + subjonctif.","tag":"hypothesis","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"___ de moyens, le projet a été abandonné. (for lack of)","options":[],"answer":"Faute","accepted":["faute"],"explanation":"faute de + nom.","tag":"hypothesis","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["d''urgence","cas","appelez","En","ce","numéro"],"answer":"En cas d''urgence appelez ce numéro","accepted":[],"explanation":"en cas de + nom.","tag":"hypothesis","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"Unless there is a strike, the train will leave on time.\"","options":[],"answer":"À moins d''une grève, le train partira à l''heure.","accepted":["À moins qu''il y ait une grève, le train partira à l''heure.","Sauf grève, le train partira à l''heure."],"explanation":"à moins de + nom.","tag":"hypothesis","id":"ex5"}],"writing_prompt":"Rédigez les consignes de sécurité pour un événement (concert, conférence) en variant les façons d''exprimer la condition.","writing_model":"En cas d''incendie, les participants devront quitter la salle par les sorties de secours. Au cas où un spectateur se sentirait mal, il pourra s''adresser au poste de secours situé à l''entrée. L''accès sera autorisé à condition que chacun présente son billet et une pièce d''identité. Pour peu que ces règles soient respectées, la soirée se déroulera dans les meilleures conditions.","writing_checklist":["au moins quatre structures différentes","bon mode après chaque conjonction (conditionnel, subjonctif)","registre formel"],"email_snippet":{"word_of_day":{"fr":"au cas où","en":"in case","example":"Prends un parapluie au cas où il pleuvrait."},"mini_question":{"prompt":"Prends ton manteau au cas où il ___ froid.","options":["fera","fait","fasse","ferait"],"answer":"ferait"}}}'::jsonb, 'approved', 'curriculum'),
  ('C1', 7, 'Le ne explétif', '{"level":"C1","seq":7,"theme":"Le ne explétif","vocabulary":[{"fr":"craindre","en":"to fear","example":"Je crains qu''il ne soit trop tard."},{"fr":"redouter","en":"to dread","example":"Elle redoute que son fils ne parte."},{"fr":"empêcher","en":"to prevent","example":"Rien n''empêche qu''il ne vienne."},{"fr":"éviter que","en":"to avoid","example":"Évitez que la porte ne claque."},{"fr":"de peur que","en":"for fear that","example":"Il parle bas de peur qu''on ne l''entende."},{"fr":"à moins que","en":"unless","example":"Je viendrai, à moins qu''il ne pleuve."},{"fr":"plus… que","en":"more… than","example":"Il est plus tard que je ne le pensais."},{"fr":"avant que","en":"before","example":"Rentrons avant qu''il ne fasse nuit."}],"grammar":{"topic":"Le ne explétif","explanation":"Le ne explétif n''a aucune valeur négative : il appartient au registre soutenu et reste facultatif.\nOn le trouve après :\n• les verbes de crainte : craindre que, avoir peur que, redouter que ;\n• avant que, à moins que, de peur que, de crainte que ;\n• éviter que, empêcher que ;\n• les comparaisons d''inégalité : plus / moins… que + verbe conjugué.\n« Je crains qu''il ne pleuve » = j''ai peur qu''il pleuve. Pour une vraie négation, il faut ne… pas : « Je crains qu''il ne pleuve pas. »","examples":["J''ai peur qu''il ne se trompe.","Partez avant qu''il ne soit trop tard.","C''est plus difficile que je ne l''imaginais.","Il faut éviter que la situation ne s''aggrave."]},"text":{"title":"Inquiétudes d''un éditeur","body":"L''éditeur craignait que le manuscrit ne soit pas prêt à temps. Il avait raison : l''auteure, de peur que son roman ne déçoive, réécrivait sans cesse le dernier chapitre. « Le livre est bien meilleur que je ne l''espérais », reconnaît-il aujourd''hui. Il a cependant dû repousser la sortie pour éviter que la presse ne reçoive une version inachevée.","questions":[{"id":"tq1","question":"Pourquoi l''auteure réécrivait-elle le dernier chapitre ?","options":["parce que l''éditeur l''exigeait","de peur que son roman déçoive","pour l''allonger","parce qu''elle manquait d''idées"],"answer":"de peur que son roman déçoive","explanation":""},{"id":"tq2","question":"Que signifie « Je crains qu''il ne soit pas prêt » ?","options":["Je suis sûr qu''il est prêt.","J''ai peur qu''il soit prêt.","J''ai peur qu''il ne soit pas prêt (négation réelle).","Je souhaite qu''il soit prêt."],"answer":"J''ai peur qu''il ne soit pas prêt (négation réelle).","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"« Je crains qu''il ne vienne. » signifie :","options":["J''ai peur qu''il vienne.","Je sais qu''il ne viendra pas.","Je souhaite qu''il vienne.","J''ai peur qu''il ne vienne pas."],"answer":"J''ai peur qu''il vienne.","accepted":[],"explanation":"Le ne explétif n''est pas négatif.","tag":"ne-expletif","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"Où peut-on employer un ne explétif ?","options":["Partons avant qu''il ___ pleuve.","Il dit qu''il ___ pleut.","Partons après qu''il ___ pleut.","Je pense qu''il ___ pleut."],"answer":"Partons avant qu''il ___ pleuve.","accepted":[],"explanation":"avant que admet le ne explétif.","tag":"ne-expletif","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"C''est plus simple que je ___ le croyais.","options":[],"answer":"ne","accepted":[],"explanation":"Comparaison d''inégalité → ne explétif possible.","tag":"ne-expletif","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["Il","tombe","ne","faut","éviter","l''enfant","que"],"answer":"Il faut éviter que l''enfant ne tombe","accepted":[],"explanation":"éviter que + ne explétif + subjonctif.","tag":"ne-expletif","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"I am afraid he might make a mistake. (formal)\"","options":[],"answer":"Je crains qu''il ne se trompe.","accepted":["J''ai peur qu''il ne se trompe.","Je crains qu''il ne fasse une erreur."],"explanation":"Verbe de crainte + ne explétif.","tag":"ne-expletif","id":"ex5"}],"writing_prompt":"Rédigez une note interne (100 mots) exprimant vos inquiétudes au sujet d''un projet, en utilisant le ne explétif au moins trois fois.","writing_model":"Je crains que le calendrier actuel ne soit trop ambitieux. Les tests ont révélé plus d''anomalies que nous ne l''avions prévu, et je redoute que le client ne découvre ces problèmes avant la livraison. Afin d''éviter que la situation ne se dégrade, je propose de reporter la mise en ligne de deux semaines. Il serait souhaitable de réunir l''équipe avant que les délais ne deviennent intenables.","writing_checklist":["ne explétif correctement placé (sans pas)","subjonctif après les verbes de crainte","registre soutenu"],"email_snippet":{"word_of_day":{"fr":"craindre","en":"to fear","example":"Je crains qu''il ne soit trop tard."},"mini_question":{"prompt":"« Je crains qu''il ne vienne. » signifie :","options":["J''ai peur qu''il vienne.","Je sais qu''il ne viendra pas.","Je souhaite qu''il vienne.","J''ai peur qu''il ne vienne pas."],"answer":"J''ai peur qu''il vienne."}}}'::jsonb, 'approved', 'curriculum'),
  ('C1', 8, 'Les verbes pronominaux et l''accord', '{"level":"C1","seq":8,"theme":"Les verbes pronominaux et l''accord","vocabulary":[{"fr":"se souvenir de","en":"to remember","example":"Elle s''est souvenue de son enfance."},{"fr":"s''apercevoir de","en":"to notice","example":"Ils se sont aperçus de leur erreur."},{"fr":"se succéder","en":"to follow one another","example":"Les ministres se sont succédé."},{"fr":"se plaire","en":"to enjoy (being somewhere)","example":"Elles se sont plu à Lyon."},{"fr":"se rendre compte","en":"to realise","example":"Elle s''est rendu compte du problème."},{"fr":"se laver les mains","en":"to wash one''s hands","example":"Elle s''est lavé les mains."},{"fr":"s''écrire","en":"to write to each other","example":"Ils se sont écrit pendant des années."},{"fr":"s''en aller","en":"to go away","example":"Elles s''en sont allées."}],"grammar":{"topic":"L''accord du participe passé des verbes pronominaux","explanation":"Règle de base : le participe s''accorde avec le COD si celui-ci est placé avant.\n• Se = COD → accord : « Elle s''est lavée » (elle a lavé qui ? se = elle).\n• COD après le verbe → pas d''accord : « Elle s''est lavé les mains. »\n• Se = COI (verbes construits avec à) → pas d''accord : « Ils se sont parlé » (parler à), se sont écrit, se sont téléphoné, se sont souri, se sont succédé, se sont plu.\n• Verbes essentiellement pronominaux (s''évanouir, se souvenir, s''apercevoir, s''en aller) → accord avec le sujet.\n• Exception : se rendre compte reste invariable.","examples":["Elles se sont regardées.","Elles se sont parlé longtemps.","Ils se sont souvenus de cette journée.","Elle s''est coupé le doigt."]},"text":{"title":"Des retrouvailles","body":"Amina et Joëlle se sont connues au lycée de Cotonou. Après le baccalauréat, elles se sont perdues de vue : l''une est partie à Paris, l''autre à Montréal. Pendant quelques années, elles se sont écrit de longues lettres, puis elles ne se sont plus parlé. Vingt ans plus tard, elles se sont croisées par hasard dans un aéroport. Elles se sont reconnues immédiatement et se sont souri, émues. Elles se sont rendu compte que rien n''avait changé.","questions":[{"id":"tq1","question":"Où se sont-elles connues ?","options":["dans un aéroport","au lycée de Cotonou","à Montréal","à Paris"],"answer":"au lycée de Cotonou","explanation":""},{"id":"tq2","question":"Comment se sont-elles retrouvées ?","options":["par hasard dans un aéroport","sur les réseaux sociaux","grâce à une lettre","lors d''un mariage"],"answer":"par hasard dans un aéroport","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"Elles se sont ___ pendant des heures. (parler)","options":["parlés","parlées","parlée","parlé"],"answer":"parlé","accepted":[],"explanation":"parler à → se = COI → invariable.","tag":"pronominal-agreement","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"Elle s''est ___ les cheveux.","options":["coupés","coupé","coupées","coupée"],"answer":"coupé","accepted":[],"explanation":"COD (les cheveux) après le verbe → pas d''accord.","tag":"pronominal-agreement","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"Ils se sont ___ de leur erreur. (s''apercevoir)","options":[],"answer":"aperçus","accepted":[],"explanation":"Verbe essentiellement pronominal → accord avec le sujet.","tag":"pronominal-agreement","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["se","Elles","du","compte","problème","sont","rendu"],"answer":"Elles se sont rendu compte du problème","accepted":[],"explanation":"se rendre compte : participe invariable.","tag":"pronominal-agreement","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"They (f.) looked at each other and smiled at each other.\"","options":[],"answer":"Elles se sont regardées et se sont souri.","accepted":[],"explanation":"regarder qqn → accord ; sourire à → invariable.","tag":"pronominal-agreement","id":"ex5"}],"writing_prompt":"Racontez une rencontre ou des retrouvailles (100 mots) en utilisant au moins cinq verbes pronominaux au passé composé, avec les bons accords.","writing_model":"Mes parents se sont rencontrés à un mariage en 1995. Ils se sont parlé toute la soirée et, le lendemain, ils se sont téléphoné. Pendant un an, ils se sont écrit chaque semaine, car ma mère étudiait à Dakar. Ils se sont mariés en 1997. Ma mère dit qu''elle s''est rendu compte très vite qu''ils s''étaient trouvés.","writing_checklist":["accord quand se est COD","pas d''accord quand se est COI (parler, écrire, téléphoner)","se rendre compte invariable"],"email_snippet":{"word_of_day":{"fr":"se souvenir de","en":"to remember","example":"Elle s''est souvenue de son enfance."},"mini_question":{"prompt":"Elles se sont ___ pendant des heures. (parler)","options":["parlés","parlées","parlée","parlé"],"answer":"parlé"}}}'::jsonb, 'approved', 'curriculum'),
  ('C1', 9, 'L''inversion du sujet', '{"level":"C1","seq":9,"theme":"L''inversion du sujet","vocabulary":[{"fr":"à peine… que","en":"hardly… when","example":"À peine était-il arrivé qu''il est reparti."},{"fr":"peut-être","en":"perhaps","example":"Peut-être a-t-il oublié."},{"fr":"sans doute","en":"probably / no doubt","example":"Sans doute viendra-t-elle demain."},{"fr":"aussi (en tête)","en":"therefore","example":"Il pleuvait ; aussi sommes-nous restés."},{"fr":"encore","en":"even then / still","example":"Encore faut-il qu''il accepte."},{"fr":"ainsi","en":"thus","example":"Ainsi s''achève notre voyage."},{"fr":"du moins","en":"at least","example":"Du moins le croyait-il."},{"fr":"toujours est-il que","en":"the fact remains","example":"Toujours est-il qu''il a gagné."}],"grammar":{"topic":"L''inversion du sujet après certains adverbes","explanation":"En registre soutenu, certains adverbes placés en tête de phrase entraînent l''inversion du sujet : peut-être, sans doute, à peine, aussi (= donc), encore, du moins, ainsi.\n• Sujet pronom : inversion simple. « Peut-être viendra-t-il. »\n• Sujet nom : inversion complexe (le nom reste, un pronom est ajouté). « Sans doute le ministre démissionnera-t-il. »\nAlternative courante : peut-être que / sans doute que + ordre normal : « Peut-être qu''il viendra. »\nN''oubliez pas le -t- euphonique entre deux voyelles : a-t-il, viendra-t-elle.","examples":["À peine avais-je fermé la porte que le téléphone a sonné.","Peut-être les résultats seront-ils meilleurs demain.","Le train était en retard ; aussi avons-nous pris un taxi.","Encore faudrait-il qu''il soit d''accord."]},"text":{"title":"Chronique d''une élection","body":"À peine les bureaux de vote avaient-ils fermé que les premiers résultats circulaient sur les réseaux sociaux. Sans doute certains chiffres étaient-ils fantaisistes ; aussi la commission électorale a-t-elle appelé à la prudence. Peut-être le vainqueur sera-t-il connu dès ce soir. Encore faut-il que le dépouillement se déroule sans incident. Toujours est-il que la participation, du moins dans les grandes villes, semble exceptionnelle.","questions":[{"id":"tq1","question":"Pourquoi la commission a-t-elle appelé à la prudence ?","options":["parce que certains chiffres circulant étaient sans doute faux","parce que les bureaux étaient fermés","parce que le vainqueur était connu","parce que la participation était faible"],"answer":"parce que certains chiffres circulant étaient sans doute faux","explanation":""},{"id":"tq2","question":"Que dit le texte de la participation ?","options":["Elle est inconnue.","Elle semble exceptionnelle, au moins dans les grandes villes.","Elle est très faible.","Elle est identique à la dernière élection."],"answer":"Elle semble exceptionnelle, au moins dans les grandes villes.","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"Forme soutenue correcte :","options":["Peut-être il viendra demain.","Peut-être viendra-t-il demain.","Peut-être que viendra-t-il demain.","Peut-être viendra il demain."],"answer":"Peut-être viendra-t-il demain.","accepted":[],"explanation":"Peut-être en tête → inversion.","tag":"inversion","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"À peine ___ qu''il s''est mis à pleuvoir.","options":["nous sommes sortis","nous étions sortis","étions-nous sortis","sortions-nous"],"answer":"étions-nous sortis","accepted":[],"explanation":"À peine + inversion + que.","tag":"inversion","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"Il était fatigué ; aussi ___-il rentré tôt. (être)","options":[],"answer":"est","accepted":[],"explanation":"aussi (= donc) en tête → inversion : aussi est-il rentré.","tag":"inversion","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["Sans","acceptera-t-il","doute","proposition","la","directeur","le"],"answer":"Sans doute le directeur acceptera-t-il la proposition","accepted":[],"explanation":"Inversion complexe avec un sujet nominal.","tag":"inversion","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"Perhaps the minister will resign.\"","options":[],"answer":"Peut-être le ministre démissionnera-t-il.","accepted":["Peut-être que le ministre démissionnera.","Le ministre démissionnera peut-être."],"explanation":"Inversion complexe en registre soutenu.","tag":"inversion","id":"ex5"}],"writing_prompt":"Rédigez un court commentaire d''actualité (100 mots) en registre soutenu, avec au moins trois inversions après adverbe.","writing_model":"À peine la nouvelle loi avait-elle été votée que les syndicats annonçaient une grève. Sans doute le gouvernement espérait-il un accueil plus favorable. Les négociations semblent bloquées ; aussi faut-il craindre un mouvement prolongé. Peut-être un compromis sera-t-il trouvé d''ici la fin du mois. Encore faudrait-il que chaque partie accepte de faire des concessions.","writing_checklist":["inversion simple et complexe","-t- euphonique","registre soutenu cohérent"],"email_snippet":{"word_of_day":{"fr":"à peine… que","en":"hardly… when","example":"À peine était-il arrivé qu''il est reparti."},"mini_question":{"prompt":"Forme soutenue correcte :","options":["Peut-être il viendra demain.","Peut-être viendra-t-il demain.","Peut-être que viendra-t-il demain.","Peut-être viendra il demain."],"answer":"Peut-être viendra-t-il demain."}}}'::jsonb, 'approved', 'curriculum'),
  ('C1', 10, 'Les faux amis', '{"level":"C1","seq":10,"theme":"Les faux amis","vocabulary":[{"fr":"actuellement","en":"currently (not ''actually'')","example":"Il est actuellement en réunion."},{"fr":"éventuellement","en":"possibly (not ''eventually'')","example":"Je viendrai éventuellement."},{"fr":"une librairie","en":"a bookshop (not ''library'')","example":"J''ai acheté ce roman en librairie."},{"fr":"sensible","en":"sensitive (not ''sensible'')","example":"C''est un enfant très sensible."},{"fr":"assister à","en":"to attend (not ''assist'')","example":"J''ai assisté à la conférence."},{"fr":"rester","en":"to stay (not ''rest'')","example":"Je reste à la maison ce soir."},{"fr":"une journée","en":"a day (not ''journey'')","example":"Quelle belle journée !"},{"fr":"prétendre","en":"to claim (not ''pretend'')","example":"Il prétend être médecin."}],"grammar":{"topic":"Les faux amis anglais–français","explanation":"Les faux amis sont des mots qui se ressemblent dans deux langues mais n''ont pas le même sens. Ils sont une source d''erreurs fréquentes chez les anglophones, même avancés.\n• actually → en fait ; actuellement → currently.\n• eventually → finalement ; éventuellement → possibly.\n• library → bibliothèque ; librairie → bookshop.\n• sensible → raisonnable / sensé ; sensible → sensitive.\n• to pretend → faire semblant ; prétendre → to claim.\n• to attend → assister à ; attendre → to wait.\n• journey → voyage / trajet ; journée → day.","examples":["En fait, je n''ai pas compris. (Actually…)","Finalement, il a accepté. (Eventually…)","Je vais à la bibliothèque pour emprunter un livre.","Sois raisonnable ! (Be sensible!)"]},"text":{"title":"Malentendus franco-anglais","body":"Lors de son premier séjour à Paris, Tunde a accumulé les malentendus. Il a dit à sa logeuse qu''il voulait « rester » après le déjeuner, alors qu''il voulait simplement se reposer. Il a cherché des livres à emprunter dans une librairie, où on lui a expliqué qu''il fallait aller à la bibliothèque. Enfin, il a écrit à son professeur qu''il viendrait « éventuellement » au cours, ce qui a beaucoup inquiété celui-ci : il voulait dire « finalement » !","questions":[{"id":"tq1","question":"Que voulait dire Tunde quand il a dit « rester » ?","options":["ne pas partir","se reposer","dormir à l''hôtel","attendre"],"answer":"se reposer","explanation":""},{"id":"tq2","question":"Pourquoi le professeur était-il inquiet ?","options":["Il a compris que Tunde viendrait peut-être.","Tunde ne venait jamais.","Tunde voulait changer de cours.","Tunde était malade."],"answer":"Il a compris que Tunde viendrait peut-être.","explanation":""}]},"exercises":[{"type":"mcq","skill":"vocabulary","prompt":"« Actually, I don''t know. » →","options":["Éventuellement, je ne sais pas.","Actuellement, je ne sais pas.","En fait, je ne sais pas.","Actuel, je ne sais pas."],"answer":"En fait, je ne sais pas.","accepted":[],"explanation":"actually = en fait.","tag":"false-friends","id":"ex1"},{"type":"mcq","skill":"vocabulary","prompt":"« I attended the meeting. » →","options":["J''ai assisté la réunion.","J''ai aidé la réunion.","J''ai attendu la réunion.","J''ai assisté à la réunion."],"answer":"J''ai assisté à la réunion.","accepted":[],"explanation":"to attend = assister à.","tag":"false-friends","id":"ex2"},{"type":"fill_blank","skill":"vocabulary","prompt":"Pour emprunter des livres, je vais à la ___.","options":[],"answer":"bibliothèque","accepted":["bibliotheque"],"explanation":"library = bibliothèque.","tag":"false-friends","id":"ex3"},{"type":"reorder","skill":"vocabulary","prompt":"Put the words in the right order.","options":["Il","de","dormir","semblant","fait"],"answer":"Il fait semblant de dormir","accepted":[],"explanation":"to pretend = faire semblant.","tag":"false-friends","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"Eventually, she accepted the offer.\"","options":[],"answer":"Finalement, elle a accepté l''offre.","accepted":["Finalement, elle a accepté la proposition.","Elle a fini par accepter l''offre."],"explanation":"eventually = finalement.","tag":"false-friends","id":"ex5"}],"writing_prompt":"Racontez un malentendu linguistique (réel ou imaginaire) et expliquez-le, en employant correctement au moins quatre faux amis.","writing_model":"Le jour de mon arrivée à Lyon, j''ai dit à mon collègue que j''étais « excité » par mon nouveau poste. Il a souri : en français, on dit plutôt « enthousiaste ». Plus tard, je lui ai demandé où se trouvait la librairie de l''entreprise, alors que je cherchais la bibliothèque. Actuellement, je fais beaucoup plus attention ; en fait, j''adore collectionner ces faux amis !","writing_checklist":["au moins quatre faux amis employés au bon sens","explication du malentendu","récit cohérent"],"email_snippet":{"word_of_day":{"fr":"actuellement","en":"currently (not ''actually'')","example":"Il est actuellement en réunion."},"mini_question":{"prompt":"« Actually, I don''t know. » →","options":["Éventuellement, je ne sais pas.","Actuellement, je ne sais pas.","En fait, je ne sais pas.","Actuel, je ne sais pas."],"answer":"En fait, je ne sais pas."}}}'::jsonb, 'approved', 'curriculum'),
  ('C1', 11, 'Cause et conséquence nuancées', '{"level":"C1","seq":11,"theme":"Cause et conséquence nuancées","vocabulary":[{"fr":"d''autant plus que","en":"all the more so because","example":"C''est grave, d''autant plus qu''il récidive."},{"fr":"sous prétexte que","en":"on the pretext that","example":"Il est parti sous prétexte qu''il était malade."},{"fr":"étant donné que","en":"given that","example":"Étant donné que le magasin est fermé, revenons demain."},{"fr":"si bien que","en":"so that (result)","example":"Il a plu, si bien que le match a été annulé."},{"fr":"de sorte que","en":"so that","example":"Il parle fort de sorte que tout le monde l''entend."},{"fr":"entraîner","en":"to lead to / cause","example":"Cette décision a entraîné des grèves."},{"fr":"découler de","en":"to result from","example":"Ce problème découle d''une erreur."},{"fr":"en raison de","en":"due to","example":"En raison de la grève, le train est annulé."}],"grammar":{"topic":"Nuancer la cause et la conséquence","explanation":"CAUSE : parce que (neutre), puisque (cause connue), comme (en tête), étant donné que / vu que (fait établi), d''autant plus que (cause renforcée), sous prétexte que (cause contestée), non que + subjonctif (cause rejetée) ; + nom : en raison de (neutre), grâce à (positive), à cause de (négative), faute de (manque).\nCONSÉQUENCE : donc, c''est pourquoi, si bien que, de sorte que + indicatif (résultat), tellement / si… que, au point que ; de sorte que + subjonctif exprime le but.\nVerbes : entraîner, provoquer, susciter, découler de, résulter de.","examples":["Il a refusé, non qu''il soit paresseux, mais il était épuisé.","Le budget a été réduit, si bien que le projet a pris du retard.","J''apprécie ce film, d''autant plus que l''actrice est nigériane.","Cette crise résulte d''une mauvaise gestion."]},"text":{"title":"Pénurie d''eau","body":"La ville connaît une pénurie d''eau sans précédent. Celle-ci découle d''abord d''une sécheresse exceptionnelle, mais elle s''explique aussi par l''état du réseau : faute d''entretien, près d''un tiers de l''eau se perd dans des fuites. La situation est d''autant plus préoccupante que la population a doublé en vingt ans. Les autorités ont imposé des restrictions, si bien que certains quartiers ne sont alimentés que deux jours par semaine. Certains élus refusent les travaux sous prétexte qu''ils coûteraient trop cher.","questions":[{"id":"tq1","question":"Quelles sont les deux causes principales de la pénurie ?","options":["la pollution et la guerre","la sécheresse et les fuites du réseau","la hausse des prix et la sécheresse","les restrictions et les élus"],"answer":"la sécheresse et les fuites du réseau","explanation":""},{"id":"tq2","question":"Quel est l''effet des restrictions ?","options":["Certains quartiers n''ont de l''eau que deux jours par semaine.","La population a doublé.","L''eau est devenue gratuite.","Les fuites ont été réparées."],"answer":"Certains quartiers n''ont de l''eau que deux jours par semaine.","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"Il n''est pas venu, ___ il avait du travail. (cause contestée)","options":["afin qu''","si bien qu''","grâce à ce qu''","sous prétexte qu''"],"answer":"sous prétexte qu''","accepted":[],"explanation":"sous prétexte que = cause qu''on met en doute.","tag":"cause","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"Il a beaucoup neigé, ___ les routes sont fermées.","options":["puisque","étant donné que","faute de","si bien que"],"answer":"si bien que","accepted":[],"explanation":"Conséquence → si bien que + indicatif.","tag":"consequence","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"___ d''argent, ils ont abandonné le projet.","options":[],"answer":"Faute","accepted":["faute"],"explanation":"faute de + nom = par manque de.","tag":"cause","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["d''une","gestion","résulte","Cette","mauvaise","crise"],"answer":"Cette crise résulte d''une mauvaise gestion","accepted":[],"explanation":"résulter de = découler de.","tag":"cause","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"Due to the storm, the flight was cancelled.\"","options":[],"answer":"En raison de la tempête, le vol a été annulé.","accepted":["À cause de la tempête, le vol a été annulé."],"explanation":"en raison de + nom (cause neutre).","tag":"cause","id":"ex5"}],"writing_prompt":"Analysez les causes et les conséquences d''un problème de société de votre pays (150 mots), en variant les connecteurs.","writing_model":"Les embouteillages de Lagos résultent de plusieurs facteurs. D''abord, la population a explosé en trente ans, si bien que les routes ne suffisent plus. Ensuite, faute de transports publics efficaces, la plupart des habitants utilisent leur voiture ou des motos-taxis. Le problème est d''autant plus grave que les chantiers sont souvent interrompus en raison de difficultés budgétaires. Ces embouteillages entraînent des pertes économiques considérables et dégradent la qualité de l''air. Certains responsables refusent de développer le métro sous prétexte que le projet serait trop coûteux ; pourtant, ne rien faire coûte bien plus cher.","writing_checklist":["au moins quatre connecteurs de cause et trois de conséquence","verbes de causalité (entraîner, résulter de…)","argumentation structurée"],"email_snippet":{"word_of_day":{"fr":"d''autant plus que","en":"all the more so because","example":"C''est grave, d''autant plus qu''il récidive."},"mini_question":{"prompt":"Il n''est pas venu, ___ il avait du travail. (cause contestée)","options":["afin qu''","si bien qu''","grâce à ce qu''","sous prétexte qu''"],"answer":"sous prétexte qu''"}}}'::jsonb, 'approved', 'curriculum'),
  ('C1', 12, 'La synthèse de documents', '{"level":"C1","seq":12,"theme":"La synthèse de documents","vocabulary":[{"fr":"selon / d''après","en":"according to","example":"Selon le premier document, la demande augmente."},{"fr":"rejoindre","en":"to agree with / echo","example":"Le second article rejoint cette analyse."},{"fr":"nuancer","en":"to qualify","example":"L''auteur nuance ce constat."},{"fr":"mettre en évidence","en":"to highlight","example":"L''étude met en évidence un paradoxe."},{"fr":"s''opposer à","en":"to contrast with / oppose","example":"Ce point de vue s''oppose au précédent."},{"fr":"la problématique","en":"the central question","example":"Quelle est la problématique de ce dossier ?"},{"fr":"en définitive","en":"ultimately","example":"En définitive, les deux auteurs s''accordent."},{"fr":"dégager","en":"to draw out (ideas)","example":"Il faut dégager les idées principales."}],"grammar":{"topic":"Rédiger une synthèse","explanation":"La synthèse (épreuve du DALF C1) consiste à confronter plusieurs documents sans donner son avis.\nMéthode :\n1. Dégager la problématique commune.\n2. Introduction : thème + problématique + annonce du plan.\n3. Développement en deux ou trois parties organisées par idées, et non document par document.\n4. Conclusion : bilan, sans opinion personnelle.\nOutils : selon X, d''après Y, X souligne / met en évidence / constate que…, Y rejoint / nuance / s''oppose à…, tandis que, alors que, de même.\nInterdits : citations recopiées, « je », informations extérieures aux documents.","examples":["Les deux documents s''accordent sur l''urgence de la situation.","Alors que le premier auteur insiste sur les coûts, le second met en évidence les bénéfices.","Cette analyse est nuancée par l''enquête de l''INSEE.","En définitive, si les constats convergent, les solutions divergent."]},"text":{"title":"Extrait d''une synthèse","body":"Les deux documents s''interrogent sur l''avenir du travail à l''ère de l''intelligence artificielle. Selon l''article du Monde, l''automatisation menacerait près d''un emploi sur quatre d''ici 2035. Le rapport de l''OCDE nuance ce constat : s''il reconnaît que certaines tâches disparaîtront, il met en évidence la création de nouveaux métiers. Tous deux s''accordent néanmoins sur la nécessité d''investir massivement dans la formation continue. En définitive, la question n''est pas tant de savoir si le travail va changer que de savoir comment accompagner cette transformation.","questions":[{"id":"tq1","question":"Sur quel point les deux documents s''accordent-ils ?","options":["la baisse des salaires","la disparition d''un emploi sur quatre","la nécessité d''investir dans la formation","l''interdiction de l''IA"],"answer":"la nécessité d''investir dans la formation","explanation":""},{"id":"tq2","question":"Comment le rapport de l''OCDE se situe-t-il par rapport à l''article ?","options":["Il n''en parle pas.","Il nuance son constat.","Il le confirme totalement.","Il le rejette entièrement."],"answer":"Il nuance son constat.","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"Dans une synthèse, on doit :","options":["confronter les documents sans donner son avis","ajouter des exemples extérieurs","donner son opinion personnelle","résumer chaque document séparément"],"answer":"confronter les documents sans donner son avis","accepted":[],"explanation":"La synthèse est objective et organisée par idées.","tag":"synthesis","id":"ex1"},{"type":"mcq","skill":"vocabulary","prompt":"« Le second document ___ cette analyse. » (va dans le même sens)","options":["nuance","rejoint","contredit","ignore"],"answer":"rejoint","accepted":[],"explanation":"rejoindre = être d''accord avec.","tag":"synthesis","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"___ le premier auteur insiste sur les risques, le second souligne les avantages.","options":[],"answer":"Alors que","accepted":["alors que","Tandis que","tandis que"],"explanation":"Opposition entre deux documents : alors que / tandis que.","tag":"synthesis","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["documents","Les","sur","s''accordent","du","l''urgence","problème","deux"],"answer":"Les deux documents s''accordent sur l''urgence du problème","accepted":[],"explanation":"Formule de convergence.","tag":"synthesis","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"Ultimately, the two authors agree on the causes.\"","options":[],"answer":"En définitive, les deux auteurs s''accordent sur les causes.","accepted":["En définitive, les deux auteurs sont d''accord sur les causes."],"explanation":"en définitive + s''accorder sur.","tag":"synthesis","id":"ex5"}],"writing_prompt":"Rédigez l''introduction et le plan d''une synthèse sur le thème « Les villes face au changement climatique » (deux documents imaginaires : l''un sur les inondations à Lagos, l''autre sur les toits végétalisés à Paris).","writing_model":"Introduction : Les deux documents abordent la manière dont les grandes villes s''adaptent aux effets du changement climatique. Alors que le premier décrit les inondations de plus en plus fréquentes qui frappent Lagos, le second présente les toits végétalisés comme une réponse innovante à la chaleur urbaine à Paris. Dans quelle mesure les villes peuvent-elles devenir plus résilientes ? Nous verrons d''abord les menaces communes mises en évidence par les documents, puis les solutions qu''ils proposent.\nPlan : I. Des villes de plus en plus vulnérables (inondations, chaleur, densité). II. Des stratégies d''adaptation encore inégales (infrastructures, végétalisation, financement).","writing_checklist":["problématique formulée en question","plan thématique, pas document par document","aucune opinion personnelle ni « je »"],"email_snippet":{"word_of_day":{"fr":"selon / d''après","en":"according to","example":"Selon le premier document, la demande augmente."},"mini_question":{"prompt":"Dans une synthèse, on doit :","options":["confronter les documents sans donner son avis","ajouter des exemples extérieurs","donner son opinion personnelle","résumer chaque document séparément"],"answer":"confronter les documents sans donner son avis"}}}'::jsonb, 'approved', 'curriculum'),
  ('C2', 1, 'Le passé simple et le récit littéraire', '{"level":"C2","seq":1,"theme":"Le passé simple et le récit littéraire","vocabulary":[{"fr":"il fut","en":"he was (passé simple)","example":"Ce fut une nuit étrange."},{"fr":"elle eut","en":"she had (passé simple)","example":"Elle eut soudain une idée."},{"fr":"ils firent","en":"they did / made","example":"Ils firent route vers le nord."},{"fr":"il vint","en":"he came","example":"Le messager vint à l''aube."},{"fr":"elle prit","en":"she took","example":"Elle prit la lettre et la lut."},{"fr":"ils virent","en":"they saw","example":"Ils virent la mer pour la première fois."},{"fr":"le crépuscule","en":"dusk","example":"Au crépuscule, le village se tut."},{"fr":"se taire (il se tut)","en":"to fall silent","example":"L''assemblée se tut."}],"grammar":{"topic":"Le passé simple et le passé antérieur","explanation":"Le passé simple est le temps du récit écrit (romans, contes, histoire). Il remplace le passé composé à l''écrit littéraire, en alternance avec l''imparfait.\nTerminaisons : -er → -ai, -as, -a, -âmes, -âtes, -èrent ; -ir et beaucoup de -re → -is, -is, -it, -îmes, -îtes, -irent ; d''autres → -us, -us, -ut… (être : je fus ; avoir : j''eus ; venir : je vins ; faire : je fis ; voir : je vis).\nLe passé antérieur (auxiliaire au passé simple + participe) exprime une action achevée juste avant une autre au passé simple, après quand, dès que, lorsque, à peine… que : « Quand il eut fini, il sortit. »","examples":["Il ouvrit la porte et entra sans un mot.","Ils vécurent heureux et eurent beaucoup d''enfants.","Dès qu''elle eut reçu la lettre, elle partit.","Nous fûmes surpris par l''orage."]},"text":{"title":"L''étranger du fleuve","body":"Ce soir-là, le fleuve était si calme qu''on eût dit un miroir. Le vieux pêcheur rangeait ses filets lorsqu''il aperçut une pirogue inconnue. Un homme en descendit, le visage couvert de poussière. Il salua d''un geste, demanda de l''eau, puis s''assit sans un mot. Quand il eut bu, il sortit de sa besace une carte jaunie et la tendit au pêcheur. Celui-ci la regarda longtemps ; il comprit alors que le voyageur cherchait le village englouti dont parlaient les légendes.","questions":[{"id":"tq1","question":"Que fit l''étranger après avoir bu ?","options":["Il tendit une carte au pêcheur.","Il repartit aussitôt.","Il raconta une légende.","Il pêcha avec le vieil homme."],"answer":"Il tendit une carte au pêcheur.","explanation":""},{"id":"tq2","question":"Que cherchait le voyageur ?","options":["sa famille","un trésor de pêcheur","un passage vers la mer","un village englouti"],"answer":"un village englouti","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"Passé simple de « venir » (il) :","options":["il venit","il vena","il vint","il vinrent"],"answer":"il vint","accepted":[],"explanation":"venir → je vins, il vint.","tag":"passe-simple","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"Quand il ___ terminé, il se leva.","options":["aura","eut","avait","a"],"answer":"eut","accepted":[],"explanation":"Passé antérieur : eut + participe, avec quand et un passé simple.","tag":"passe-anterieur","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"Ils ___ le voyage à pied. (faire, passé simple)","options":[],"answer":"firent","accepted":[],"explanation":"faire → ils firent.","tag":"passe-simple","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["la","et","Elle","prit","silence","lettre","la","lut","en"],"answer":"Elle prit la lettre et la lut en silence","accepted":[],"explanation":"Enchaînement d''actions au passé simple.","tag":"passe-simple","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"He opened the door and saw the sea.\"","options":[],"answer":"Il ouvrit la porte et vit la mer.","accepted":["Il ouvrit la porte et aperçut la mer."],"explanation":"Récit littéraire → passé simple.","tag":"passe-simple","id":"ex5"}],"writing_prompt":"Écrivez le début d''un conte (120 mots) au passé simple et à l''imparfait, avec au moins un passé antérieur.","writing_model":"Il était une fois, au bord du lac Tchad, une jeune tisserande qui ne parlait jamais. Chaque matin, elle s''asseyait devant sa maison et tissait des étoffes d''une beauté étrange. Un jour, un marchand venu du Nord s''arrêta devant elle. Il contempla longuement son travail, puis il lui offrit tout l''or qu''il possédait. La jeune femme refusa d''un signe de tête. Dès que le marchand fut reparti, elle déroula la dernière étoffe : on y voyait le visage de l''homme, tissé la veille.","writing_checklist":["imparfait pour le décor, passé simple pour les actions","au moins un passé antérieur après dès que / quand","registre littéraire"],"email_snippet":{"word_of_day":{"fr":"il fut","en":"he was (passé simple)","example":"Ce fut une nuit étrange."},"mini_question":{"prompt":"Passé simple de « venir » (il) :","options":["il venit","il vena","il vint","il vinrent"],"answer":"il vint"}}}'::jsonb, 'approved', 'curriculum'),
  ('C2', 2, 'Le subjonctif imparfait', '{"level":"C2","seq":2,"theme":"Le subjonctif imparfait","vocabulary":[{"fr":"qu''il fût","en":"that he was / were","example":"Il fallait qu''il fût présent."},{"fr":"qu''il eût","en":"that he had","example":"Bien qu''il eût raison, on l''ignora."},{"fr":"qu''elle vînt","en":"that she came","example":"Il souhaitait qu''elle vînt."},{"fr":"qu''il fît","en":"that he did","example":"On attendait qu''il fît un geste."},{"fr":"qu''ils pussent","en":"that they could","example":"Il fallait qu''ils pussent partir."},{"fr":"on eût dit","en":"one would have said","example":"On eût dit un tableau."},{"fr":"dût-il","en":"even if he had to","example":"Il le fera, dût-il y passer la nuit."},{"fr":"fût-ce","en":"even if it were","example":"Il refusa, fût-ce pour un jour."}],"grammar":{"topic":"Les subjonctifs imparfait et plus-que-parfait","explanation":"Dans la langue littéraire, quand le verbe principal est au passé, la concordance stricte exige le subjonctif imparfait (simultanéité) ou plus-que-parfait (antériorité).\nFormation de l''imparfait : à partir du passé simple (il fut → qu''il fût ; il chanta → qu''il chantât) ; terminaisons -sse, -sses, -^t, -ssions, -ssiez, -ssent : que je chantasse, qu''il chantât.\nPlus-que-parfait : eût / fût + participe : qu''il eût fini, qu''elle fût partie.\nLe plus-que-parfait du subjonctif sert aussi de « conditionnel passé deuxième forme » : « Si j''eusse su, je fusse venu. » / « On eût dit… »\nAujourd''hui, ces formes sont surtout lues ; à l''oral, on emploie le subjonctif présent et passé.","examples":["Le roi exigea qu''on lui obéît.","Bien qu''il fût malade, il continua de travailler.","Je craignais qu''elle ne fût déjà partie.","Il eût fallu agir plus tôt."]},"text":{"title":"Extrait de mémoires","body":"Mon père voulait que j''apprisse le latin, bien que je n''en visse guère l''utilité. Il fallait qu''aucune heure ne fût perdue ; aussi le précepteur arrivait-il dès l''aube. J''eusse préféré courir dans les champs, mais il eût été impensable de désobéir. Ce n''est que bien plus tard que je compris : il souhaitait que je pusse lire les auteurs anciens sans intermédiaire, comme si les livres avaient été pour lui une forme de liberté.","questions":[{"id":"tq1","question":"Que souhaitait le père du narrateur ?","options":["qu''il travaille aux champs","qu''il apprenne le latin","qu''il voyage","qu''il devienne précepteur"],"answer":"qu''il apprenne le latin","explanation":""},{"id":"tq2","question":"Quel sens donne le narrateur, plus tard, à ce souhait ?","options":["Il devait devenir prêtre.","Son père voulait le punir.","Lire les auteurs anciens était une forme de liberté.","Le latin était nécessaire pour travailler."],"answer":"Lire les auteurs anciens était une forme de liberté.","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"Subjonctif imparfait de « être » (il) :","options":["qu''il fut","qu''il soit","qu''il fusse","qu''il fût"],"answer":"qu''il fût","accepted":[],"explanation":"il fut (passé simple) → qu''il fût (accent circonflexe).","tag":"subjonctif-imparfait","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"« On eût dit un rêve » signifie :","options":["On a dit un rêve.","On aurait dit un rêve.","On dira un rêve.","On disait un rêve."],"answer":"On aurait dit un rêve.","accepted":[],"explanation":"Plus-que-parfait du subjonctif = conditionnel passé 2e forme.","tag":"subjonctif-imparfait","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"Il exigea qu''elle ___ sur-le-champ. (venir, subj. imparfait)","options":[],"answer":"vînt","accepted":[],"explanation":"venir → elle vint → qu''elle vînt.","tag":"subjonctif-imparfait","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["Bien","qu''il","d''écrire","il","tard","continua","fût"],"answer":"Bien qu''il fût tard il continua d''écrire","accepted":[],"explanation":"Concordance littéraire au passé.","tag":"subjonctif-imparfait","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"It would have been necessary to act sooner. (literary)\"","options":[],"answer":"Il eût fallu agir plus tôt.","accepted":["Il aurait fallu agir plus tôt."],"explanation":"eût fallu = aurait fallu (littéraire).","tag":"subjonctif-imparfait","id":"ex5"}],"writing_prompt":"Réécrivez dans un style littéraire (subjonctif imparfait et plus-que-parfait) le passage suivant : « Mes parents voulaient que je devienne médecin. Bien que je sois doué pour le dessin, ils ne voulaient pas que j''en fasse mon métier. Il aurait fallu que je sois plus courageux. »","writing_model":"Mes parents voulaient que je devinsse médecin. Bien que je fusse doué pour le dessin, ils ne souhaitaient pas que j''en fisse mon métier. Il eût fallu que je fusse plus courageux ; peut-être alors eussé-je osé leur tenir tête.","writing_checklist":["subjonctif imparfait après un verbe principal au passé","eût / fût pour le conditionnel passé 2e forme","accents circonflexes (fût, fît, vînt)"],"email_snippet":{"word_of_day":{"fr":"qu''il fût","en":"that he was / were","example":"Il fallait qu''il fût présent."},"mini_question":{"prompt":"Subjonctif imparfait de « être » (il) :","options":["qu''il fut","qu''il soit","qu''il fusse","qu''il fût"],"answer":"qu''il fût"}}}'::jsonb, 'approved', 'curriculum'),
  ('C2', 3, 'Les figures de style', '{"level":"C2","seq":3,"theme":"Les figures de style","vocabulary":[{"fr":"la métaphore","en":"metaphor","example":"« Cet homme est un lion » est une métaphore."},{"fr":"la comparaison","en":"simile","example":"« Fort comme un lion » est une comparaison."},{"fr":"la litote","en":"litotes (understatement)","example":"« Ce n''est pas mauvais » est une litote."},{"fr":"l''hyperbole (f.)","en":"hyperbole","example":"« Je meurs de faim » est une hyperbole."},{"fr":"l''oxymore (m.)","en":"oxymoron","example":"« Un silence assourdissant » est un oxymore."},{"fr":"l''euphémisme (m.)","en":"euphemism","example":"« Il nous a quittés » est un euphémisme."},{"fr":"la personnification","en":"personification","example":"« La ville s''éveille » est une personnification."},{"fr":"l''antithèse (f.)","en":"antithesis","example":"« Je vis, je meurs » est une antithèse."}],"grammar":{"topic":"Reconnaître et analyser les figures de style","explanation":"• Comparaison : rapprochement avec un outil (comme, tel, pareil à).\n• Métaphore : rapprochement sans outil (« ce gouffre de tristesse »).\n• Personnification : attribuer des traits humains à une chose.\n• Hyperbole : exagération.\n• Litote : dire moins pour suggérer plus (« Va, je ne te hais point » — Corneille).\n• Euphémisme : atténuer une réalité pénible.\n• Oxymore : deux termes contradictoires réunis (« cette obscure clarté »).\n• Antithèse : opposition de deux idées dans une même phrase.\nAnalyser une figure, c''est la nommer ET expliquer son effet.","examples":["« Ses yeux étaient deux étoiles. » (métaphore)","« Le vent hurlait dans la nuit. » (personnification)","« Je te l''ai dit mille fois ! » (hyperbole)","« Il n''est pas très malin. » (litote)"]},"text":{"title":"Lecture d''un poème en prose","body":"« La ville dormait, géante assoupie aux mille yeux éteints. Seul le fleuve veillait, serpent d''argent qui murmurait aux ponts ses secrets millénaires. Dans ce silence assourdissant, un homme marchait, aussi léger qu''une ombre. Il n''était pas tout à fait malheureux ; il était seulement seul. » Dans ce passage, l''auteur multiplie les images : la ville et le fleuve prennent vie, tandis que l''oxymore du silence souligne l''étrangeté de la nuit.","questions":[{"id":"tq1","question":"Quelle figure trouve-t-on dans « serpent d''argent » ?","options":["une comparaison","une antithèse","une métaphore","une litote"],"answer":"une métaphore","explanation":""},{"id":"tq2","question":"« Il n''était pas tout à fait malheureux » est :","options":["une litote","une personnification","un oxymore","une hyperbole"],"answer":"une litote","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"« Un silence assourdissant » est :","options":["une hyperbole","un euphémisme","une comparaison","un oxymore"],"answer":"un oxymore","accepted":[],"explanation":"Deux termes contradictoires réunis.","tag":"stylistics","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"« Il est fort comme un bœuf » est :","options":["une métaphore","une litote","une comparaison","une personnification"],"answer":"une comparaison","accepted":[],"explanation":"Outil de comparaison : comme.","tag":"stylistics","id":"ex2"},{"type":"fill_blank","skill":"vocabulary","prompt":"« Il nous a quittés » pour « il est mort » est un ___.","options":[],"answer":"euphémisme","accepted":["euphemisme"],"explanation":"Atténuation d''une réalité pénible.","tag":"stylistics","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["vent","Le","les","gémissait","volets","contre"],"answer":"Le vent gémissait contre les volets","accepted":[],"explanation":"Personnification : le vent gémit comme un humain.","tag":"stylistics","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"The city wakes up slowly. (personification)\"","options":[],"answer":"La ville s''éveille lentement.","accepted":["La ville se réveille lentement."],"explanation":"Personnification de la ville.","tag":"stylistics","id":"ex5"}],"writing_prompt":"Décrivez un lieu qui vous est cher (100 mots) en employant au moins cinq figures de style différentes, que vous identifierez entre parenthèses.","writing_model":"Le marché de Balogun est un océan de couleurs (métaphore) où les voix des vendeuses chantent plus fort que les klaxons (personnification). On y croise un million de visages (hyperbole) et l''on y respire un parfum aussi épicé qu''un plat de jollof (comparaison). Ce n''est pas l''endroit le plus calme de Lagos (litote), mais dans ce chaos ordonné (oxymore), je me sens chez moi.","writing_checklist":["au moins cinq figures différentes","identification correcte de chaque figure","effet expressif cohérent"],"email_snippet":{"word_of_day":{"fr":"la métaphore","en":"metaphor","example":"« Cet homme est un lion » est une métaphore."},"mini_question":{"prompt":"« Un silence assourdissant » est :","options":["une hyperbole","un euphémisme","une comparaison","un oxymore"],"answer":"un oxymore"}}}'::jsonb, 'approved', 'curriculum'),
  ('C2', 4, 'Le style journalistique', '{"level":"C2","seq":4,"theme":"Le style journalistique","vocabulary":[{"fr":"le chapeau","en":"the standfirst / lead","example":"Le chapeau résume l''article."},{"fr":"la une","en":"the front page","example":"L''affaire fait la une des journaux."},{"fr":"un éditorial","en":"an editorial","example":"L''éditorial critique le gouvernement."},{"fr":"un entrefilet","en":"a short news item","example":"L''information tient en un entrefilet."},{"fr":"selon nos informations","en":"according to our sources","example":"Selon nos informations, le ministre démissionnerait."},{"fr":"le conditionnel journalistique","en":"the journalistic conditional","example":"L''accident aurait fait trois blessés."},{"fr":"démentir","en":"to deny","example":"Le porte-parole a démenti la rumeur."},{"fr":"l''ellipse (f.)","en":"ellipsis","example":"« Incendie à Kano : trois blessés » est une ellipse."}],"grammar":{"topic":"Ellipse, style nominal et conditionnel de prudence","explanation":"La presse condense l''information :\n• Titres elliptiques, sans verbe conjugué : « Grève des enseignants : les écoles fermées lundi ».\n• Nominalisation : « annonce », « hausse », « report ».\n• Conditionnel journalistique pour une information non confirmée : « Le suspect aurait quitté le pays. »\n• Discours rapporté varié : selon, d''après, de source policière, a-t-il affirmé (inversion en incise).\n• Apposition : « Le maire, élu en 2023, a déclaré… »\nL''éditorial, lui, peut employer la première personne, l''ironie et les questions rhétoriques.","examples":["Inondations à Abidjan : au moins douze morts.","Le ministre aurait remis sa démission, selon plusieurs sources.","« Nous ne céderons pas », a martelé la présidente.","Arrivé en tête, le candidat sortant a salué « une victoire du peuple »."]},"text":{"title":"Article","body":"CRISE À LA COMPAGNIE NATIONALE : LE PDG SUR LE DÉPART ?\nLe président-directeur général de la compagnie aérienne nationale, nommé il y a à peine deux ans, aurait présenté sa démission hier soir, selon des sources proches du dossier. Le ministère des Transports a démenti « toute décision à ce stade ». Cette annonce intervient alors que la compagnie, lourdement endettée, a annulé plus de trois cents vols en un mois. « Nous traversons une période difficile, mais l''entreprise n''est pas en faillite », a assuré un porte-parole.","questions":[{"id":"tq1","question":"Pourquoi l''article emploie-t-il « aurait présenté » ?","options":["par politesse","parce que c''est une hypothèse impossible","parce que l''action est future","parce que l''information n''est pas confirmée"],"answer":"parce que l''information n''est pas confirmée","explanation":""},{"id":"tq2","question":"Quelle est la réaction du ministère ?","options":["Il dément qu''une décision soit prise.","Il annonce la faillite.","Il confirme la démission.","Il refuse de commenter."],"answer":"Il dément qu''une décision soit prise.","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"Pour une information non confirmée, un journaliste écrira :","options":["Le suspect fuira à l''étranger.","Le suspect fuyait à l''étranger.","Le suspect aurait fui à l''étranger.","Le suspect a fui à l''étranger."],"answer":"Le suspect aurait fui à l''étranger.","accepted":[],"explanation":"Conditionnel de prudence.","tag":"journalistic-style","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"Titre de presse correct :","options":["Les prix augmentent et les ménages sont inquiets parce que","Je pense que les prix augmentent","Hausse des prix : les ménages inquiets","Ils disent que les prix vont augmenter"],"answer":"Hausse des prix : les ménages inquiets","accepted":[],"explanation":"Ellipse et style nominal.","tag":"journalistic-style","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"« Nous gagnerons », a-t-___ déclaré. (il)","options":[],"answer":"il","accepted":[],"explanation":"Inversion en incise : a-t-il déclaré.","tag":"journalistic-style","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["ministre","le","démissionné","aurait","nos","informations","Selon"],"answer":"Selon nos informations le ministre aurait démissionné","accepted":[],"explanation":"Source + conditionnel journalistique.","tag":"journalistic-style","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"The fire is said to have caused major damage.\"","options":[],"answer":"L''incendie aurait causé d''importants dégâts.","accepted":["L''incendie aurait provoqué d''importants dégâts."],"explanation":"Conditionnel passé de prudence.","tag":"journalistic-style","id":"ex5"}],"writing_prompt":"Rédigez une brève de presse (titre + chapeau + 80 mots) sur un événement imaginaire, avec ellipse, conditionnel journalistique et discours rapporté.","writing_model":"PANNE GÉANTE À LAGOS : LA VILLE PLONGÉE DANS LE NOIR\nUne coupure d''électricité a touché hier soir plus de deux millions d''habitants.\nSelon la compagnie d''électricité, la panne aurait été provoquée par un incendie dans une sous-station. « Le courant sera rétabli d''ici demain matin », a assuré son directeur. Plusieurs hôpitaux ont dû recourir à leurs générateurs. Des commerçants dénoncent « une situation intolérable », la troisième panne de ce type depuis janvier.","writing_checklist":["titre elliptique","conditionnel journalistique","citations avec inversion en incise"],"email_snippet":{"word_of_day":{"fr":"le chapeau","en":"the standfirst / lead","example":"Le chapeau résume l''article."},"mini_question":{"prompt":"Pour une information non confirmée, un journaliste écrira :","options":["Le suspect fuira à l''étranger.","Le suspect fuyait à l''étranger.","Le suspect aurait fui à l''étranger.","Le suspect a fui à l''étranger."],"answer":"Le suspect aurait fui à l''étranger."}}}'::jsonb, 'approved', 'curriculum'),
  ('C2', 5, 'Tournures littéraires', '{"level":"C2","seq":5,"theme":"Tournures littéraires","vocabulary":[{"fr":"point (= pas, littéraire)","en":"not (literary)","example":"Je ne te hais point."},{"fr":"guère","en":"hardly","example":"Il n''en reste guère."},{"fr":"nul / nulle","en":"no one / no","example":"Nul n''est censé ignorer la loi."},{"fr":"naguère","en":"not long ago","example":"Ce quartier, naguère animé, est désert."},{"fr":"d''aucuns","en":"some people","example":"D''aucuns prétendent le contraire."},{"fr":"ne… que","en":"only","example":"Il n''a que vingt ans."},{"fr":"sitôt","en":"as soon as","example":"Sitôt arrivé, il se mit au travail."},{"fr":"force est de constater","en":"one is forced to admit","example":"Force est de constater que l''échec est total."}],"grammar":{"topic":"Négations et tournures du registre littéraire","explanation":"• Négations soutenues : ne… point (pas), ne… guère (presque pas), ne… nullement, nul ne / nulle part, ne seul (sans pas) avec cesser, oser, pouvoir, savoir : « Il ne cesse de pleuvoir », « Je n''ose le dire ».\n• Tournures figées : force est de constater que, il n''est que de voir, point n''est besoin de, d''aucuns, naguère, sitôt + participe.\n• Antéposition de l''adjectif ou du complément pour l''effet : « De cette ville, il ne reste rien. »\nCes tournures donnent de l''élégance, mais leur accumulation devient affectée.","examples":["Point n''est besoin d''insister.","Il ne saurait être question de céder.","Nul ne sait ce qu''il est devenu.","Sitôt la nuit tombée, les rues se vidèrent."]},"text":{"title":"Éloge d''un vieux quartier","body":"Ce quartier, naguère le cœur battant de la ville, n''est guère plus qu''un souvenir. D''aucuns y voient le prix du progrès ; force est de constater pourtant que nul n''a su remplacer ce qui faisait son charme. Point n''est besoin d''être nostalgique pour regretter les cours ombragées et les ateliers d''artisans. Sitôt les bulldozers partis, les tours de verre ont surgi, et l''on n''ose imaginer ce qu''en penseraient les anciens.","questions":[{"id":"tq1","question":"Que signifie « n''est guère plus qu''un souvenir » ?","options":["est un beau souvenir","est devenu plus important","n''est plus du tout un souvenir","n''est presque plus qu''un souvenir"],"answer":"n''est presque plus qu''un souvenir","explanation":""},{"id":"tq2","question":"Quel est le ton du texte ?","options":["neutre et technique","enthousiaste pour le progrès","humoristique","nostalgique et critique envers les transformations"],"answer":"nostalgique et critique envers les transformations","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"« Il ne cesse de travailler » signifie :","options":["Il refuse de travailler.","Il travaille peu.","Il ne travaille plus.","Il travaille sans arrêt."],"answer":"Il travaille sans arrêt.","accepted":[],"explanation":"ne seul avec cesser : pas de valeur de « pas ».","tag":"literary-negation","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"« Point n''est besoin d''insister » signifie :","options":["Il faut insister sur ce point.","Il faut insister un peu.","Il n''est pas nécessaire d''insister.","Il est besoin d''un point."],"answer":"Il n''est pas nécessaire d''insister.","accepted":[],"explanation":"point = pas (littéraire), inversion figée.","tag":"literary-negation","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"___ n''est censé ignorer la loi. (no one)","options":[],"answer":"Nul","accepted":["nul"],"explanation":"nul ne = personne ne (soutenu).","tag":"literary-negation","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["Sitôt","foule","dispersa","nouvelle","se","la","connue","la"],"answer":"Sitôt la nouvelle connue la foule se dispersa","accepted":[],"explanation":"sitôt + participe : dès que.","tag":"literary-style","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"Some people claim the opposite. (literary)\"","options":[],"answer":"D''aucuns prétendent le contraire.","accepted":["Certains prétendent le contraire."],"explanation":"d''aucuns = certains (soutenu).","tag":"literary-style","id":"ex5"}],"writing_prompt":"Rédigez un paragraphe de 100 mots dans un registre littéraire soutenu sur un lieu disparu ou transformé, avec au moins quatre tournures étudiées.","writing_model":"De la maison de mon enfance, il ne reste guère que le manguier. Naguère, la cour résonnait des rires de mes cousins ; nul aujourd''hui ne s''y attarde. D''aucuns diront que les souvenirs embellissent tout. Force est de constater, pourtant, que je n''ose plus y retourner. Sitôt le portail franchi, une tristesse sourde m''envahit, et point n''est besoin de mots pour la dire.","writing_checklist":["négations soutenues (guère, nul, n''ose)","tournures figées (force est de constater, point n''est besoin)","registre homogène et non affecté"],"email_snippet":{"word_of_day":{"fr":"point (= pas, littéraire)","en":"not (literary)","example":"Je ne te hais point."},"mini_question":{"prompt":"« Il ne cesse de travailler » signifie :","options":["Il refuse de travailler.","Il travaille peu.","Il ne travaille plus.","Il travaille sans arrêt."],"answer":"Il travaille sans arrêt."}}}'::jsonb, 'approved', 'curriculum'),
  ('C2', 6, 'Variétés du français', '{"level":"C2","seq":6,"theme":"Variétés du français","vocabulary":[{"fr":"la francophonie","en":"the French-speaking world","example":"La francophonie compte plus de 300 millions de locuteurs."},{"fr":"un québécisme","en":"a Quebec expression","example":"« Magasiner » est un québécisme."},{"fr":"un belgicisme","en":"a Belgian expression","example":"« Septante » est un belgicisme."},{"fr":"un africanisme","en":"an African French expression","example":"« Essencerie » est un africanisme sénégalais."},{"fr":"le courriel","en":"e-mail (recommended term)","example":"Envoyez-moi un courriel."},{"fr":"un anglicisme","en":"an anglicism","example":"« Faire du shopping » est un anglicisme."},{"fr":"un néologisme","en":"a neologism","example":"« Divulgâcher » est un néologisme pour « spoiler »."},{"fr":"la norme","en":"the standard / norm","example":"La norme varie selon les pays."}],"grammar":{"topic":"Le français dans le monde : variation et norme","explanation":"Le français n''est pas une langue uniforme : il varie selon les régions (variation diatopique).\n• Belgique / Suisse : septante (70), nonante (90), huitante (80, en Suisse romande) ; déjeuner / dîner / souper pour les trois repas.\n• Québec : magasiner (faire les courses), char (voiture), courriel, fin de semaine, « c''est le fun ».\n• Afrique : essencerie (station-service, Sénégal), un maquis (petit restaurant, Côte d''Ivoire), droit (réserve de salaire, Cameroun), « on va faire comment ? ».\n• Néologismes et recommandations officielles : courriel, divulgâcher, mot-dièse (hashtag), infox (fake news).\nLa « norme » est donc plurielle ; un locuteur C2 sait reconnaître ces variétés sans les juger.","examples":["À Bruxelles, on dîne à midi et on soupe le soir.","À Montréal : « Je vais magasiner en fin de semaine. »","À Abidjan : « On se retrouve au maquis ce soir ? »","« Ne divulgâche pas la fin du film ! »"]},"text":{"title":"Un français, des français","body":"Lors d''une conférence à Genève, des étudiants venus de Dakar, de Montréal et de Liège ont comparé leurs façons de parler. Aminata expliquait qu''elle faisait le plein à l''essencerie ; Félix, de Québec, racontait qu''il magasinait chaque fin de semaine ; et Louise, la Liégeoise, invitait tout le monde à dîner… à midi. Loin de s''en amuser, la professeure a rappelé que ces différences enrichissent la langue : le français appartient désormais davantage à l''Afrique qu''à la France, puisque la majorité de ses locuteurs y vivent.","questions":[{"id":"tq1","question":"Que signifie « magasiner » au Québec ?","options":["travailler dans un magasin","faire des courses / du shopping","voler dans un magasin","fermer un magasin"],"answer":"faire des courses / du shopping","explanation":""},{"id":"tq2","question":"Selon la professeure, où vit la majorité des francophones ?","options":["en Afrique","au Canada","en France","en Belgique"],"answer":"en Afrique","explanation":""}]},"exercises":[{"type":"mcq","skill":"vocabulary","prompt":"En Belgique, 90 se dit :","options":["nonante","huitante","neuvante","quatre-vingt-dix"],"answer":"nonante","accepted":[],"explanation":"Belgique et Suisse : septante, nonante.","tag":"francophonie","id":"ex1"},{"type":"mcq","skill":"vocabulary","prompt":"Terme recommandé en français pour « fake news » :","options":["fausse nouvelle-news","pseudoinfo","faknews","infox"],"answer":"infox","accepted":[],"explanation":"Recommandation officielle : infox.","tag":"neologisms","id":"ex2"},{"type":"fill_blank","skill":"vocabulary","prompt":"Au Sénégal, on fait le plein d''essence à l''___.","options":[],"answer":"essencerie","accepted":[],"explanation":"Africanisme : essencerie = station-service.","tag":"francophonie","id":"ex3"},{"type":"reorder","skill":"vocabulary","prompt":"Put the words in the right order.","options":["on","courriel","un","Québec","Au","envoie"],"answer":"Au Québec on envoie un courriel","accepted":[],"explanation":"courriel = e-mail.","tag":"francophonie","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"Don''t spoil the end of the series!\"","options":[],"answer":"Ne divulgâche pas la fin de la série !","accepted":["Ne me divulgâche pas la fin de la série !","Ne spoile pas la fin de la série !"],"explanation":"Néologisme recommandé : divulgâcher.","tag":"neologisms","id":"ex5"}],"writing_prompt":"Le français parlé dans votre pays (ou que vous entendez autour de vous) a-t-il des particularités ? Présentez-en quelques-unes en 120 mots et réfléchissez à la notion de « bon français ».","writing_model":"Au Nigeria, le français est surtout une langue apprise, mais il est influencé par nos voisins du Bénin et du Cameroun. On entend des expressions comme « on va faire comment ? » ou « il est allé au maquis ». Certains enseignants les jugent incorrectes ; pourtant, elles sont parfaitement comprises dans toute l''Afrique de l''Ouest. À mon sens, le « bon français » n''est pas celui de Paris, mais celui qui est adapté à la situation. Un locuteur compétent sait passer d''une variété à l''autre selon son interlocuteur.","writing_checklist":["exemples précis de variation","réflexion nuancée sur la norme","registre soutenu"],"email_snippet":{"word_of_day":{"fr":"la francophonie","en":"the French-speaking world","example":"La francophonie compte plus de 300 millions de locuteurs."},"mini_question":{"prompt":"En Belgique, 90 se dit :","options":["nonante","huitante","neuvante","quatre-vingt-dix"],"answer":"nonante"}}}'::jsonb, 'approved', 'curriculum'),
  ('C2', 7, 'Locutions latines et savantes', '{"level":"C2","seq":7,"theme":"Locutions latines et savantes","vocabulary":[{"fr":"a priori","en":"at first sight / in principle","example":"A priori, rien ne s''y oppose."},{"fr":"a posteriori","en":"after the fact","example":"On l''a compris a posteriori."},{"fr":"de facto","en":"in fact / in practice","example":"Il est de facto le chef."},{"fr":"in extremis","en":"at the last moment","example":"Il a été sauvé in extremis."},{"fr":"sine qua non","en":"essential condition","example":"C''est une condition sine qua non."},{"fr":"ad hoc","en":"for this purpose","example":"Une commission ad hoc a été créée."},{"fr":"mea culpa","en":"admission of guilt","example":"Le ministre a fait son mea culpa."},{"fr":"statu quo","en":"the status quo","example":"Ils préfèrent le statu quo."}],"grammar":{"topic":"Employer les locutions latines","explanation":"Le français soutenu emprunte de nombreuses locutions latines. Elles sont invariables et s''écrivent aujourd''hui sans accent en principe (a priori, a posteriori), bien que les rectifications de 1990 autorisent « à priori ».\nAttention aux erreurs fréquentes :\n• « au jour d''aujourd''hui » est un pléonasme ;\n• « statu quo » (et non « statu-quo » ni « status quo ») ;\n• « in extremis » = au dernier moment, pas « extrêmement » ;\n• « a priori » ne signifie pas « probablement » mais « au premier abord, avant examen ».\nN''en abusez pas : une ou deux par paragraphe suffisent.","examples":["A priori, la proposition semble raisonnable.","Le but a été marqué in extremis.","La maîtrise du français est une condition sine qua non.","Faute d''accord, le statu quo est maintenu."]},"text":{"title":"Négociations","body":"Après trois jours de discussions, un accord a été trouvé in extremis entre le syndicat et la direction. A priori, rien ne laissait présager une telle issue : chacun campait sur ses positions et le statu quo semblait inévitable. La création d''une commission ad hoc, chargée de suivre l''application de l''accord, était pour le syndicat une condition sine qua non. A posteriori, plusieurs observateurs estiment que le mea culpa du directeur a débloqué la situation.","questions":[{"id":"tq1","question":"Quand l''accord a-t-il été trouvé ?","options":["un mois plus tard","au dernier moment","il n''y a pas eu d''accord","dès le premier jour"],"answer":"au dernier moment","explanation":""},{"id":"tq2","question":"Qu''est-ce qui aurait débloqué la situation ?","options":["le mea culpa du directeur","une grève","l''intervention du ministre","la commission ad hoc"],"answer":"le mea culpa du directeur","explanation":""}]},"exercises":[{"type":"mcq","skill":"vocabulary","prompt":"« Il a été sauvé in extremis » signifie :","options":["par erreur","de façon extrême","très facilement","au dernier moment"],"answer":"au dernier moment","accepted":[],"explanation":"in extremis = au dernier moment.","tag":"latin-phrases","id":"ex1"},{"type":"mcq","skill":"vocabulary","prompt":"Graphie correcte :","options":["le statu quo","le statu-quo","le status quo","le statut quo"],"answer":"le statu quo","accepted":[],"explanation":"Locution latine invariable : statu quo.","tag":"latin-phrases","id":"ex2"},{"type":"fill_blank","skill":"vocabulary","prompt":"Parler français est une condition ___ qua non pour ce poste.","options":[],"answer":"sine","accepted":[],"explanation":"sine qua non = indispensable.","tag":"latin-phrases","id":"ex3"},{"type":"reorder","skill":"vocabulary","prompt":"Put the words in the right order.","options":["A","réalisable","semble","projet","le","priori"],"answer":"A priori le projet semble réalisable","accepted":[],"explanation":"a priori = au premier abord.","tag":"latin-phrases","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"The president admitted his mistake publicly.\"","options":[],"answer":"Le président a fait son mea culpa publiquement.","accepted":["Le président a publiquement fait son mea culpa.","Le président a reconnu publiquement son erreur."],"explanation":"faire son mea culpa = reconnaître sa faute.","tag":"latin-phrases","id":"ex5"}],"writing_prompt":"Rédigez un court compte rendu de réunion (100 mots) en utilisant à bon escient au moins quatre locutions latines.","writing_model":"La réunion du 12 mai avait pour objet le budget de la formation. A priori, les positions semblaient inconciliables : la direction souhaitait le statu quo, tandis que les équipes réclamaient une hausse de 20 %. Une solution a été trouvée in extremis : un groupe de travail ad hoc proposera d''ici juin une répartition équitable. Sa création était une condition sine qua non pour les représentants du personnel.","writing_checklist":["au moins quatre locutions latines","sens exact de chaque locution","graphies correctes et invariables"],"email_snippet":{"word_of_day":{"fr":"a priori","en":"at first sight / in principle","example":"A priori, rien ne s''y oppose."},"mini_question":{"prompt":"« Il a été sauvé in extremis » signifie :","options":["par erreur","de façon extrême","très facilement","au dernier moment"],"answer":"au dernier moment"}}}'::jsonb, 'approved', 'curriculum'),
  ('C2', 8, 'Ponctuation et rythme', '{"level":"C2","seq":8,"theme":"Ponctuation et rythme","vocabulary":[{"fr":"le point-virgule","en":"semicolon","example":"Il pleuvait ; nous sommes restés."},{"fr":"les deux-points","en":"colon","example":"Il n''avait qu''un rêve : partir."},{"fr":"les points de suspension","en":"ellipsis (…)","example":"Et puis… plus rien."},{"fr":"les guillemets (m.)","en":"quotation marks « »","example":"Il a dit : « Je reviendrai. »"},{"fr":"le tiret","en":"dash","example":"Ma sœur — qui vit à Paris — arrive demain."},{"fr":"l''incise (f.)","en":"parenthetical clause","example":"« Viens », dit-elle."},{"fr":"la cadence","en":"rhythm / cadence","example":"La phrase a une belle cadence."},{"fr":"la période","en":"periodic sentence","example":"Bossuet maîtrisait l''art de la période."}],"grammar":{"topic":"La ponctuation française et le rythme de la phrase","explanation":"Particularités typographiques françaises : espace insécable avant ; : ! ? et à l''intérieur des guillemets « ».\n• Point-virgule : sépare deux propositions liées par le sens.\n• Deux-points : annonce une explication, une conséquence, une énumération ou une citation.\n• Tiret / parenthèses : insertion d''un commentaire.\n• Incise avec inversion : « Je pars, dit-il. »\nLe rythme naît de la longueur et de l''équilibre des segments : rythme binaire (« Il hésita, puis renonça »), ternaire (« Je suis venu, j''ai vu, j''ai vaincu »), phrase brève après une phrase longue pour créer un effet de chute.","examples":["Elle avait tout préparé : les valises, les billets, les adieux.","Il voulait parler ; il n''osa pas.","Mon voisin — un homme charmant — m''a aidé.","« Je ne viendrai pas », répondit-elle sèchement."]},"text":{"title":"Analyse d''un paragraphe","body":"« Il marcha longtemps, sous la pluie, entre les maisons aveugles et les arbres nus ; il marcha sans but, sans pensée, sans espoir. Puis il s''arrêta. » Dans ce passage, l''auteur construit une longue phrase au rythme ternaire — sans but, sans pensée, sans espoir — qui mime la marche épuisante du personnage. Le point-virgule relie deux mouvements de la même errance. La phrase brève qui suit produit un effet de rupture : l''arrêt est soudain, presque brutal.","questions":[{"id":"tq1","question":"Quel effet produit la phrase « Puis il s''arrêta. » ?","options":["un effet de rupture brutale","une accélération du rythme","un effet comique","une transition vers un dialogue"],"answer":"un effet de rupture brutale","explanation":""},{"id":"tq2","question":"Quel rythme l''auteur emploie-t-il dans « sans but, sans pensée, sans espoir » ?","options":["binaire","quaternaire","irrégulier","ternaire"],"answer":"ternaire","explanation":""}]},"exercises":[{"type":"mcq","skill":"vocabulary","prompt":"Signe annonçant une explication ou une énumération :","options":["le point-virgule","les deux-points","le tiret","les points de suspension"],"answer":"les deux-points","accepted":[],"explanation":"Les deux-points annoncent ce qui suit.","tag":"punctuation","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"Incise correcte :","options":["« Je pars », dit il.","« Je pars », il dit.","« Je pars », dit-il.","« Je pars » il a dit."],"answer":"« Je pars », dit-il.","accepted":[],"explanation":"Incise avec inversion et trait d''union.","tag":"punctuation","id":"ex2"},{"type":"mcq","skill":"grammar","prompt":"Quel signe convient ? « Il voulait parler ___ il n''osa pas. »","options":["le tiret","le point d''interrogation","le point-virgule","les guillemets"],"answer":"le point-virgule","accepted":[],"explanation":"Le point-virgule relie deux propositions liées par le sens.","tag":"punctuation","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["j''ai","suis","vaincu","venu","j''ai","vu","Je"],"answer":"Je suis venu j''ai vu j''ai vaincu","accepted":[],"explanation":"Rythme ternaire célèbre.","tag":"rhythm","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"She had only one dream: to leave.\"","options":[],"answer":"Elle n''avait qu''un rêve : partir.","accepted":["Elle n''avait qu''un seul rêve : partir."],"explanation":"Deux-points précédés d''une espace en français.","tag":"punctuation","id":"ex5"}],"writing_prompt":"Écrivez un paragraphe descriptif (100 mots) qui joue sur le rythme : une longue phrase ternaire, un point-virgule, des deux-points, et une phrase brève finale.","writing_model":"Le marché s''éveillait lentement : les vendeuses déballaient leurs étoffes, les porteurs criaient, les enfants couraient entre les étals. Il y avait là toutes les couleurs, toutes les odeurs, toutes les langues de la ville ; on y venait moins pour acheter que pour vivre. Je m''avançais au milieu de cette foule — étourdi, émerveillé — quand une voix appela mon nom. Je me retournai. Personne.","writing_checklist":["rythme ternaire","point-virgule et deux-points bien employés","phrase brève finale à effet de chute"],"email_snippet":{"word_of_day":{"fr":"le point-virgule","en":"semicolon","example":"Il pleuvait ; nous sommes restés."},"mini_question":{"prompt":"Signe annonçant une explication ou une énumération :","options":["le point-virgule","les deux-points","le tiret","les points de suspension"],"answer":"les deux-points"}}}'::jsonb, 'approved', 'curriculum'),
  ('C2', 9, 'Les paronymes', '{"level":"C2","seq":9,"theme":"Les paronymes","vocabulary":[{"fr":"affliger / infliger","en":"to distress / to inflict","example":"Cette nouvelle m''afflige ; il lui a infligé une amende."},{"fr":"éminent / imminent","en":"eminent / imminent","example":"Un éminent professeur ; un danger imminent."},{"fr":"conjecture / conjoncture","en":"guess / circumstances","example":"Simple conjecture ; la conjoncture économique."},{"fr":"prodige / prodigue","en":"prodigy / lavish","example":"Un enfant prodige ; un fils prodigue."},{"fr":"acception / acceptation","en":"sense of a word / acceptance","example":"Dans toutes les acceptions du terme."},{"fr":"perpétrer / perpétuer","en":"to commit (a crime) / to perpetuate","example":"Perpétrer un crime ; perpétuer une tradition."},{"fr":"évoquer / invoquer","en":"to mention / to call upon","example":"Évoquer un souvenir ; invoquer une loi."},{"fr":"effraction / infraction","en":"break-in / offence","example":"Vol avec effraction ; une infraction au code."}],"grammar":{"topic":"Les paronymes","explanation":"Les paronymes sont des mots de forme proche mais de sens différent. Leur confusion est fréquente même chez les locuteurs natifs, et elle est sanctionnée dans les examens de niveau C2.\nStratégies : rattacher chaque mot à sa famille (éminent → éminence ; imminent → imminence), mémoriser une collocation type (perpétrer un crime, perpétuer une tradition), vérifier dans un dictionnaire en cas de doute.\nAutres paires utiles : allocation / allocution ; collision / collusion ; inclinaison / inclination ; percepteur / précepteur ; recouvrer / recouvrir.","examples":["Le président a prononcé une allocution télévisée.","Il a recouvré la vue après l''opération.","La conjoncture actuelle est défavorable.","On soupçonne une collusion entre les deux entreprises."]},"text":{"title":"Chronique judiciaire","body":"L''audience s''est ouverte dans une atmosphère tendue. L''accusé, soupçonné d''avoir perpétré un cambriolage avec effraction, a invoqué un alibi que l''accusation a qualifié de pure conjecture. L''avocat de la défense, éminent pénaliste, a évoqué la conjoncture sociale difficile du quartier. Le tribunal a finalement infligé une peine de deux ans avec sursis, une décision qui a manifestement affligé la famille de la victime.","questions":[{"id":"tq1","question":"De quoi l''accusé est-il soupçonné ?","options":["d''une fraude fiscale","d''un cambriolage avec effraction","d''une agression","d''une infraction au code de la route"],"answer":"d''un cambriolage avec effraction","explanation":""},{"id":"tq2","question":"Comment a réagi la famille de la victime ?","options":["Elle a été affligée par la décision.","Elle a été soulagée.","Elle a fait appel immédiatement.","Elle n''était pas présente."],"answer":"Elle a été affligée par la décision.","explanation":""}]},"exercises":[{"type":"mcq","skill":"vocabulary","prompt":"Le juge lui a ___ une lourde amende.","options":["inflogé","affligeait","infligé","affligé"],"answer":"infligé","accepted":[],"explanation":"infliger une peine / une amende.","tag":"paronyms","id":"ex1"},{"type":"mcq","skill":"vocabulary","prompt":"Un orage est ___ : rentrez vite !","options":["imminent","émanant","éminent","immanent"],"answer":"imminent","accepted":[],"explanation":"imminent = sur le point de se produire.","tag":"paronyms","id":"ex2"},{"type":"fill_blank","skill":"vocabulary","prompt":"Après une longue maladie, il a ___ la santé. (retrouvé)","options":[],"answer":"recouvré","accepted":[],"explanation":"recouvrer = retrouver ; recouvrir = couvrir.","tag":"paronyms","id":"ex3"},{"type":"reorder","skill":"vocabulary","prompt":"Put the words in the right order.","options":["tradition","ancienne","village","Ce","une","perpétue"],"answer":"Ce village perpétue une tradition ancienne","accepted":[],"explanation":"perpétuer une tradition.","tag":"paronyms","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"The president gave a televised address.\"","options":[],"answer":"Le président a prononcé une allocution télévisée.","accepted":["Le président a fait une allocution télévisée."],"explanation":"allocution = discours ; allocation = somme versée.","tag":"paronyms","id":"ex5"}],"writing_prompt":"Rédigez un court fait divers (100 mots) employant correctement au moins quatre paronymes de la leçon.","writing_model":"Un cambriolage avec effraction a été perpétré cette nuit dans une bijouterie du centre-ville. Selon la police, les voleurs auraient profité d''une panne d''électricité imminente, annoncée la veille. Le propriétaire, encore affligé, a évoqué devant les journalistes un « travail de professionnels ». Les enquêteurs refusent pour l''instant toute conjecture. S''ils sont arrêtés, les auteurs se verront infliger une peine pouvant aller jusqu''à dix ans de prison.","writing_checklist":["au moins quatre paronymes employés au bon sens","style de fait divers","conditionnel journalistique si pertinent"],"email_snippet":{"word_of_day":{"fr":"affliger / infliger","en":"to distress / to inflict","example":"Cette nouvelle m''afflige ; il lui a infligé une amende."},"mini_question":{"prompt":"Le juge lui a ___ une lourde amende.","options":["inflogé","affligeait","infligé","affligé"],"answer":"infligé"}}}'::jsonb, 'approved', 'curriculum'),
  ('C2', 10, 'Le style indirect libre', '{"level":"C2","seq":10,"theme":"Le style indirect libre","vocabulary":[{"fr":"le narrateur","en":"the narrator","example":"Le narrateur reste extérieur à l''histoire."},{"fr":"le point de vue","en":"the point of view","example":"Le récit adopte le point de vue du héros."},{"fr":"la focalisation interne","en":"internal focalisation","example":"La focalisation interne révèle ses pensées."},{"fr":"le monologue intérieur","en":"interior monologue","example":"Le roman s''ouvre sur un monologue intérieur."},{"fr":"discours direct / indirect","en":"direct / indirect speech","example":"Le discours direct est entre guillemets."},{"fr":"une ambiguïté","en":"an ambiguity","example":"Cette phrase crée une ambiguïté."},{"fr":"l''ironie (f.)","en":"irony","example":"L''ironie du narrateur est mordante."},{"fr":"se fondre","en":"to merge","example":"La voix du personnage se fond dans celle du narrateur."}],"grammar":{"topic":"Le discours indirect libre","explanation":"Le discours indirect libre mêle la voix du narrateur et celle du personnage, sans verbe introducteur ni guillemets.\nIl garde les temps et les pronoms du discours indirect (3e personne, imparfait, conditionnel), mais conserve la spontanéité du discours direct (exclamations, questions, mots familiers).\n• Direct : Il se dit : « Je ne partirai jamais d''ici ! »\n• Indirect : Il se dit qu''il ne partirait jamais de là.\n• Indirect libre : Il regarda la mer. Partir ? Jamais il ne partirait d''ici !\nTrès employé par Flaubert, Zola ou Maryse Condé, il crée une proximité avec le personnage et peut servir l''ironie.","examples":["Elle relut la lettre. Comment avait-il osé ? Après tout ce qu''elle avait fait pour lui !","Il hésitait. Et si on le reconnaissait ? Tant pis, il fallait y aller.","Le patron se frotta les mains : la journée serait excellente.","Elle soupira. Encore un dimanche à attendre."]},"text":{"title":"Le retour","body":"Adama descendit du car devant la place du village. Rien n''avait changé : le même baobab, la même boutique, les mêmes enfants qui couraient pieds nus. Dix ans ! Dix ans qu''il était parti, persuadé qu''il reviendrait riche et respecté. Et il rentrait avec une valise et des dettes. Que dirait sa mère ? Elle le serrerait dans ses bras, bien sûr, elle ne poserait pas de questions. C''était pire.","questions":[{"id":"tq1","question":"Quelle technique l''auteur emploie-t-il dans « Que dirait sa mère ? » ?","options":["le discours direct","le discours indirect libre","le discours indirect","un dialogue"],"answer":"le discours indirect libre","explanation":""},{"id":"tq2","question":"Pourquoi Adama pense-t-il que « c''était pire » ?","options":["parce que le silence de sa mère le mettrait face à son échec","parce que sa mère serait en colère","parce que le village avait changé","parce qu''il avait perdu sa valise"],"answer":"parce que le silence de sa mère le mettrait face à son échec","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"Quelle phrase est au discours indirect libre ?","options":["« Pourquoi as-tu accepté ? » demanda-t-il.","Elle ferma les yeux. Pourquoi avait-elle accepté ?","Elle se dit : « Pourquoi ai-je accepté ? »","Elle se demanda pourquoi elle avait accepté."],"answer":"Elle ferma les yeux. Pourquoi avait-elle accepté ?","accepted":[],"explanation":"Question du personnage sans verbe introducteur, à la 3e personne et au passé.","tag":"free-indirect-speech","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"Le discours indirect libre se caractérise par :","options":["le présent de l''indicatif obligatoire","l''absence de verbe introducteur et de guillemets","l''emploi de guillemets","l''emploi obligatoire de la 1re personne"],"answer":"l''absence de verbe introducteur et de guillemets","accepted":[],"explanation":"Fusion des voix narrateur / personnage.","tag":"free-indirect-speech","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"Direct : « Je partirai demain. » → Indirect libre : Il partirait ___. ","options":[],"answer":"le lendemain","accepted":[],"explanation":"Transposition du temps et des repères : demain → le lendemain.","tag":"free-indirect-speech","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["perdu","un","jour","pluie.","Encore","Il","regarda","la"],"answer":"Il regarda la pluie. Encore un jour perdu","accepted":[],"explanation":"Pensée du personnage intégrée au récit.","tag":"free-indirect-speech","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"She looked at the letter. How could he have forgotten?\"","options":[],"answer":"Elle regarda la lettre. Comment avait-il pu oublier ?","accepted":["Elle regarda la lettre. Comment avait-il pu l''oublier ?"],"explanation":"Question du personnage au plus-que-parfait, sans guillemets.","tag":"free-indirect-speech","id":"ex5"}],"writing_prompt":"Écrivez une courte scène (120 mots) où un personnage attend un résultat important, en utilisant le discours indirect libre pour révéler ses pensées.","writing_model":"Ifeoma fixait l''écran de son téléphone. Les résultats devaient tomber à midi ; il était midi cinq. Et si le site était en panne ? Ou pire, si son nom n''apparaissait nulle part ? Trois ans de travail, de nuits blanches, de sacrifices ! Sa mère, elle, priait dans la pièce voisine. Ifeoma rafraîchit la page une fois, deux fois. Enfin, la liste. Elle parcourut les noms d''un doigt tremblant. Okafor… Okeke… Okonkwo. Admise. Elle était admise. Elle resta immobile, incapable de crier.","writing_checklist":["pensées du personnage sans verbe introducteur ni guillemets","3e personne et temps du passé","exclamations ou questions expressives"],"email_snippet":{"word_of_day":{"fr":"le narrateur","en":"the narrator","example":"Le narrateur reste extérieur à l''histoire."},"mini_question":{"prompt":"Quelle phrase est au discours indirect libre ?","options":["« Pourquoi as-tu accepté ? » demanda-t-il.","Elle ferma les yeux. Pourquoi avait-elle accepté ?","Elle se dit : « Pourquoi ai-je accepté ? »","Elle se demanda pourquoi elle avait accepté."],"answer":"Elle ferma les yeux. Pourquoi avait-elle accepté ?"}}}'::jsonb, 'approved', 'curriculum'),
  ('C2', 11, 'Les accords délicats', '{"level":"C2","seq":11,"theme":"Les accords délicats","vocabulary":[{"fr":"tout / toute / tous / toutes","en":"all / quite","example":"Elle est toute contente."},{"fr":"même","en":"same / even","example":"Les enfants eux-mêmes ont ri."},{"fr":"demi","en":"half","example":"Une demi-heure ; deux heures et demie."},{"fr":"quelque","en":"some / however","example":"Quelques amis ; quelque vingt personnes."},{"fr":"nu","en":"bare","example":"Nu-pieds ; les pieds nus."},{"fr":"possible","en":"possible","example":"Le moins d''erreurs possible."},{"fr":"excepté","en":"except","example":"Excepté les enfants, tous sont partis."},{"fr":"ci-joint","en":"attached","example":"Ci-joint les factures ; les factures ci-jointes."}],"grammar":{"topic":"Tout, même, demi, quelque et les adjectifs invariables","explanation":"• tout adverbe (= tout à fait) est invariable, SAUF devant un adjectif féminin commençant par une consonne ou un h aspiré : ils sont tout contents, elles sont tout étonnées, mais elle est toute petite.\n• même : adjectif, il s''accorde (les mêmes livres, eux-mêmes) ; adverbe (= aussi), il est invariable (même les enfants).\n• demi : invariable devant le nom avec trait d''union (une demi-heure) ; après le nom, accord en genre seulement (deux heures et demie).\n• quelque : adjectif = plusieurs (quelques amis) ; adverbe = environ, invariable (quelque cent personnes).\n• nu, ci-joint, excepté, passé : invariables placés avant le nom (nu-tête, ci-joint les documents), variables après (tête nue, les documents ci-joints).","examples":["Elles étaient tout émues.","Elle était toute honteuse.","Même les plus sceptiques ont applaudi.","Il a attendu une demi-heure, puis deux heures et demie."]},"text":{"title":"Correction d''un texte","body":"La correctrice relut le manuscrit avec attention. L''auteur avait écrit : « L''invitée, toute émue, arriva nu-pieds ; quelques cent personnes l''attendaient depuis une heure et demi. » Elle corrigea : « tout émue », car tout est ici adverbe devant un adjectif féminin commençant par une voyelle ; « quelque cent personnes », car quelque signifie environ ; et « une heure et demie », car demi s''accorde en genre après le nom. Nu-pieds, en revanche, était juste.","questions":[{"id":"tq1","question":"Pourquoi « tout émue » s''écrit-il sans e ?","options":["tout est adverbe devant un adjectif féminin commençant par une voyelle","c''est une erreur de la correctrice","parce que tout est un pronom","parce que émue est masculin"],"answer":"tout est adverbe devant un adjectif féminin commençant par une voyelle","explanation":""},{"id":"tq2","question":"Que signifie « quelque cent personnes » ?","options":["environ cent personnes","plusieurs centaines de personnes","moins de cent personnes","cent personnes exactement"],"answer":"environ cent personnes","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"Elle est ___ heureuse. (= très)","options":["tous","toutes","toute","tout"],"answer":"tout","accepted":[],"explanation":"tout adverbe devant un adjectif féminin à h muet → invariable.","tag":"tricky-agreement","id":"ex1"},{"type":"mcq","skill":"grammar","prompt":"Elle est restée ___ surprise.","options":["toutes","toute","tous","tout"],"answer":"toute","accepted":[],"explanation":"Devant un adjectif féminin commençant par une consonne → toute.","tag":"tricky-agreement","id":"ex2"},{"type":"fill_blank","skill":"grammar","prompt":"Il est arrivé à midi et ___. (demi)","options":[],"answer":"demi","accepted":[],"explanation":"midi est masculin → et demi.","tag":"tricky-agreement","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["trouver","demandés","Veuillez","ci-joint","les","documents"],"answer":"Veuillez trouver ci-joint les documents demandés","accepted":[],"explanation":"ci-joint en tête : invariable.","tag":"tricky-agreement","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"Even the teachers were surprised.\"","options":[],"answer":"Même les professeurs ont été surpris.","accepted":["Même les enseignants ont été surpris.","Les professeurs eux-mêmes ont été surpris."],"explanation":"même adverbe (= aussi) : invariable.","tag":"tricky-agreement","id":"ex5"}],"writing_prompt":"Rédigez un paragraphe de 100 mots (description d''une fête, d''un voyage…) contenant au moins six occurrences des mots tout, même, demi, quelque, nu, ci-joint, correctement accordés.","writing_model":"La fête a duré quelque cinq heures. Les invitées, tout émues, sont arrivées vers huit heures et demie ; certaines dansaient nu-pieds, d''autres gardaient les pieds nus sous leurs longues robes. Toutes les générations étaient présentes : même les grands-parents ont dansé ! Au bout d''une demi-heure, la musique est devenue toute différente. Vous trouverez ci-joint quelques photos ; les vidéos ci-jointes sont plus longues.","writing_checklist":["tout adverbe et adjectif correctement accordés","demi avant / après le nom","quelque (environ) vs quelques (plusieurs)"],"email_snippet":{"word_of_day":{"fr":"tout / toute / tous / toutes","en":"all / quite","example":"Elle est toute contente."},"mini_question":{"prompt":"Elle est ___ heureuse. (= très)","options":["tous","toutes","toute","tout"],"answer":"tout"}}}'::jsonb, 'approved', 'curriculum'),
  ('C2', 12, 'Rhétorique et éloquence', '{"level":"C2","seq":12,"theme":"Rhétorique et éloquence","vocabulary":[{"fr":"l''anaphore (f.)","en":"anaphora","example":"« Moi président… » est une anaphore célèbre."},{"fr":"la gradation","en":"climax / gradation","example":"« Va, cours, vole » est une gradation."},{"fr":"le chiasme","en":"chiasmus","example":"« Il faut manger pour vivre et non vivre pour manger. »"},{"fr":"la question rhétorique","en":"rhetorical question","example":"« Qui pourrait l''accepter ? »"},{"fr":"l''exorde (m.)","en":"the opening of a speech","example":"L''exorde doit capter l''attention."},{"fr":"la péroraison","en":"the peroration / conclusion","example":"La péroraison appelle à l''action."},{"fr":"convaincre / persuader","en":"to convince / to persuade","example":"Convaincre par la raison, persuader par l''émotion."},{"fr":"un orateur / une oratrice","en":"a speaker / orator","example":"C''est une oratrice remarquable."}],"grammar":{"topic":"Les procédés de l''éloquence","explanation":"Un discours s''organise traditionnellement en exorde (captiver), narration et argumentation, puis péroraison (émouvoir, appeler à agir).\nProcédés d''insistance et d''émotion :\n• anaphore : répétition en tête de phrase (« Nous ne renoncerons pas… Nous ne céderons pas… ») ;\n• gradation : termes d''intensité croissante ;\n• chiasme : structure croisée ABBA ;\n• question rhétorique : question qui n''attend pas de réponse ;\n• apostrophe : interpellation directe de l''auditoire ;\n• accumulation et rythme ternaire.\nConvaincre s''adresse à la raison (arguments, exemples) ; persuader s''adresse aux émotions.","examples":["« Je suis venu, j''ai vu, j''ai vaincu. » (rythme ternaire)","« Un pour tous, tous pour un. » (chiasme)","« Jusqu''à quand abuseras-tu de notre patience ? » (question rhétorique)","« Ce n''est pas un problème, c''est un drame, c''est une tragédie ! » (gradation)"]},"text":{"title":"Extrait d''un discours","body":"« Mesdames et messieurs, chers jeunes diplômés, regardez autour de vous. Regardez ces visages qui ont partagé vos doutes, vos nuits blanches, vos victoires. On vous dira que l''avenir est sombre. On vous dira que le monde n''a pas besoin de vous. On vous dira de vous taire. Mais qui, sinon vous, inventera les solutions de demain ? Ne demandez pas ce que ce pays peut faire pour vous : demandez-vous ce que vous pouvez faire pour lui. Osez, construisez, transformez ! »","questions":[{"id":"tq1","question":"Quel procédé repose sur la répétition de « On vous dira » ?","options":["l''euphémisme","le chiasme","l''anaphore","la litote"],"answer":"l''anaphore","explanation":""},{"id":"tq2","question":"« Osez, construisez, transformez ! » est :","options":["une question rhétorique","une antithèse","une gradation au rythme ternaire","un chiasme"],"answer":"une gradation au rythme ternaire","explanation":""}]},"exercises":[{"type":"mcq","skill":"grammar","prompt":"« Il faut manger pour vivre et non vivre pour manger » est :","options":["une anaphore","un chiasme","une gradation","une litote"],"answer":"un chiasme","accepted":[],"explanation":"Structure croisée ABBA.","tag":"rhetoric","id":"ex1"},{"type":"mcq","skill":"vocabulary","prompt":"Persuader, c''est surtout :","options":["citer des chiffres","toucher les émotions de l''auditoire","répéter les mêmes mots","démontrer par la logique seule"],"answer":"toucher les émotions de l''auditoire","accepted":[],"explanation":"Persuader : émotions ; convaincre : raison.","tag":"rhetoric","id":"ex2"},{"type":"fill_blank","skill":"vocabulary","prompt":"La conclusion d''un discours, qui appelle à l''action, s''appelle la ___.","options":[],"answer":"péroraison","accepted":["peroraison"],"explanation":"exorde (début) / péroraison (fin).","tag":"rhetoric","id":"ex3"},{"type":"reorder","skill":"grammar","prompt":"Put the words in the right order.","options":["à","telle","Qui","injustice","pourrait","indifférent","une","rester",""],"answer":"Qui pourrait rester indifférent à une telle injustice ","accepted":[],"explanation":"Question rhétorique.","tag":"rhetoric","id":"ex4"},{"type":"translation","skill":"vocabulary","prompt":"Translate into French: \"We will not give up, we will not yield, we will not fail.\"","options":[],"answer":"Nous n''abandonnerons pas, nous ne céderons pas, nous n''échouerons pas.","accepted":["Nous ne renoncerons pas, nous ne céderons pas, nous n''échouerons pas."],"explanation":"Anaphore et rythme ternaire.","tag":"rhetoric","id":"ex5"}],"writing_prompt":"Rédigez la péroraison (120 mots) d''un discours pour encourager les jeunes de votre ville à apprendre une nouvelle langue. Employez au moins une anaphore, une gradation, une question rhétorique et un chiasme.","writing_model":"Chers amis, apprendre une langue, c''est ouvrir une porte. Apprendre une langue, c''est tendre la main. Apprendre une langue, c''est refuser de rester enfermé dans un seul regard sur le monde. Qui parmi vous n''a jamais rêvé de comprendre une chanson, un film, un ami venu d''ailleurs ? Le français vous attend : il vous offrira des études, des voyages, des carrières, des amitiés pour la vie. N''oubliez jamais ceci : ce n''est pas la langue qui fait le voyageur, c''est le voyageur qui fait vivre la langue. Alors commencez, persévérez, triomphez !","writing_checklist":["anaphore, gradation, question rhétorique, chiasme","apostrophe à l''auditoire","élan final vers l''action"],"email_snippet":{"word_of_day":{"fr":"l''anaphore (f.)","en":"anaphora","example":"« Moi président… » est une anaphore célèbre."},"mini_question":{"prompt":"« Il faut manger pour vivre et non vivre pour manger » est :","options":["une anaphore","un chiasme","une gradation","une litote"],"answer":"un chiasme"}}}'::jsonb, 'approved', 'curriculum')
